#pragma once

// Binary identity.
//
// The C++20 and C++23 builds are not ABI-compatible: every type that carries a
// result differs in layout because the underlying expected differs. Linking
// objects from both produces a program that appears to build and then reads the
// wrong bytes.
//
// An inline namespace whose name encodes the ABI revision and expected choice
// makes incompatibility a link error. Callers still write `libtmux::Server`;
// the namespace is inline in source and decisive in the mangled name.

#include "libtmux/expected.hpp"

#if defined(LIBTMUX_USE_TL_EXPECTED)
#define LIBTMUX_ABI_NAMESPACE v2_cxx20
#else
#define LIBTMUX_ABI_NAMESPACE v2_cxx23
#endif

#define LIBTMUX_NAMESPACE_BEGIN                                                        \
  namespace libtmux {                                                                  \
  inline namespace LIBTMUX_ABI_NAMESPACE {

#define LIBTMUX_NAMESPACE_END                                                          \
  }                                                                                    \
  }

include/libtmux/async.hpp.content:
#pragma once

// Explicit bounded ownership for asynchronous Server commands.
// Results and global observations remain independent after admission.

#include "libtmux/abi.hpp"

#include "libtmux/command.hpp"
#include "libtmux/expected.hpp"
#include <chrono>
#include <cstddef>
#include <cstdint>
#include <functional>
#include <memory>
#include <optional>
#include <string>
#include <utility>
#include <version>

#if defined(__cpp_lib_jthread) && __cpp_lib_jthread >= 201911L
#include <stop_token>
#endif

LIBTMUX_NAMESPACE_BEGIN

class Server;

enum class ReadyStatus : std::uint8_t { ready, timeout, closed };

/// The maximum number of accepted commands retaining any lifecycle leg.
/// `start` rejects zero with `DeliveryStatus::not_started`.
/// How many commands the runtime will admit at once.
struct CommandRuntimeConfig final {
  std::size_t capacity{256U};
};

/// A lock-consistent instant; values may change immediately after it is read.
/// Admission, refusal, and completion totals are monotonic.
/// The runtime's counters at one instant, for diagnostics rather than control.
///
/// Read under a lock and stale immediately after, so a caller must not branch
/// on `in_flight` expecting it to still hold. The totals only ever increase.
struct CommandRuntimeSnapshot final {
  std::size_t capacity{};
  /// Accepted commands retaining transport, result, or observer work.
  std::size_t in_flight{};
  /// Result handles not yet waited, detached, or destroyed.
  std::size_t pending_results{};
  /// Observer records not yet claimed for dispatch or discarded, ready or not.
  std::size_t pending_observers{};
  /// Commands admitted since startup.
  std::uint64_t accepted{};
  /// Commands refused before admission since startup.
  std::uint64_t refused{};
  /// Accepted results whose observer record, when present, is also ready.
  std::uint64_t completed{};
  /// True while neither stop nor close has ended admission.
  bool accepting{};
};

/// The first successful `close` report; every later call returns this value.
/// Discharge result and observer work first when `safe_to_unload` must be true.
struct CommandRuntimeShutdown final {
  /// Result obligations outstanding when the first close succeeded.
  std::size_t pending_results{};
  /// Observer obligations outstanding when the first close succeeded.
  std::size_t pending_observers{};
  /// Whether every owned child and transport thread retired.
  bool transports_stopped{};
  /// True only when transports and pending work ended and no caller-side
  /// readiness wait, dispatch or discard, including callback-target teardown,
  /// remains active.
  /// Callers must prevent concurrent or later runtime entry before unloading.
  bool safe_to_unload{};
  /// The first runtime lifecycle failure; an operation may also carry it.
  std::optional<CommandFailure> failure;
};

/// Move-only owner of the transport threads, admission bound, and observations.
/// Runtime operations, including `try_submit`, may race; move and destruction
/// may not.
class CommandRuntime final {
public:
  /// Starts the bounded transport; startup failures are not-started values.
  static expected<CommandRuntime, CommandFailure>
  start(CommandRuntimeConfig config = {});
  CommandRuntime(CommandRuntime&&) noexcept;
  CommandRuntime& operator=(CommandRuntime&&) noexcept;
  CommandRuntime(const CommandRuntime&) = delete;
  CommandRuntime& operator=(const CommandRuntime&) = delete;
  /// Stops and joins owned threads; pending observers are discarded, not
  /// invoked.
  /// Call `close` first when its terminal report matters.
  ~CommandRuntime();

  /// Stops admission and requests cancellation without waiting.
  void request_stop() noexcept;
  /// Joins every owned thread without invoking or discarding observers, and
  /// does not return or throw until every blocked `wait_ready` caller has left.
  /// The first successful report is cached; a throwing shutdown can be retried.
  [[nodiscard]] CommandRuntimeShutdown close();
  /// Reads one lock-consistent instant without waiting for work.
  [[nodiscard]] CommandRuntimeSnapshot snapshot() const noexcept;
  /// Waits for a ready observer without invoking it. `closed` means close has
  /// joined the transports and no ready observers remain, or this owner was moved.
  /// Ready records take precedence over closure and deadline expiry.
  [[nodiscard]] ReadyStatus
  wait_ready(std::chrono::steady_clock::time_point deadline =
                 std::chrono::steady_clock::time_point::max());
  [[nodiscard]] ReadyStatus wait_ready_for(std::chrono::milliseconds timeout);
  /// Runs one snapshot of ready observers on this thread and returns its count.
  /// A callback exception releases that record, propagates, and leaves later
  /// records.
  [[nodiscard]] std::size_t dispatch_ready();
  /// Releases ready observer obligations without invoking callbacks.
  /// Only one dispatch or discard call runs at once; competitors return zero.
  [[nodiscard]] std::size_t discard_ready();

  /// Readable exactly when `wait_ready` would return without blocking, for a
  /// caller that owns an event loop and cannot park a thread in `wait_ready`.
  /// The same contract as `Connection::notification_fd`:
  ///
  ///   - Readability is the signal. Do not read from it: the byte carries
  ///     nothing and is this runtime's to consume. Drain by taking the work —
  ///     `dispatch_ready` or `discard_ready` — which clears it.
  ///   - A closed runtime makes it readable, so a poller learns that no answer
  ///     is coming rather than waiting for one.
  ///   - Valid until this runtime is destroyed or moved from. `-1` when the
  ///     pipe could not be created, and on Windows, where the runtime has no
  ///     descriptor to offer; a caller that gets `-1` uses `wait_ready`.
  [[nodiscard]] int ready_fd() const noexcept;

private:
  struct State;
  explicit CommandRuntime(std::unique_ptr<State> state) noexcept;
  friend class Server;

  std::unique_ptr<State> state_;
};

/// Move-only result handle for one admitted command; its methods are not
/// concurrent. Destruction releases its result without cancelling the command.
/// It may outlive the runtime without retaining runtime threads.
class CommandOperation final {
public:
  CommandOperation(CommandOperation&& other) noexcept;
  CommandOperation& operator=(CommandOperation&& other) noexcept;
  CommandOperation(const CommandOperation&) = delete;
  CommandOperation& operator=(const CommandOperation&) = delete;
  ~CommandOperation();

  /// Consumes the same bounded answer `Server::run` gives.
  /// Waiting never dispatches the Server's global observer.
  [[nodiscard]] expected<std::string, CommandFailure> wait() &&;

  /// True means the result can be taken; false means only this wait expired.
  /// Neither outcome consumes the handle or changes the command's deadline.
  /// A consumed or moved-from handle reports FailureKind::validation.
  [[nodiscard]] expected<bool, CommandFailure>
  wait_until(std::chrono::steady_clock::time_point deadline) const;
  [[nodiscard]] expected<bool, CommandFailure>
  wait_for(std::chrono::milliseconds timeout) const;

#if defined(__cpp_lib_jthread) && __cpp_lib_jthread >= 201911L
  /// These three overloads exist only where the standard library provides
  /// `std::stop_token`. libstdc++ does; libc++ does not without
  /// `-fexperimental-library`, and this package pins clang with libc++ — so a
  /// default build of it has no `stop_token` overload at all, and a caller
  /// reaching for one meets "no matching member function" rather than anything
  /// that explains itself. Every non-token overload below is always present,
  /// and `cancel()` is the portable way to withdraw a wait.
  ///
  /// The token requests transport cancellation only during this wait; it
  /// cannot undo tmux work. The eventual result retains its command failure
  /// and delivery status.
  [[nodiscard]] expected<std::string, CommandFailure> wait(std::stop_token stop) && {
    const std::stop_callback cancellation{stop, cancellation_callback()};
    return std::move(*this).wait();
  }
  [[nodiscard]] expected<bool, CommandFailure>
  wait_until(std::chrono::steady_clock::time_point deadline,
             std::stop_token stop) const {
    const std::stop_callback cancellation{stop, cancellation_callback()};
    return wait_until(deadline);
  }
  [[nodiscard]] expected<bool, CommandFailure>
  wait_for(std::chrono::milliseconds timeout, std::stop_token stop) const {
    const std::stop_callback cancellation{stop, cancellation_callback()};
    return wait_for(timeout);
  }
#endif

  /// Releases the result obligation without cancelling the command.
  /// The Server's global observer remains a runtime obligation.
  void detach() && noexcept;

  /// Requests withdrawal; false means no live transport cancellation remains.
  /// The eventual result's delivery says whether tmux may have acted.
  [[nodiscard]] bool request_cancel();

private:
  struct State;
  explicit CommandOperation(std::unique_ptr<State> state) noexcept;
  [[nodiscard]] std::function<void()> cancellation_callback() const;
  friend class CommandRuntime;
  friend class Server;

  std::unique_ptr<State> state_;
};

LIBTMUX_NAMESPACE_END

include/libtmux/batch.hpp.content:
#pragma once

// Build one tmux command sequence from several commands.
//
// tmux accepts multiple commands in a single invocation separated by a `;`
// argument. Because the core execs argv directly and never goes through a
// shell, the separator is a bare `;` element — there is no backslash to escape
// and no quoting to get wrong.
//
// A batch is one fail-fast group: tmux stops at the first command that errors.
// That is why a batch is a distinct type from a list of independent requests,
// which the transport runs separately and attributes individually.

#include "libtmux/abi.hpp"
#include "libtmux/command.hpp"
#include <cstddef>
#include <string>
#include <utility>
#include <vector>

LIBTMUX_NAMESPACE_BEGIN

inline constexpr std::string_view kCommandSeparator = ";";

/// The argv a chain becomes: commands joined by tmux's separator.
///
/// An empty command is rejected rather than emitted, because tmux reads two
/// adjacent separators as the next command's first argument.
class CommandBatch {
public:
  /// Append one command. An empty command is rejected rather than emitted,
  /// because an empty argv between separators makes tmux read the next
  /// command's name as an argument.
  bool add(CommandRequest command) {
    if (command.empty()) {
      return false;
    }
    commands_.push_back(std::move(command));
    return true;
  }

  [[nodiscard]] std::size_t size() const noexcept { return commands_.size(); }
  [[nodiscard]] bool empty() const noexcept { return commands_.empty(); }

  /// Render the whole batch as one argv. A single command renders with no
  /// separator, so a batch of one is byte-identical to running it alone.
  [[nodiscard]] CommandRequest request() const {
    CommandRequest result;
    for (const CommandRequest& command : commands_) {
      if (!result.empty()) {
        result.emplace_back(kCommandSeparator);
      }
      for (const CommandArgument& argument : command.arguments()) {
        result.push_back(argument);
      }
    }
    return result;
  }

  [[nodiscard]] std::vector<std::string> argv() const { return request().argv(); }

  [[nodiscard]] const std::vector<CommandRequest>& commands() const noexcept {
    return commands_;
  }

private:
  std::vector<CommandRequest> commands_;
};

LIBTMUX_NAMESPACE_END

include/libtmux/capabilities.hpp.content:
#pragma once

// What this Server can promise without probing tmux.
//
// These describe the local backend contract, not the executable on PATH.
// An unrecognised backend reports no features, so every check says no.

#include "libtmux/abi.hpp"
#include <string_view>

LIBTMUX_NAMESPACE_BEGIN

/// Which server answered: tmux, a compatible reimplementation, or not yet
/// determined.
enum class ServerImplementation {
  unknown,
  tmux,
  psmux,
};

[[nodiscard]] constexpr std::string_view
to_string(ServerImplementation implementation) noexcept {
  switch (implementation) {
  case ServerImplementation::unknown:
    return "unknown";
  case ServerImplementation::tmux:
    return "tmux";
  case ServerImplementation::psmux:
    return "psmux";
  }
  return "unknown";
}

/// How commands reach the server: by spawning a process, or through a backend
/// the caller supplied.
enum class BackendKind {
  custom,
  subprocess,
  /// Held-open control clients, with a launch for what they cannot answer
  /// completely. Appended: the values before it are an installed ABI.
  control,
};

[[nodiscard]] constexpr std::string_view to_string(BackendKind backend) noexcept {
  switch (backend) {
  case BackendKind::custom:
    return "custom";
  case BackendKind::subprocess:
    return "subprocess";
  case BackendKind::control:
    return "control";
  }
  return "unknown";
}

/// Coarse-grained promises callers choose around. Raw commands remain unchecked;
/// the psmux preview promises only exact inspection and namespace cleanup.
enum class ServerFeature {
  /// Exact session/window/pane listings, traversal, refresh, and format reads.
  exact_inspection,
  /// Cleanup of the selected namespace under the Server's execution policy.
  server_cleanup,
  /// `Server::window` and `Server::pane` without an owning session handle.
  server_entity_lookup,
  /// Typed session creation with an attributable result.
  session_creation,
  /// Typed window creation with an attributable result.
  window_creation,
  /// Mutating an object captured in an earlier snapshot.
  captured_mutation,
  /// Pane input, capture, copy mode, history, and piping.
  pane_io,
  /// Producing argv that attaches a caller-owned terminal to a session.
  terminal_attach,
  /// A reusable public target that identifies one captured window link.
  reusable_window_target,
  /// Clients, buffers, commands, configuration, options, and hooks.
  server_state,
  /// Latched `wait-for` channels.
  wait_channels,
  /// This Server can open a persistent control connection.
  control_mode,
};

[[nodiscard]] constexpr std::string_view to_string(ServerFeature feature) noexcept {
  switch (feature) {
  case ServerFeature::exact_inspection:
    return "exact inspection";
  case ServerFeature::server_cleanup:
    return "server cleanup";
  case ServerFeature::server_entity_lookup:
    return "server-wide entity lookup";
  case ServerFeature::session_creation:
    return "session creation";
  case ServerFeature::window_creation:
    return "window creation";
  case ServerFeature::captured_mutation:
    return "captured entity mutation";
  case ServerFeature::pane_io:
    return "pane input and output";
  case ServerFeature::terminal_attach:
    return "terminal attachment";
  case ServerFeature::reusable_window_target:
    return "reusable window targets";
  case ServerFeature::server_state:
    return "server-scoped state";
  case ServerFeature::wait_channels:
    return "wait channels";
  case ServerFeature::control_mode:
    return "control mode";
  }
  return "unknown feature";
}

/// What this server is known to support, decided without asking it.
///
/// Every query here is local: the implementation and backend were established
/// once, and answering from them costs no process and cannot fail.
struct ServerCapabilities {
  ServerImplementation implementation{ServerImplementation::unknown};
  BackendKind backend{BackendKind::custom};

  /// Purely local: this never launches tmux or touches a server.
  [[nodiscard]] constexpr bool supports(ServerFeature feature) const noexcept {
    if (implementation == ServerImplementation::unknown) {
      return false;
    }
    switch (feature) {
    case ServerFeature::exact_inspection:
    case ServerFeature::server_cleanup:
      return true;
    case ServerFeature::server_entity_lookup:
    case ServerFeature::session_creation:
    case ServerFeature::window_creation:
    case ServerFeature::captured_mutation:
    case ServerFeature::pane_io:
    case ServerFeature::terminal_attach:
    case ServerFeature::reusable_window_target:
    case ServerFeature::server_state:
    case ServerFeature::wait_channels:
    case ServerFeature::control_mode:
      return implementation == ServerImplementation::tmux;
    }
    return false;
  }

  /// Whether this implementation is known to get the feature wrong, which is
  /// the opposite question from `supports` rather than its negation. Both
  /// answer no for a backend nobody recognises: a caller asking what it may
  /// rely on must not be promised anything, and a custom executor running real
  /// tmux must not be refused for being unfamiliar.
  [[nodiscard]] constexpr bool refuses(ServerFeature feature) const noexcept {
    return implementation != ServerImplementation::unknown && !supports(feature);
  }
};

LIBTMUX_NAMESPACE_END

include/libtmux/capture.hpp.content:
#pragma once

// Split `capture-pane -p` output into lines.
//
// Every captured line is newline-terminated, so a naive split on '\n' yields a
// final empty element that is not a line. Blank rows inside the pane are
// genuine empty lines and must survive, which is why the terminator is removed
// by dropping exactly one trailing element rather than by trimming empties.
//
// `-p` already strips trailing whitespace from each line; `-N` preserves it.
// Neither is re-implemented here: the caller chooses the flag and this only
// frames what tmux returned.

#include "libtmux/abi.hpp"
#include <concepts>
#include <string>
#include <string_view>
#include <type_traits>
#include <vector>

LIBTMUX_NAMESPACE_BEGIN

/// The lines are views into the text, so text that dies at the semicolon takes
/// them with it — and `pane.capture()` returns its output by value, which makes
/// `capture_lines(*pane.capture())` the natural thing to write and a
/// use-after-free to run. Deleted for an rvalue string only: an lvalue string
/// converts as before, and so does a literal.
template <typename Text>
  requires std::same_as<std::remove_cvref_t<Text>, std::string> &&
               (!std::is_lvalue_reference_v<Text>)
std::vector<std::string_view> capture_lines(Text&&) = delete;

[[nodiscard]] inline std::vector<std::string_view>
capture_lines(std::string_view output) {
  std::vector<std::string_view> lines;
  if (output.empty()) {
    return lines;
  }
  std::size_t position = 0;
  while (position <= output.size()) {
    const std::size_t end = output.find('\n', position);
    if (end == std::string_view::npos) {
      lines.push_back(output.substr(position));
      break;
    }
    lines.push_back(output.substr(position, end - position));
    position = end + 1;
    // A terminator at the very end closes the last line rather than opening
    // an empty one.
    if (position == output.size()) {
      break;
    }
  }
  return lines;
}

/// Drop the blank rows a pane pads its height with, keeping blank lines that
/// have content below them.
[[nodiscard]] inline std::vector<std::string_view>
without_trailing_blanks(std::vector<std::string_view> lines) {
  while (!lines.empty() && lines.back().empty()) {
    lines.pop_back();
  }
  return lines;
}

namespace detail {

[[nodiscard]] constexpr bool is_word_byte(unsigned char byte) noexcept {
  return (byte >= 'a' && byte <= 'z') || (byte >= 'A' && byte <= 'Z') ||
         (byte >= '0' && byte <= '9') || byte == '_';
}

// ASCII word boundaries preserve a short answer inside a longer output word.
[[nodiscard]] inline std::string mask_whole_occurrences(std::string_view text,
                                                        std::string_view echo) {
  if (echo.empty() || text.empty()) {
    return std::string{text};
  }
  std::string result;
  std::size_t cursor = 0;
  std::size_t from = 0;
  for (;;) {
    const std::size_t at = text.find(echo, from);
    if (at == std::string_view::npos) {
      break;
    }
    const std::size_t end = at + echo.size();
    const bool opens = at == 0 ||
                       !is_word_byte(static_cast<unsigned char>(text[at - 1])) ||
                       !is_word_byte(static_cast<unsigned char>(echo.front()));
    const bool closes = end == text.size() ||
                        !is_word_byte(static_cast<unsigned char>(text[end])) ||
                        !is_word_byte(static_cast<unsigned char>(echo.back()));
    if (opens && closes) {
      result.append(text.substr(cursor, at - cursor));
      cursor = end;
      from = end;
    } else {
      from = at + 1;
    }
  }
  result.append(text.substr(cursor));
  return result;
}

} // namespace detail

/// Whether `wanted` appears in captured text as something the pane produced,
/// rather than as text that is merely on screen.
///
/// Waiting for a pane to say something is the first thing a supervising program
/// needs and the easiest to get wrong, because a capture shows two things that
/// are not output. The first is a command still sitting on the prompt: it has
/// been typed, nothing has run it, and searching for it succeeds immediately.
/// The second is its echo. A shell echoes typed input at least once — the
/// kernel's own cooked-mode echo — and often twice more before anything runs,
/// from the line editor's redisplay and from any unrelated repaint. None of
/// those are output, however many rows they end up spread across.
///
/// `sent` is what the calling program itself typed into this pane and has not
/// had confirmed. Every whole occurrence of every entry is masked before
/// `wanted` is looked for, so an echo cannot be credited to the pane no matter
/// where a redraw moved it, and a short entry cannot corrupt a longer real
/// word that merely contains it. That is the check row position alone misses:
/// the same unsubmitted line, unchanged, after something else pushed it off
/// the last row without the pane having produced anything.
///
[[nodiscard]] inline bool output_confirms(std::string_view captured,
                                          std::string_view wanted,
                                          const std::vector<std::string>& sent = {}) {
  if (wanted.empty()) {
    return false;
  }
  // A match confined to the row the cursor is on is a command waiting to run.
  std::string_view settled = captured;
  while (!settled.empty() && settled.back() == '\n') {
    settled.remove_suffix(1);
  }
  const auto last_newline = settled.find_last_of('\n');
  const std::string_view active_row = last_newline == std::string_view::npos
                                          ? settled
                                          : settled.substr(last_newline + 1);
  const std::string_view above = last_newline == std::string_view::npos
                                     ? std::string_view{}
                                     : settled.substr(0, last_newline);
  if (active_row.find(wanted) != std::string_view::npos &&
      above.find(wanted) == std::string_view::npos) {
    return false;
  }

  std::string masked{captured};
  for (const std::string& entry : sent) {
    masked = detail::mask_whole_occurrences(masked, entry);
  }
  return masked.find(wanted) != std::string::npos;
}

LIBTMUX_NAMESPACE_END

include/libtmux/cardinality.hpp.content:
#pragma once

// Exception-free cardinality over snapshot views.
//
// Callers ask for one entity far more often than they want to handle a range,
// and the two ways that request can fail are not the same failure: finding
// nothing is ordinary, finding several means the caller's filter was wrong.
// These return types keep both outcomes in the value channel.

#include "libtmux/abi.hpp"
#include "libtmux/expected.hpp"
#include <concepts>
#include <functional>
#include <memory>
#include <optional>
#include <ranges>
#include <string_view>
#include <type_traits>

LIBTMUX_NAMESPACE_BEGIN

/// Why a lookup that required exactly one match did not get one.
///
/// The two want opposite fixes, which is why they are distinct: one needs
/// wider criteria and the other needs narrower.
enum class CardinalityError { none_matched, several_matched };

[[nodiscard]] constexpr std::string_view to_string(CardinalityError error) noexcept {
  switch (error) {
  case CardinalityError::none_matched:
    return "nothing matched";
  case CardinalityError::several_matched:
    return "several matched where one was required";
  }
  return "unknown cardinality error";
}

template <std::ranges::input_range Range>
/// A borrowed element of a range, rather than a copy of it.
///
/// These lookups reference an element of the range they were given, so the
/// range has to outlive the result. That is why they take an lvalue.
using Referenced = std::reference_wrapper<const std::ranges::range_value_t<Range>>;

// Both take an lvalue on purpose. The result references an element of the
// range, so binding a temporary here — a pipeline over an owning view, or a
// list returned by value — leaves that reference dangling at the semicolon.
// Requiring a name makes the storage the caller must keep alive visible.

/// Both also require the range to yield references. A range whose elements are
/// produced on demand — a transform that returns by value, say — has nothing
/// for the answer to refer to, and the temporary dies with the call.
template <typename Range>
concept ReferenceRange =
    std::ranges::input_range<Range> &&
    std::is_lvalue_reference_v<std::ranges::range_reference_t<Range>>;

/// `first` states that a caller tolerates extras; it never reports several.
template <ReferenceRange Range>
[[nodiscard]] std::optional<Referenced<Range>> first(Range& range) {
  auto iterator = std::ranges::begin(range);
  if (iterator == std::ranges::end(range)) {
    return std::nullopt;
  }
  return std::cref(*iterator);
}

/// `exactly_one` states that several is a caller error, and says which one.
template <ReferenceRange Range>
[[nodiscard]] expected<Referenced<Range>, CardinalityError> exactly_one(Range& range) {
  auto iterator = std::ranges::begin(range);
  const auto last = std::ranges::end(range);
  if (iterator == last) {
    return unexpected(CardinalityError::none_matched);
  }
  // A pointer, not a reference: binding `const auto&` to `*iterator` would
  // extend the lifetime of anything the range produced on demand, and then
  // return a reference to it. The constraint rules that range out; taking the
  // address says so at the one line where it would have mattered.
  const auto* only = std::addressof(*iterator);
  if (++iterator != last) {
    return unexpected(CardinalityError::several_matched);
  }
  return std::cref(*only);
}

/// Copies referenced elements; moves when an iterator yields an rvalue. A
/// temporary view over an lvalue container therefore leaves that container intact.
/// Owning the element does not extend storage borrowed by its own members.
template <std::ranges::input_range Range>
  requires std::constructible_from<std::ranges::range_value_t<Range>,
                                   std::ranges::range_reference_t<Range>>
[[nodiscard]] std::optional<std::ranges::range_value_t<Range>>
first_owned(Range&& range) {
  auto iterator = std::ranges::begin(range);
  if (iterator == std::ranges::end(range)) {
    return std::nullopt;
  }
  return std::optional<std::ranges::range_value_t<Range>>{std::in_place, *iterator};
}

/// A forward range's iterator can be copied and advanced independently of the
/// original, so a second element rules the range out before the first is
/// materialized. A single-pass range (a stream, a generator) shares mutable
/// state between copies instead, so it has no way to look ahead: the first
/// element must be materialized before the range can be advanced to check for
/// a second, and an error there still consumes it.
template <std::ranges::input_range Range>
  requires std::constructible_from<std::ranges::range_value_t<Range>,
                                   std::ranges::range_reference_t<Range>> &&
           std::move_constructible<std::ranges::range_value_t<Range>>
[[nodiscard]] expected<std::ranges::range_value_t<Range>, CardinalityError>
exactly_one_owned(Range&& range) {
  auto iterator = std::ranges::begin(range);
  const auto last = std::ranges::end(range);
  if (iterator == last) {
    return unexpected(CardinalityError::none_matched);
  }
  if constexpr (std::ranges::forward_range<Range>) {
    auto second = iterator;
    if (++second != last) {
      return unexpected(CardinalityError::several_matched);
    }
    return std::ranges::range_value_t<Range>(*iterator);
  } else {
    std::ranges::range_value_t<Range> only(*iterator);
    if (++iterator != last) {
      return unexpected(CardinalityError::several_matched);
    }
    return only;
  }
}

LIBTMUX_NAMESPACE_END

include/libtmux/chain.hpp.content:
#pragma once

// Compose several tmux commands as one fail-fast group.
//
// A chain is a typed front for a batch: each step validates its own arguments
// as it is added, so a bad target or key name is reported where it was written
// rather than as a tmux message about a command the caller cannot see.
//
// The chain records the first validation failure and stops accumulating. That
// keeps the fluent form honest — the alternative, throwing mid-expression or
// silently dropping a step, both leave the caller guessing which parts ran.

#include <string>
#include <string_view>
#include <utility>
#include <vector>

#include "libtmux/abi.hpp"
#include "libtmux/batch.hpp"
#include "libtmux/keys.hpp"
#include "libtmux/target.hpp"

LIBTMUX_NAMESPACE_BEGIN

/// Several commands built up and sent as one tmux invocation.
///
/// tmux runs a chain until a command fails and discards the rest, so the chain
/// is the unit of atomicity a caller gets — and the reply count alone cannot
/// say which command failed.
class Chain {
public:
  Chain& new_session(std::string_view name, bool detached = true) {
    const auto target = session_target(name);
    if (!target.has_value()) {
      return fail("session name cannot address itself");
    }
    std::vector<std::string> command{"new-session", "-s", *target};
    if (detached) {
      command.emplace_back("-d");
    }
    return add(std::move(command));
  }

  Chain& new_window(std::string_view session, std::string_view name) {
    const auto target = session_target(session);
    if (!target.has_value()) {
      return fail("session name cannot address itself");
    }
    if (!path_component(name).has_value()) {
      return fail("window name cannot address itself");
    }
    return add({"new-window", "-t", *target, "-n", std::string{name}});
  }

  Chain& split_window(std::string_view session, std::string_view window) {
    const auto target = window_target(session, window);
    if (!target.has_value()) {
      return fail("window target cannot be addressed");
    }
    return add({"split-window", "-t", *target});
  }

  /// Literal text, never interpreted as key names or formats.
  Chain& send_text(std::string_view target, std::string_view text) {
    const auto arguments = literal_arguments(text);
    if (!arguments.has_value()) {
      return fail("text to send is empty");
    }
    std::vector<std::string> command{"send-keys", "-t", std::string{target}};
    command.insert(command.end(), arguments->begin(), arguments->end());
    return add(std::move(command));
  }

  Chain& send_key(std::string_view target, std::string_view key) {
    if (!is_key_name(key)) {
      return fail("unknown key name: " + std::string{key});
    }
    return add({"send-keys", "-t", std::string{target}, std::string{key}});
  }

  /// Escape hatch for a command the typed steps do not cover.
  Chain& command(std::vector<std::string> argv) { return add(std::move(argv)); }

  [[nodiscard]] bool valid() const noexcept { return error_.empty(); }
  [[nodiscard]] const std::string& error() const noexcept { return error_; }
  [[nodiscard]] const CommandBatch& batch() const noexcept { return batch_; }

private:
  Chain& add(std::vector<std::string> command) {
    if (error_.empty() && !batch_.add(std::move(command))) {
      error_ = "empty command";
    }
    return *this;
  }

  Chain& fail(std::string reason) {
    if (error_.empty()) {
      error_ = std::move(reason);
    }
    return *this;
  }

  CommandBatch batch_;
  std::string error_;
};

LIBTMUX_NAMESPACE_END

