#pragma once

// Why a tmux command produced no answer.
//
// `refused` means tmux ran and said no; `missing` means tmux ran, said yes,
// and the object asked about was not there; `truncated` means it answered at
// greater length than the caller allowed for. `unsupported` is a backend
// feature gap; `validation` is a bad request, so callers handle them
// differently.

#include "libtmux/abi.hpp"
#include "libtmux/delivery.hpp"
#include <chrono>
#include <cstddef>
#include <cstdint>
#include <filesystem>
#include <format>
#include <functional>
#include <initializer_list>
#include <optional>
#include <span>
#include <string>
#include <string_view>
#include <utility>
#include <vector>

LIBTMUX_NAMESPACE_BEGIN

/// Why a command did not produce an answer, in the order a caller would
/// diagnose them: bad before it left, then how it left, then what came back.
enum class FailureKind {
  validation,
  spawn,
  pre_exec,
  pipe,
  timeout,
  refused,
  missing,
  /// tmux ran and answered, and the answer did not fit. Reported rather than
  /// returned, because a truncated answer is indistinguishable from a complete
  /// one: the last line is simply cut, mid-word.
  truncated,
  /// The backend cannot provide this operation without weakening its contract;
  /// nothing was dispatched.
  unsupported,
  /// More work is in flight than the engine accepts. Nothing was dispatched, so
  /// this is the one refusal a caller may simply try again later — appended
  /// rather than grouped, because the values before it are an installed ABI.
  overloaded,
  /// The caller withdrew the call. Whether tmux acted is a separate question,
  /// and `delivery` is what answers it: a cancellation accepted before dispatch
  /// is not_started, and one accepted after the command was written is not.
  cancelled,
};

[[nodiscard]] constexpr std::string_view to_string(FailureKind kind) noexcept {
  switch (kind) {
  case FailureKind::validation:
    return "the request was rejected before tmux ran";
  case FailureKind::spawn:
    return "tmux could not be started";
  case FailureKind::pre_exec:
    return "the child failed before reaching tmux";
  case FailureKind::pipe:
    return "the transport failed";
  case FailureKind::timeout:
    return "tmux did not answer in time";
  case FailureKind::refused:
    return "tmux refused the command";
  case FailureKind::missing:
    return "tmux has no such object";
  case FailureKind::truncated:
    return "the answer did not fit";
  case FailureKind::unsupported:
    return "the backend does not support this operation";
  case FailureKind::overloaded:
    return "the engine has more work in flight than it accepts";
  case FailureKind::cancelled:
    return "the caller withdrew the command";
  }
  return "unknown failure";
}

/// A command that did not produce an answer, and how far it got.
///
/// `delivery` is the part that decides whether retrying is safe; `kind` and
/// `diagnostic` say what to fix.
struct CommandFailure {
  FailureKind kind{FailureKind::refused};
  /// How far the command is known to have progressed. Only `not_started` is
  /// safe to retry blindly.
  DeliveryStatus delivery{DeliveryStatus::not_started};
  int exit_code{};
  std::string diagnostic;
};

/// One line naming what happened, what tmux said, and — through the delivery
/// status — whether the call is safe to repeat.
[[nodiscard]] inline std::string to_string(const CommandFailure& failure) {
  std::string text{to_string(failure.kind)};
  if (!failure.diagnostic.empty()) {
    text += ": ";
    text += failure.diagnostic;
  }
  text += " (";
  // Only a command tmux answered has an exit status, and even then a child
  // that died from a signal has none: the transport writes -1 for the absence
  // of a status in both cases. The sign cannot stand in for that test, because
  // a Windows child reports its status through an int32_t and a crash is
  // legitimately negative.
  if (failure.delivery == DeliveryStatus::replied && failure.exit_code != 0 &&
      failure.exit_code != -1) {
    text += "exit ";
    text += std::to_string(failure.exit_code);
    text += ", ";
  }
  text += to_string(failure.delivery);
  text += ')';
  return text;
}

/// Whether an argument may appear in a diagnostic, a log, or an error message.
enum class ArgumentSensitivity : std::uint8_t { public_value, secret };

/// One argument, carrying whether any part of it is a secret.
///
/// Implicitly constructible from the string types so building a command reads
/// as a list of words; marking a part secret is the deliberate act.
class CommandArgument {
public:
  CommandArgument(const char* value) : value_{value} {}
  CommandArgument(std::string value) : value_{std::move(value)} {}
  CommandArgument(std::string_view value) : value_{value} {}

  [[nodiscard]] static CommandArgument sensitive(std::string value) {
    CommandArgument argument{std::move(value)};
    if (!argument.value_.empty()) {
      argument.sensitive_parts_.push_back(argument.value_);
    }
    return argument;
  }

  /// Keep a composite argument intact on the wire while treating one byte
  /// range inside it as sensitive. An invalid range hides the whole argument.
  [[nodiscard]] static CommandArgument
  sensitive_range(std::string value, std::size_t offset, std::size_t size) {
    CommandArgument argument{std::move(value)};
    if (offset > argument.value_.size() || size > argument.value_.size() - offset) {
      argument.sensitive_parts_.push_back(argument.value_);
      return argument;
    }
    if (size == 0U) {
      return argument;
    }
    argument.sensitive_parts_.push_back(argument.value_.substr(offset, size));
    return argument;
  }

  [[nodiscard]] const std::string& value() const noexcept { return value_; }
  [[nodiscard]] ArgumentSensitivity sensitivity() const noexcept {
    return sensitive_parts_.empty() ? ArgumentSensitivity::public_value
                                    : ArgumentSensitivity::secret;
  }
  [[nodiscard]] const std::vector<std::string>& sensitive_parts() const noexcept {
    return sensitive_parts_;
  }

private:
  std::string value_;
  std::vector<std::string> sensitive_parts_;
};

/// One tmux command as argv, with no shell between it and tmux.
///
/// Arguments are passed as separate words, so a value holding a space, a quote
/// or a `;` arrives whole and nothing here needs escaping.
class CommandRequest {
public:
  CommandRequest() = default;
  CommandRequest(std::initializer_list<CommandArgument> arguments)
      : arguments_{arguments} {}
  CommandRequest(std::vector<std::string> arguments) {
    arguments_.reserve(arguments.size());
    for (std::string& argument : arguments) {
      arguments_.emplace_back(std::move(argument));
    }
  }

  [[nodiscard]] bool empty() const noexcept { return arguments_.empty(); }
  [[nodiscard]] std::size_t size() const noexcept { return arguments_.size(); }
  void reserve(std::size_t size) { arguments_.reserve(size); }

  void emplace_back(const char* value) { arguments_.emplace_back(value); }
  void emplace_back(std::string value) { arguments_.emplace_back(std::move(value)); }
  void emplace_back(std::string_view value) { arguments_.emplace_back(value); }
  void push_back(CommandArgument argument) {
    arguments_.push_back(std::move(argument));
  }

  [[nodiscard]] const std::vector<CommandArgument>& arguments() const noexcept {
    return arguments_;
  }
  [[nodiscard]] std::vector<std::string> argv() const {
    std::vector<std::string> result;
    result.reserve(arguments_.size());
    for (const CommandArgument& argument : arguments_) {
      result.push_back(argument.value());
    }
    return result;
  }

private:
  std::vector<CommandArgument> arguments_;
};

/// Told about every command, as it finishes.
///
/// There is otherwise no way to see what this library ran: a caller debugging a
/// tmux interaction has only the failures, and nothing at all when things
/// succeed. The command is rendered as tmux received it, with any argument
/// marked sensitive replaced.
///
/// Synchronous calls invoke it on their caller's thread. Asynchronous calls
/// invoke it only on the thread calling `CommandRuntime::dispatch_ready`.
/// No internal lock is held; a shared observer must synchronise itself.
struct CommandReport {
  /// As tmux received it, with any argument marked sensitive replaced. For a
  /// human reading a log.
  std::string_view command;
  /// The same command unrendered, for a caller building structured telemetry
  /// rather than a line of text. Empty when the report has no argv to give.
  std::span<const std::string> argv;
  /// Nothing when the command succeeded.
  const CommandFailure* failure;
  /// How long the command took, measured around its dispatch. Absent when
  /// nothing was dispatched — a request rejected before it ran took no time,
  /// and reporting zero would read as an immeasurably fast command.
  std::optional<std::chrono::nanoseconds> elapsed;
};

/// Every member expires on return; a caller keeping any of it copies it.
using CommandObserver = std::function<void(const CommandReport&)>;

/// What a call waits and holds when the caller did not say.
///
/// A timeout on the call is still how a caller says "this one in particular":
/// listing sessions does not share a deadline with attaching a client. What was
/// missing was a floor. Typed methods passed no timeout at all, so
/// `window.rename(...)` waited for as long as the process ran if tmux never
/// answered — and "tmux is normally fast" is not a liveness guarantee when a
/// hook blocks, a filesystem stops answering, or a connection breaks without
/// closing the pipe.
///
/// Thirty seconds is far past every tmux command that works and far short of
/// forever. `wait_for` opts out, because waiting is the whole request.
struct ExecutionPolicy {
  /// Absent means wait. That is a thing to mean deliberately.
  std::optional<std::chrono::milliseconds> timeout{std::chrono::seconds{30}};
  /// Absent leaves the transport's own bound, which is one megabyte.
  std::optional<std::size_t> output_limit{};
  /// Which tmux to run. A bare name is resolved through `PATH`, as tmux's own
  /// documentation assumes; a path containing a separator is used as given.
  ///
  /// Naming it is how a caller stops `PATH` deciding: a hermetic build, a
  /// pinned version under test, or a wrapper that reaches tmux on another
  /// machine. It rides the policy rather than the call because a Server's
  /// connection is immutable, and because a handle that changed which tmux it
  /// meant between two calls would make its own entities disagree.
  ///
  /// `Server::control` passes this to the connection it opens, so both
  /// transports run the same executable unless the caller overrides it in
  /// `ConnectionOptions`.
  std::filesystem::path tmux_binary{"tmux"};
};

/// A transport a caller supplies.
///
/// `BackendKind::custom` named this possibility from the first release, but
/// nothing implemented it: the interface a backend had to satisfy lived in the
/// library's private headers, so the only reachable transport was the one that
/// launches a subprocess per command. This is the seam that makes the name
/// true.
///
/// One method, deliberately. Everything else a backend does — routing an entity
/// command through its owning psmux session, proving a session belongs,
/// preparing an attach argv — is either psmux's problem or the library's, and
/// freezing it here would make a private arrangement permanent. What a
/// transport owes is an answer to one command; the library supplies the rest
/// and asks this for the tmux version too, by running `-V` through it.
///
/// `run` is const and may be called from any thread, because a `Server` is
/// copyable across threads and shares one executor. An implementation that
/// keeps a connection or a buffer synchronises itself.
///
/// Returning the command's standard output is the whole contract: a listing
/// answers its rows, a mutation answers whatever tmux printed, and a failure
/// answers `CommandFailure` rather than throwing.
///
/// A batch arrives here too, as one request whose argv carries `;` between the
/// grouped commands — there is no second method to implement, but the
/// separators must reach tmux as they are. A transport that interprets or drops
/// them turns one fail-fast group into something else without saying so.
class CommandExecutor {
public:
  CommandExecutor() = default;
  CommandExecutor(const CommandExecutor&) = delete;
  CommandExecutor& operator=(const CommandExecutor&) = delete;
  CommandExecutor(CommandExecutor&&) = delete;
  CommandExecutor& operator=(CommandExecutor&&) = delete;
  virtual ~CommandExecutor() = default;

  /// Absent timeout means the caller named none; absent limit means the same.
  /// An implementation that cannot bound itself should refuse rather than wait
  /// forever, the way every transport here already does.
  [[nodiscard]] virtual expected<std::string, CommandFailure>
  run(const CommandRequest& command, std::optional<std::chrono::milliseconds> timeout,
      std::optional<std::size_t> output_limit) const = 0;
};

LIBTMUX_NAMESPACE_END

/// Formatting a failure is how it reaches a log line, so the type every call
/// can return knows how to write itself.
///
/// Inheriting the string formatter keeps fill, alignment and width working, so
/// `{:>40}` pads a failure exactly as it pads its text. `__cpp_lib_format` is
/// deliberately not tested here: libc++ 18 leaves it undefined while
/// `std::format` works, so guarding on it would drop this from the clang lane
/// and keep it on the GCC one.
template <>
struct std::formatter<libtmux::CommandFailure> : std::formatter<std::string> {
  template <typename Context>
  auto format(const libtmux::CommandFailure& failure, Context& context) const {
    return std::formatter<std::string>::format(libtmux::to_string(failure), context);
  }
};

include/libtmux/control.hpp.content:
#pragma once

// Decode tmux's control protocol.
//
// A control-mode stream interleaves command reply blocks with asynchronous
// notifications. This parser turns bytes into those events and nothing else:
// no threads, no process, no executor. Feeding it is the caller's job, which
// is what lets the same decoder serve a synchronous read loop today and an
// async executor later without either appearing in this header.
//
// Framing preserves bytes. A line inside a block that looks like a
// notification stays block body, because control-mode framing does not make it
// independently attributable, and block bodies are never converted to UTF-8.

#include <chrono>
#include <cstddef>
#include <cstdint>
#include <filesystem>
#include <iterator>
#include <memory>
#include <optional>
#include <span>
#include <string>
#include <string_view>
#include <variant>
#include <vector>

#include "libtmux/abi.hpp"
#include "libtmux/delivery.hpp"
#include "libtmux/expected.hpp"
#include "libtmux/notification.hpp"

LIBTMUX_NAMESPACE_BEGIN

/// Why a control operation stopped. The stream is terminal after a protocol
/// failure: a caller cannot resynchronise it, only start a new one. `delivery`
/// says whether the affected request was untouched, fully written, answered,
/// or left indeterminate.
struct ProtocolError {
  std::string message;
  DeliveryStatus delivery{DeliveryStatus::indeterminate};
};

/// How tmux closed a reply block: normally, or reporting a failure.
enum class ControlTerminal : std::uint8_t { end, error };

/// How much of one reply a decoder holds, and how long a single line may grow
/// before the stream is called broken.
///
/// A subprocess ends and gives its memory back; a connection does not, so the
/// bound has to be in the decoder rather than in whatever reads it afterwards.
/// The reply bound is the subprocess transport's capture limit, so the same
/// call costs the same memory over either transport. The line bound has no
/// subprocess equivalent: it is the point past which an unterminated line is
/// evidence of a broken stream rather than a large answer.
inline constexpr std::size_t kDefaultRetainedReplyBytes = 1024U * 1024U;
inline constexpr std::size_t kDefaultLineBytes = 1024U * 1024U;

/// One reply block, framed between tmux's `%begin` and its terminator.
///
/// Framing is all this is: whether the command succeeded is
/// `terminal`, and what it said is `body`. A body that hit the decoder's
/// retention bound is still framed and still attributable — see
/// `body_truncated`.
struct ControlBlock {
  std::uint64_t sequence;
  std::uint64_t command_number;
  ControlTerminal terminal;
  std::vector<std::byte> begin_metadata;
  std::vector<std::byte> terminal_metadata;
  std::vector<std::byte> body;
  /// `body` holds the first `retained_reply_bytes` and stopped; `body_bytes` is
  /// how many there were. Set rather than reported as an error because framing
  /// is the parser's job and judging the answer is the caller's: the rest of the
  /// reply is still drained, so the next command's reply is still attributable.
  bool body_truncated{false};
  std::size_t body_bytes{0};
};

/// Anything the parser produces: a reply to something asked, or something tmux
/// said on its own. The two arrive interleaved on one stream.
using Event = std::variant<ControlBlock, Notification>;

/// The control-mode wire format, decoded into whole events.
///
/// Owns the partial state between reads, so a caller feeds whatever bytes
/// arrived and gets back only complete events. It bounds what it retains
/// because a connection, unlike a subprocess, never gives its memory back.
class Parser final {
public:
  Parser() = default;
  /// Zero means unbounded, which only a test that owns both ends should ask
  /// for.
  Parser(std::size_t retained_reply_bytes, std::size_t line_bytes) noexcept
      : retained_reply_bytes_{retained_reply_bytes}, line_bytes_{line_bytes} {}

  expected<std::vector<Event>, ProtocolError> feed(std::span<const std::byte> bytes);
  expected<void, ProtocolError> finish();

private:
  std::vector<std::byte> pending_;
  std::optional<ControlBlock> block_;
  std::optional<ProtocolError> failure_;
  std::size_t retained_reply_bytes_{kDefaultRetainedReplyBytes};
  std::size_t line_bytes_{kDefaultLineBytes};
  bool finished_{false};
};

/// One command as argv, before it is joined into a control-mode line.
struct ControlCommand {
  std::vector<std::string> argv;
};

/// The commands sent as one group, which tmux runs until one fails.
struct ControlRequest {
  std::vector<ControlCommand> group;
};

/// What one request produced: its reply blocks, and the connection error that
/// ended the exchange if one did.
///
/// A connection error is separate from a failed block because they need
/// different handling: a failed command leaves the connection usable.
struct ControlRequestResult {
  /// Every synchronous reply block tmux emitted for this request, in wire
  /// order. tmux does not put a request or operation ID on its guards, so a
  /// command alias or inserted command may make this differ from `group`.
  std::vector<ControlBlock> blocks;
  std::optional<ProtocolError> connection_error;
};

/// How to start a control-mode connection, and what it is allowed to buffer.
///
/// Two of these cannot be changed later because tmux cannot: whether pane
/// output is delivered at all is fixed when the connection starts, and the
/// decoder's bounds belong to the decoder rather than to whatever reads it.
struct ConnectionOptions {
  /// Which tmux to run. Absent means `tmux` from `PATH` — or, through
  /// `Server::control`, the tmux that Server's policy names. Absent rather than
  /// defaulting to `tmux`, so that a caller who writes `tmux` here gets it,
  /// instead of being indistinguishable from one who wrote nothing.
  std::optional<std::filesystem::path> tmux_binary{};
  std::filesystem::path socket_path{};
  std::string session_name{};
  std::chrono::milliseconds startup_timeout{2000};
  std::chrono::milliseconds shutdown_timeout{2000};
  /// Passed to the decoder. Raise the first to hold a bigger capture; the
  /// second bounds a line that never ends. A connection accepts zero
  /// (unbounded) or at least 128 bytes, which leaves room for its private
  /// request boundary.
  std::size_t retained_reply_bytes{kDefaultRetainedReplyBytes};
  std::size_t line_bytes{kDefaultLineBytes};

  /// Deliver `%output` for every pane, as notifications.
  ///
  /// Off, so tmux is not asked to buffer pane output for a caller who never
  /// reads it. It is fixed at connect time because tmux fixes it: a connection
  /// started without output cannot be made to listen later, so this cannot be
  /// a subscription. See `docs/design/pane-output-streaming.md`.
  bool pane_output{false};

  /// Discard a pane's queued output once it is this far behind, and say so
  /// with `%pause`.
  ///
  /// A data-loss policy rather than backpressure, and unset is a policy too:
  /// tmux then buffers until a queued block is five minutes old and closes the
  /// connection with `too far behind`. Set this and a slow reader survives
  /// having lost output; leave it and a slow enough reader loses the
  /// connection. Only meaningful with `pane_output`.
  ///
  /// `%pause` is the sole report that anything was dropped, and it names the
  /// pane. A caller that sets this and ignores notifications has chosen to
  /// lose output silently.
  std::optional<std::chrono::seconds> pause_after{};
};

class Connection;

/// Everything tmux says, until the deadline, as one loop.
///
/// Draining by hand is two nested loops and a break: ask for a batch, stop if
/// it is empty, walk it, ask again. That shape was written six times across
/// this repository's own tests and examples before this existed, which is the
/// argument for it.
///
/// An input range, single pass. A `ParsedNotification` views the notification
/// it was read from, and this owns that notification only until the iterator
/// advances — so copy what you need out of one before asking for the next.
class NotificationRange final {
public:
  /// Single-pass, and the value it yields is borrowed: advancing invalidates
  /// the notification the previous dereference viewed.
  class iterator final {
  public:
    using difference_type = std::ptrdiff_t;
    using value_type = ParsedNotification;
    using iterator_concept = std::input_iterator_tag;

    iterator() = default;
    explicit iterator(NotificationRange* range) : range_{range} { advance(); }

    [[nodiscard]] const ParsedNotification& operator*() const noexcept {
      return current_;
    }
    iterator& operator++() {
      advance();
      return *this;
    }
    void operator++(int) { advance(); }

    [[nodiscard]] bool operator==(std::default_sentinel_t) const noexcept {
      return range_ == nullptr;
    }

  private:
    void advance();

    NotificationRange* range_{nullptr};
    ParsedNotification current_{};
  };

  NotificationRange(Connection& connection,
                    std::chrono::steady_clock::time_point deadline) noexcept
      : connection_{&connection}, deadline_{deadline} {}

  [[nodiscard]] iterator begin() { return iterator{this}; }
  [[nodiscard]] std::default_sentinel_t end() const noexcept { return {}; }

private:
  friend class iterator;
  /// The next outside-block event, or nothing after an empty deadline.
  [[nodiscard]] const Notification* next();

  Connection* connection_{nullptr};
  std::chrono::steady_clock::time_point deadline_{};
  std::vector<Notification> batch_{};
  std::size_t index_{0};
};

/// One held-open control client.
///
/// Shared freely between threads. `execute`, `take_notifications`,
/// `wait_for_notifications`, `watch_notifications`, `set_pane_output` and the
/// muting pair may all be called at once: writes are serialized, and each
/// reply is matched to its own request through a private boundary, which is
/// what lets concurrent callers tell their blocks apart even though tmux puts
/// no request id on a guard.
///
/// Moving from a connection, or destroying one, may not race with any of
/// those — the same rule `CommandRuntime` states for itself.
///
/// It remains one FIFO client, so a command that waits on the server also
/// delays whatever another thread asked for next. That is why `Server::run`
/// stays the surface for a command whose final result matters.
class Connection final {
public:
  static expected<Connection, ProtocolError> connect(ConnectionOptions options);

  ~Connection() noexcept;
  Connection(Connection&&) noexcept;
  Connection& operator=(Connection&&) noexcept;
  Connection(const Connection&) = delete;
  Connection& operator=(const Connection&) = delete;

  /// Completes at this request's private protocol boundary and preserves every
  /// guarded block before it. This is wire evidence, not a final command
  /// result: tmux may end a block before a waiting job or file operation later
  /// reports unguarded output or failure. Use `Server::run` when final success
  /// or failure is required.
  ControlRequestResult execute(ControlRequest request,
                               std::chrono::steady_clock::time_point deadline);
  /// Every outside-block event tmux has written since the last call.
  ///
  /// Taking drains: what comes back will not come back again. It says nothing
  /// about what happens next, so an empty result does not mean the stream has
  /// gone quiet, and a later one is new traffic rather than a repeat. Wait for
  /// the next event with `wait_for_notifications` rather than polling for one.
  [[nodiscard]] std::vector<Notification> take_notifications();

  /// Open an independent cursor at the next outside-block event. Unlike the
  /// legacy taking methods above, watches do not steal events from each other.
  [[nodiscard]] NotificationWatch watch_notifications();

  /// The same, but waits for something to arrive.
  ///
  /// `take_notifications` returns immediately, so a caller reacting to tmux had
  /// to call it in a loop and sleep between — which either wakes too often or
  /// reacts too late, and picks that trade with no idea how long the next event
  /// will take. This blocks until at least one event is available, the
  /// connection fails, or the deadline passes, and returns whatever it has.
  ///
  /// An empty result means the deadline passed or the stream ended; the two are
  /// told apart by asking `execute` or `shutdown`, which report the failure.
  /// Events already buffered are returned without waiting at all.
  [[nodiscard]] std::vector<Notification>
  wait_for_notifications(std::chrono::steady_clock::time_point deadline);
  /// A descriptor that is readable exactly when a take would return something.
  ///
  /// For a caller who owns their own event loop. Without it, integrating means
  /// a thread blocked in `wait_for_notifications`, a queue of their own, and a
  /// self-pipe to wake the loop — which is this descriptor, rebuilt by hand on
  /// top of the thread and queue this connection already has.
  ///
  /// Do not read from it: readability is the signal and the byte is this
  /// connection's to consume. Drain with `take_notifications`, which clears it.
  /// A broken stream makes it readable too, so a poller learns of the failure
  /// rather than waiting for an answer that cannot come.
  ///
  /// Valid until the connection is destroyed or moved from; `-1` if the pipe
  /// could not be created.
  [[nodiscard]] int notification_fd() const noexcept;

  /// Stop or resume `%output` for one pane, on a connection that asked for it.
  ///
  /// The direction is not symmetrical, because tmux is not: a connection that
  /// started without `pane_output` cannot be made to listen to anything, and
  /// muting is the only per-pane control it offers. So this narrows what a
  /// listening connection receives; it cannot widen a silent one.
  ///
  /// Resuming clears both mute and pause, starting at tmux's current output
  /// offset. What a caller sees for output produced while muted differs by
  /// tmux version, and is not this library's choice either way:
  ///
  ///   - Before tmux 3.7, muting stops delivery to this connection only.
  ///     What the pane printed while muted is lost — resuming never replays
  ///     it.
  ///   - On tmux 3.7+, muting stops tmux from reading the pane's pty at all.
  ///     The pane freezes for every attached client and tool, not only this
  ///     connection, and what it printed while muted arrives as a backlog on
  ///     resume (measured against raw tmux, both directions).
  expected<void, ProtocolError>
  set_pane_output(std::string_view pane, bool deliver,
                  std::chrono::steady_clock::time_point deadline);

  /// Named forms of set_pane_output; the same connection policy applies.
  ///
  /// Muting is not this connection's private business on tmux 3.7+: tmux stops
  /// reading the pane's pty, so the pane freezes for every attached client and
  /// tool until it is resumed. `set_pane_output` has the version-by-version
  /// detail; this is the part worth knowing before reaching for the name.
  [[nodiscard]] expected<void, ProtocolError>
  mute_pane_output(std::string_view pane,
                   std::chrono::steady_clock::time_point deadline) {
    return set_pane_output(pane, false, deadline);
  }
  [[nodiscard]] expected<void, ProtocolError>
  resume_pane_output(std::string_view pane,
                     std::chrono::steady_clock::time_point deadline) {
    return set_pane_output(pane, true, deadline);
  }

  /// Everything tmux says until the deadline, as one loop rather than two.
  ///
  /// Borrows this connection, which must outlive it.
  [[nodiscard]] NotificationRange
  events(std::chrono::steady_clock::time_point deadline);

  /// How many outside-block events this Connection's legacy taking cursor
  /// missed to keep the shared log bounded. Each watch has its own count.
  [[nodiscard]] std::size_t dropped_notifications() const noexcept;
  [[nodiscard]] std::int64_t native_child_pid() const noexcept;
  expected<void, ProtocolError>
  shutdown(std::chrono::steady_clock::time_point deadline);

private:
  struct State;
  explicit Connection(std::unique_ptr<State> state) noexcept;
  std::unique_ptr<State> state_;
};

LIBTMUX_NAMESPACE_END

include/libtmux/delivery.hpp.content:
#pragma once

// How far a tmux command is known to have progressed before a failure.
//
// Only `not_started` is safe to retry without inspecting the operation.
// `written` means the complete request reached the transport but no terminal
// reply did. `replied` means tmux produced a terminal reply. `indeterminate`
// means the transport cannot prove whether tmux saw or completed the request.

#include <cstdint>
#include <string_view>

#include "libtmux/abi.hpp"

LIBTMUX_NAMESPACE_BEGIN

/// How far a command is known to have got before something stopped it.
///
/// This is the value that decides whether retrying is safe: only
/// `not_started` is safe blindly, and `indeterminate` is an answer rather than
/// a missing one.
enum class DeliveryStatus : std::uint8_t {
  not_started,
  written,
  replied,
  indeterminate,
};

[[nodiscard]] constexpr std::string_view to_string(DeliveryStatus status) noexcept {
  switch (status) {
  case DeliveryStatus::not_started:
    return "not_started";
  case DeliveryStatus::written:
    return "written";
  case DeliveryStatus::replied:
    return "replied";
  case DeliveryStatus::indeterminate:
    return "indeterminate";
  }
  return "unknown";
}

LIBTMUX_NAMESPACE_END

include/libtmux/entities.hpp.content:
#pragma once

// The tmux object hierarchy.
//
// A Session, Window, Pane or Client is one row of a snapshot: a shared pointer
// to the listing it came from plus the index of its row. That representation
// is what lets an entity be copied, stored in a container and returned from a
// function with nothing to keep alive alongside it, while still costing no
// per-row allocation and no tmux call to read.
//
// The other side of that: keeping one entity keeps its whole listing. A pane
// held from a thousand-pane server retains all thousand rows and the bytes
// tmux sent for them, and ten panes from one listing retain it once, not ten
// times. For the sizes tmux serves this is the cheaper trade — but a program
// that holds handles across large servers for a long time should hold the id
// it needs and look the entity up again, rather than hold the entity.
//
// Reading a field is local and cannot fail. Every method returning `expected`
// runs tmux, and a returned entity describes the moment that command ran:
// entities do not update themselves, `refresh` takes a new snapshot.
//
// Psmux numbers windows and panes per session, so Windows snapshots retain
// their owning session identity alongside tmux's `$0`, `@0`, and `%0` IDs.
//
// Every field below is a format token tmux 3.2a already registers, which is
// the oldest version this library supports. That is a hard constraint rather
// than a preference: tmux expands a token it does not know to the empty
// string, so requesting a newer one would read as a present-but-empty value on
// an older server instead of failing.

#include "libtmux/abi.hpp"
#include "libtmux/capabilities.hpp"
#include "libtmux/command.hpp"
#include "libtmux/expected.hpp"
#include <array>
#include <charconv>
#include <chrono>
#include <cstddef>
#include <format>
#include <functional>
#include <iosfwd>
#include <memory>
#include <optional>
#include <string>
#include <string_view>
#include <system_error>
#include <utility>
#include <vector>

#include "libtmux/filter_expr.hpp"
#include "libtmux/options.hpp"
#include "libtmux/snapshot.hpp"
#include "libtmux/wait.hpp"

LIBTMUX_NAMESPACE_BEGIN

class Server;
class Session;
class Window;
class Pane;
class Buffer;
class Client;
class Command;

/// What a creation command can be told.
///
/// Every field maps to a flag tmux 3.2a already has, and every default is what
/// tmux does when the flag is absent — except focus, which defaults to leaving
/// it where the user put it. A library that moves someone's cursor because it
/// created something is a library people stop calling.
///
/// Aggregates rather than parameters: a caller writes only the fields it cares
/// about, and a field added later does not renumber anything.

struct SplitOptions {
  /// Side by side. tmux stacks by default.
  bool horizontal{false};
  /// Before the target rather than after it.
  bool before{false};
  /// Spanning the full width or height of the window rather than of the pane.
  bool full_size{false};
  /// Where the new pane starts. Empty inherits from the window.
  std::string start_directory{};
  /// Run this instead of the default shell.
  std::string shell_command{};
  /// Size as a percentage of the space being divided.
  std::optional<int> percentage{};
  /// Make the new pane the active one.
  bool focus{false};
  /// Variables the new process starts with, on top of what tmux passes down.
  ///
  /// Pairs rather than `NAME=value` strings: tmux takes a `-e` without an `=`
  /// without complaint and creates nothing, so the pair is joined here and a
  /// name carrying an `=` is refused where the command is built.
  ///
  /// An empty value sets the variable to empty. It does not remove it.
  std::vector<std::pair<std::string, std::string>> environment{};
};

/// What a new window is created as, and where it lands.
///
/// Placing a window after the current one shifts the windows above it up, so
/// an index a caller is holding can change.
struct NewWindowOptions {
  std::string name{};
  std::string start_directory{};
  std::string shell_command{};
  /// Immediately after the current window rather than at the end.
  bool after_current{false};
  /// Put the window at this index rather than at the next free one.
  ///
  /// tmux refuses an index already in use rather than shifting anything, and
  /// that refusal is kept: a workspace rebuilt over a running one should say
  /// so rather than quietly land somewhere else.
  std::optional<long long> index{};
  bool focus{false};
  /// Variables the new process starts with, on top of what tmux passes down.
  ///
  /// Pairs rather than `NAME=value` strings: tmux takes a `-e` without an `=`
  /// without complaint and creates nothing, so the pair is joined here and a
  /// name carrying an `=` is refused where the command is built.
  ///
  /// An empty value sets the variable to empty. It does not remove it.
  std::vector<std::pair<std::string, std::string>> environment{};
};

/// What a new session is created as, including its first window.
///
/// tmux always creates a first window, so the fields naming one are not
/// optional in effect — leaving them empty takes tmux's defaults rather than
/// creating nothing.
struct NewSessionOptions {
  std::string name{};
  std::string start_directory{};
  /// The name of the window the session starts with.
  std::string first_window_name{};
  std::string shell_command{};
  /// The size tmux gives the session while no client is attached. Without it a
  /// detached session is 80x24, and a pane that reports its size to a program
  /// reports that.
  std::optional<int> width{};
  std::optional<int> height{};
  /// Variables the new process starts with, on top of what tmux passes down.
  ///
  /// Pairs rather than `NAME=value` strings: tmux takes a `-e` without an `=`
  /// without complaint and creates nothing, so the pair is joined here and a
  /// name carrying an `=` is refused where the command is built.
  ///
  /// An empty value sets the variable to empty. It does not remove it.
  std::vector<std::pair<std::string, std::string>> environment{};
};

struct RespawnOptions {
  bool replace_running{false};
  /// Where the configured replacement process starts. Empty inherits the
  /// pane's current directory. The command builder escapes tmux format markers
  /// exactly once before this value reaches tmux.
  std::string start_directory{};
};

/// Which part of a pane's screen and scrollback a capture reads.
///
/// A capture reads what the pane is showing, so a line the program redrew is
/// the redrawn one and a line scrolled past the history limit is gone.
struct CaptureOptions {
  /// Where to start, counting back into the scrollback. Absent starts at the
  /// top of the visible pane.
  std::optional<int> start_line{};
  std::optional<int> end_line{};
  /// Everything tmux still remembers, which is what a caller reading history
  /// usually means.
  bool whole_history{false};
  /// Join a line tmux wrapped back into the one line it was.
  bool join_wrapped{false};
  /// Keep the escape sequences rather than the text they produced.
  bool with_escape_sequences{false};
  /// Keep the spaces at the end of a line, which tmux otherwise trims.
  bool keep_trailing_spaces{false};
  /// How much of the answer this call is prepared to hold. A scrollback can be
  /// far larger than the default, and one that does not fit is reported.
  std::optional<std::size_t> output_limit{};
};

/// A tmux object id, typed by what it names.
///
/// tmux spells these `$0`, `@1` and `%2`. The prefix says which kind it is, and
/// nothing in the type did: six accessors returned `std::string_view`, so a
/// window id compiled wherever a pane id belonged, and
/// `pane.id() == window.id()` was a comparison that can never be true but
/// always built.
///
/// The string is reached through `value()` rather than through a conversion.
/// A conversion is what let the mix-up through in the first place: with one,
/// every `std::string_view` parameter accepts any id again, and this would read
/// as type safety while providing none.
///
/// Comparing an id to plain text still works, because that cannot confuse two
/// kinds — `pane.id() == "%0"` asks something answerable. Comparing two ids of
/// different kinds does not compile.
template <typename Kind> class EntityId {
public:
  EntityId() = default;
  explicit constexpr EntityId(std::string_view value) noexcept : value_{value} {}

  [[nodiscard]] constexpr std::string_view value() const noexcept { return value_; }
  [[nodiscard]] constexpr bool empty() const noexcept { return value_.empty(); }

  [[nodiscard]] friend constexpr bool operator==(EntityId left,
                                                 EntityId right) noexcept {
    return left.value_ == right.value_;
  }
  [[nodiscard]] friend constexpr bool operator==(EntityId left,
                                                 std::string_view right) noexcept {
    return left.value_ == right;
  }
  [[nodiscard]] friend constexpr auto operator<=>(EntityId left,
                                                  EntityId right) noexcept {
    return left.value_ <=> right.value_;
  }

private:
  std::string_view value_{};
};

/// Distinct types, not aliases of one: `Kind` is only ever named here.
using SessionId = EntityId<struct SessionIdKind>;
using WindowId = EntityId<struct WindowIdKind>;
using PaneId = EntityId<struct PaneIdKind>;

template <typename Kind>
std::ostream& operator<<(std::ostream& stream, EntityId<Kind> id);

namespace detail {

/// tmux renders every value as text. These read the three shapes it uses, and
/// answer zero, false or the epoch for a value it did not render — which within
/// the supported version range means tmux had nothing to say, not that the
/// token was unknown.
[[nodiscard]] inline long long to_number(std::string_view text) noexcept {
  long long value = 0;
  const char* const end = text.data() + text.size();
  const auto [stopped, code] = std::from_chars(text.data(), end, value);
  return code == std::errc{} && stopped == end ? value : 0;
}

/// tmux renders flag formats as "1" or "0"; anything else is not the flag.
[[nodiscard]] inline bool to_flag(std::string_view text) noexcept {
  return text == "1";
}

[[nodiscard]] inline std::chrono::sys_seconds to_time(std::string_view text) noexcept {
  return std::chrono::sys_seconds{std::chrono::seconds{to_number(text)}};
}

// Whether two ids name the same object.
//
// `scoped_by_session` is the server's answer, not the build's: tmux numbers
// panes and windows uniquely across the whole server, so the id settles it and
// a pane that moves between sessions stays the same pane. psmux numbers them
// within a session, so the same id in two sessions is two objects. Asking the
// server rather than the platform is what keeps two builds of this source
// agreeing about identity — and what keeps a psmux-like transport reached
// through `Server::over` from being treated as tmux because it happens to run
// on POSIX.
[[nodiscard]] inline bool same_entity_id(bool scoped_by_session,
                                         std::string_view left_id,
                                         std::string_view left_session_id,
                                         std::string_view right_id,
                                         std::string_view right_session_id) noexcept {
  if (left_id != right_id) {
    return false;
  }
  return !scoped_by_session || left_session_id == right_session_id;
}

/// The storage every entity has, in one place: the snapshot that owns the bytes
/// and which of its rows this entity is. Inherited privately — an entity is
/// implemented in terms of a row, it is not a kind of row.
class Row {
public:
  Row(std::shared_ptr<const Snapshot> snapshot, std::size_t row) noexcept
      : snapshot_{std::move(snapshot)}, row_{row} {}

protected:
  // Absent reads as empty, which every field decodes as its own zero.
  //
  // The bound is not defensive programming: `from_recording` takes whatever
  // field list a caller passes, and entity constructors are public, so a
  // recording made against an older schema — one field list shorter than the
  // entity now names — is an ordinary value a caller can hold. Indexing it
  // unchecked read past the row, which the by-name overload below never did.
  [[nodiscard]] std::string_view value(std::size_t index) const noexcept {
    const auto& rows = snapshot_->rows();
    if (row_ >= rows.size()) {
      return {};
    }
    const auto& row = rows[row_];
    return index < row.size() ? row[index] : std::string_view{};
  }

  [[nodiscard]] std::string_view value(std::string_view field) const noexcept {
    return value(snapshot_->index_of(field));
  }

  [[nodiscard]] const std::shared_ptr<const Backend>& backend() const noexcept {
    return snapshot_->backend();
  }

  /// Run a command for this entity. An entity read out of a recording has no
  /// server to run it against, and says so rather than doing nothing.
  [[nodiscard]] expected<std::string, CommandFailure>
  run(const CommandRequest& command,
      std::optional<std::size_t> output_limit = {}) const;

  /// The refusal to return when this server is known to get `feature` wrong,
  /// and nothing when it is not. `why` says what it does instead, which is the
  /// part a caller cannot look up.
  [[nodiscard]] std::optional<CommandFailure> refused(ServerFeature feature,
                                                      std::string_view why) const;

public:
  /// The server this entity came from, for a command the typed surface does not
  /// cover. This rather than a public `run`: a command built there would lose
  /// the qualified target the entity knows to use, and a caller reaching for
  /// the escape hatch should be able to see that they are back to raw argv.
  [[nodiscard]] expected<Server, CommandFailure> server() const;

  /// Which tmux server incarnation this came from. Equality and hashing are
  /// defined in terms of it, so two handles opened on one live socket agree but
  /// a handle kept across a restart does not become a handle to the replacement.
  ///
  /// Empty for a value read out of a recording, which is on no server at all.
  [[nodiscard]] std::string_view connection_identity() const noexcept;

protected:
  /// Whether another value came from the same tmux server. Out of line because
  /// answering it needs the connection type, which no installed header sees.
  [[nodiscard]] bool same_connection(const Row& other) const noexcept;

  // Whether this server scopes pane and window ids within a session, so that
  // an id alone does not name an object. Out of line for the same reason as
  // `same_connection`: answering it needs the backend. False for a value read
  // out of a recording, which is on no server and can only be compared by id.
  [[nodiscard]] bool ids_scoped_by_session() const noexcept;

private:
  std::shared_ptr<const Snapshot> snapshot_;
  std::size_t row_;
};

} // namespace detail

/// An attach argv and the private route selecting this server incarnation.
/// Keep it alive until the client exits; same-process `exec` leaves the route on disk.
class AttachCommand final {
public:
  AttachCommand(const AttachCommand&) noexcept;
  AttachCommand(AttachCommand&&) noexcept;
  AttachCommand& operator=(const AttachCommand&) noexcept;
  AttachCommand& operator=(AttachCommand&&) noexcept;
  ~AttachCommand();

  /// Exec-order arguments; empty after this value is moved from.
  [[nodiscard]] const std::vector<std::string>& argv() const noexcept;

private:
  struct State;
  explicit AttachCommand(std::shared_ptr<const State> state) noexcept;

  friend class Session;
  std::shared_ptr<const State> state_;
};

/// One session, as one listing saw it.
///
/// Reads its own fields without touching tmux: the listing ran once, and every
/// value here is that moment's. A window created since is not in
/// `window_count`, and a session killed since still answers.
///
/// Equality is the server incarnation and the session id together, so two
/// handles from separate listings of one live server agree, and a handle kept
/// across a restart does not become a handle to whatever reused `$0`.
class Session : private detail::Row {
public:
  static constexpr std::string_view kNoun{"session"};
  static constexpr std::array kFields{
      std::string_view{"session_id"},       std::string_view{"session_name"},
      std::string_view{"session_attached"}, std::string_view{"session_windows"},
      std::string_view{"session_path"},     std::string_view{"session_created"},
      std::string_view{"session_group"},    std::string_view{"session_grouped"}};

  Session(std::shared_ptr<const Snapshot> snapshot, std::size_t row) noexcept
      : Row{std::move(snapshot), row} {}

  using Row::connection_identity;
  using Row::server;

  [[nodiscard]] SessionId id() const noexcept { return SessionId{value(0)}; }
  [[nodiscard]] std::string_view name() const noexcept { return value(1); }
  /// `session_attached` counts clients rather than rendering a flag, so any
  /// count other than zero means attached.
  [[nodiscard]] bool attached() const noexcept { return client_count() != 0; }
  [[nodiscard]] long long client_count() const noexcept {
    return detail::to_number(value(2));
  }
  [[nodiscard]] long long window_count() const noexcept {
    return detail::to_number(value(3));
  }
  /// The directory a new window starts in, not the shell's current directory.
  [[nodiscard]] std::string_view path() const noexcept { return value(4); }
  [[nodiscard]] std::chrono::sys_seconds created() const noexcept {
    return detail::to_time(value(5));
  }
  /// Empty unless the session belongs to a group sharing its windows.
  [[nodiscard]] std::string_view group() const noexcept { return value(6); }
  [[nodiscard]] bool grouped() const noexcept { return detail::to_flag(value(7)); }

  /// Two values are the same session when they name the same tmux object on the
  /// same connection — not when they were listed at the same moment. A
  /// session refreshed after a rename equals the one it was refreshed from.
  [[nodiscard]] bool operator==(const Session& other) const noexcept {
    return same_connection(other) && id() == other.id();
  }

  [[nodiscard]] expected<std::vector<Window>, CommandFailure> windows() const;
  [[nodiscard]] expected<std::vector<Pane>, CommandFailure> panes() const;
  [[nodiscard]] expected<Window, CommandFailure> active_window() const;
  [[nodiscard]] expected<Pane, CommandFailure> active_pane() const;

  /// Move the selection, and answer with the window it landed on.
  ///
  /// Named for what they do rather than for what they return: `next_window()`
  /// would read as a question, and these change which window is active.
  ///
  /// Relative navigation is tmux's to perform, not a caller's to compute.
  /// Next and previous wrap around the window list, and "last" means the
  /// previously selected window — state only the server holds, which a caller
  /// listing windows has no way to reconstruct.
  ///
  /// Each fails when there is nowhere to go, as tmux does: a session with one
  /// window refuses all three rather than selecting the window already active.
  [[nodiscard]] expected<Window, CommandFailure> select_next_window() const;
  [[nodiscard]] expected<Window, CommandFailure> select_previous_window() const;
  [[nodiscard]] expected<Window, CommandFailure> select_last_window() const;

  /// Created detached: a library call that stole the terminal would be a
  /// surprise, and attaching is a separate decision.
  [[nodiscard]] expected<Window, CommandFailure>
  new_window(std::string_view name) const;
  [[nodiscard]] expected<Window, CommandFailure>
  new_window(NewWindowOptions options) const;

  [[nodiscard]] expected<void, CommandFailure> rename(std::string_view name) const;
  [[nodiscard]] expected<void, CommandFailure> kill() const;
  [[nodiscard]] expected<Session, CommandFailure> refresh() const;

  /// Session options. Reading reports the value tmux would use, marking one
  /// that comes from a wider scope as inherited rather than hiding it.
  [[nodiscard]] expected<std::vector<OptionEntry>, CommandFailure> options() const;
  [[nodiscard]] expected<OptionEntry, CommandFailure>
  option(std::string_view name) const;
  [[nodiscard]] expected<void, CommandFailure> set_option(std::string_view name,
                                                          std::string_view value) const;
  /// Remove the value set here, so the wider scope shows through again.
  [[nodiscard]] expected<void, CommandFailure>
  unset_option(std::string_view name) const;

  /// A command line that attaches a terminal to this session.
  ///
  /// Not a method that attaches: a tmux client needs a terminal, and every
  /// command this library runs talks to it through pipes, so an attach it
  /// performed itself could only ever fail. Spawn the returned argv and retain
  /// the value until that client exits.
  [[nodiscard]] expected<AttachCommand, CommandFailure> attach_command() const;

  /// Send every client here away, leaving the session running.
  [[nodiscard]] expected<void, CommandFailure> detach_clients() const;

  /// Ask tmux to expand a format against this session. The fields above are
  /// what a session is; this reaches the rest of tmux's vocabulary without a
  /// method per variable.
  ///
  /// A target tmux cannot find is not an error to tmux. It expands the fields
  /// it cannot resolve to nothing, prints the literals around them, and exits
  /// zero — so a session that has been killed answers with a blank that reads
  /// like a value. This asks for the session's own id alongside the caller's
  /// format and reports `missing` when the answer is not this session.
  [[nodiscard]] expected<std::string, CommandFailure>
  expand(std::string_view format) const;

  /// Put a message on the status line of every client attached here, and send
  /// it to a control client as `%message`.
  ///
  /// tmux expands the text as a format, so a `#{...}` in it is substituted
  /// rather than shown. Text built from data belongs in `escape_literal` first.
  [[nodiscard]] expected<void, CommandFailure>
  show_message(std::string_view text) const;

  [[nodiscard]] expected<std::vector<OptionEntry>, CommandFailure> hooks() const;
  [[nodiscard]] expected<void, CommandFailure> set_hook(std::string_view name,
                                                        std::string_view command) const;
};

/// One window, as one listing saw it.
///
/// A window can be linked into more than one session; this handle carries the
/// session it was reached through, which is the one its qualified target
/// addresses.
///
/// Reads its own fields without touching tmux, on the same terms as
/// `Session`.
class Window : private detail::Row {
public:
  static constexpr std::string_view kNoun{"window"};
  static constexpr std::string_view kSessionNameField{"session_name"};
  static constexpr std::array kFields{std::string_view{"window_id"},
                                      std::string_view{"window_name"},
                                      std::string_view{"window_active"},
                                      std::string_view{"session_id"},
                                      std::string_view{"window_index"},
                                      std::string_view{"window_panes"},
                                      std::string_view{"window_width"},
                                      std::string_view{"window_height"},
                                      std::string_view{"window_layout"},
                                      std::string_view{"window_zoomed_flag"},
                                      std::string_view{"window_bell_flag"},
                                      std::string_view{"window_activity_flag"},
                                      std::string_view{"window_linked_sessions"}};

  Window(std::shared_ptr<const Snapshot> snapshot, std::size_t row) noexcept
      : Row{std::move(snapshot), row} {}

  using Row::connection_identity;
  using Row::server;

  [[nodiscard]] WindowId id() const noexcept { return WindowId{value(0)}; }
  [[nodiscard]] std::string_view name() const noexcept { return value(1); }
  [[nodiscard]] bool active() const noexcept { return detail::to_flag(value(2)); }
  /// The link to the parent, carried in the row so traversal upward costs
  /// nothing until the parent itself is wanted.
  [[nodiscard]] SessionId session_id() const noexcept { return SessionId{value(3)}; }
  /// Position within its session, which `base-index` is free to start anywhere.
  [[nodiscard]] long long index() const noexcept { return detail::to_number(value(4)); }
  [[nodiscard]] long long pane_count() const noexcept {
    return detail::to_number(value(5));
  }
  [[nodiscard]] long long width() const noexcept { return detail::to_number(value(6)); }
  [[nodiscard]] long long height() const noexcept {
    return detail::to_number(value(7));
  }
  /// An opaque token: hand it back to `select_layout` exactly as received,
  /// and do not parse its shape. tmux 3.8+ reports JSON here for a plain
  /// client, and keeps the classic layout string for a control client
  /// unless that client has asked tmux for JSON with `refresh-client -f
  /// new-layouts` — which `Connection::connect` sends on every connection,
  /// so control mode through this library gets JSON on 3.8+ too.
  ///
  /// A version's own `layout()` output round-trips through its own
  /// `select_layout` on that version; see that method's comment for what
  /// "round-trips" promises and what it does not.
  [[nodiscard]] std::string_view layout() const noexcept { return value(8); }
  [[nodiscard]] bool zoomed() const noexcept { return detail::to_flag(value(9)); }
  [[nodiscard]] bool bell() const noexcept { return detail::to_flag(value(10)); }
  [[nodiscard]] bool activity() const noexcept { return detail::to_flag(value(11)); }
  /// How many sessions hold this window. More than one means the same window
  /// is shown in several places, and a command aimed at a bare id could land
  /// on any of them — which is why targets here are qualified.
  [[nodiscard]] long long linked_sessions() const noexcept {
    return detail::to_number(value(12));
  }
  /// The owning psmux route carried by Windows live snapshots. Empty on POSIX
  /// and in recordings made from the backward-compatible `kFields` schema.
  [[nodiscard]] std::string_view session_name() const noexcept {
    return value(kSessionNameField);
  }

  /// Two values are the same window when they name the same tmux object on the
  /// same connection — not when they were listed at the same moment. A
  /// window refreshed after a rename equals the one it was refreshed from.
  [[nodiscard]] bool operator==(const Window& other) const noexcept {
    return same_connection(other) &&
           detail::same_entity_id(ids_scoped_by_session(), id().value(),
                                  session_id().value(), other.id().value(),
                                  other.session_id().value());
  }

  /// How to address this window, and the reason a window id alone will not do.
  ///
  /// The same window can be linked into several sessions, and a bare `@id`
  /// leaves tmux to pick one of those homes: the index it reports, the session
  /// it names, and the link a move or a kill lands on then depend on a choice
  /// the caller did not make. Qualifying by the session this window was listed
  /// from names one link.
  ///
  /// Prefer `checked_target()`; this source-compatible form returns an empty
  /// string when psmux cannot bind a reusable target without a stale race.
  [[nodiscard]] std::string target() const;
  [[nodiscard]] expected<std::string, CommandFailure> checked_target() const;

  [[nodiscard]] expected<Session, CommandFailure> session() const;
  [[nodiscard]] expected<std::vector<Pane>, CommandFailure> panes() const;
  [[nodiscard]] expected<Pane, CommandFailure> active_pane() const;

  [[nodiscard]] expected<Pane, CommandFailure> split() const;
  [[nodiscard]] expected<Pane, CommandFailure> split(SplitOptions options) const;
  [[nodiscard]] expected<void, CommandFailure> rename(std::string_view name) const;

  /// Rearrange the panes. tmux names five layouts, plus two mirrored ones on
  /// tmux 3.5+, and also accepts the layout description `layout()` returns.
  ///
  /// Restoring one exactly — the same pane back at the same position, not
  /// only the same shape — holds on tmux 3.8+, where the saved string is
  /// JSON and carries each pane's id. On tmux 3.7 and earlier the classic
  /// layout string restores the shape but can rotate which pane lands in
  /// which cell (measured against raw tmux; not a choice this library
  /// makes). A JSON layout is refused before 3.8, and a mirrored preset
  /// before 3.5.
  ///
  /// Anything not shaped like one of those — a leading `-`, a name tmux
  /// does not know, or an incomplete layout string — is refused before
  /// reaching tmux rather than passed through: on tmux 3.3 and 3.3a, that
  /// shape crashes the server outright rather than being refused.
  [[nodiscard]] expected<void, CommandFailure>
  select_layout(std::string_view layout) const;
  [[nodiscard]] expected<void, CommandFailure> resize(long long width,
                                                      long long height) const;
  /// Step through tmux's preset arrangements, and turn the panes within the
  /// one in use.
  ///
  /// The layouts are tmux's list, not a caller's: asking for "the next one"
  /// is the only way to reach them without naming each. Rotating is a
  /// different act — it moves which pane occupies which cell and leaves the
  /// cells where they are.
  ///
  /// None of the three refuses a window holding a single pane. tmux accepts
  /// all of them there and changes nothing, which is worth knowing before
  /// treating success as evidence that something moved.
  [[nodiscard]] expected<void, CommandFailure> next_layout() const;
  [[nodiscard]] expected<void, CommandFailure> previous_layout() const;
  [[nodiscard]] expected<void, CommandFailure> rotate() const;
  /// Go back to the pane that was selected before the current one, and
  /// answer with it.
  ///
  /// Server state, like the window equivalent: nothing in a listing says
  /// which pane that was. A window holding one pane is refused rather than
  /// reselecting it, which is what tmux does.
  [[nodiscard]] expected<Pane, CommandFailure> select_last_pane() const;

  /// Show this window in another session as well. The same window, not a
  /// copy: what runs in it is running in one place and shown in two.
  [[nodiscard]] expected<void, CommandFailure> link_to(const Session& target) const;

  /// Stop showing it in the session this value came from.
  ///
  /// tmux refuses to remove the last link rather than leaving a window no
  /// session holds, and that refusal is kept: a caller who meant to be rid
  /// of the window wants `kill`, which says so.
  [[nodiscard]] expected<void, CommandFailure> unlink() const;

  /// Exchange positions with another window, keeping both ids.
  [[nodiscard]] expected<void, CommandFailure> swap_with(const Window& other) const;
  /// Move to another index within the same session.
  [[nodiscard]] expected<void, CommandFailure> move_to(long long index) const;

  /// Ask tmux to expand a format against this window: the same reach the
  /// session form gives, guarded the same way. A window that has gone reports
  /// `missing` rather than answering with a blank.
  [[nodiscard]] expected<std::string, CommandFailure>
  expand(std::string_view format) const;

  /// Show a message to the clients watching this window's session.
  ///
  /// The window is the context the text expands in, not just who sees it:
  /// `#{window_name}` in a message sent from here names this window even
  /// while another is the active one.
  [[nodiscard]] expected<void, CommandFailure>
  show_message(std::string_view text) const;

  [[nodiscard]] expected<void, CommandFailure> select() const;
  [[nodiscard]] expected<void, CommandFailure> kill() const;
  [[nodiscard]] expected<Window, CommandFailure> refresh() const;

  /// Window options. tmux looks a named option up in the table it belongs to,
  /// so the scope here selects which window provides the context and the
  /// inheritance chain, not which names are legal.
  [[nodiscard]] expected<std::vector<OptionEntry>, CommandFailure> options() const;
  [[nodiscard]] expected<OptionEntry, CommandFailure>
  option(std::string_view name) const;
  [[nodiscard]] expected<void, CommandFailure> set_option(std::string_view name,
                                                          std::string_view value) const;
  [[nodiscard]] expected<void, CommandFailure>
  unset_option(std::string_view name) const;
};

/// One pane, as one listing saw it.
///
/// The narrowest thing tmux addresses, and the only one that owns a process:
/// `pid` is the command tmux started, not the shell's children, so a pane
/// running a program under a shell reports the shell.
///
/// Reads its own fields without touching tmux, on the same terms as
/// `Session`.
class Pane : private detail::Row {
public:
  static constexpr std::string_view kNoun{"pane"};
  static constexpr std::string_view kSessionNameField{"session_name"};
  static constexpr std::array kFields{
      std::string_view{"pane_id"},      std::string_view{"pane_current_command"},
      std::string_view{"pane_active"},  std::string_view{"window_id"},
      std::string_view{"session_id"},   std::string_view{"pane_index"},
      std::string_view{"pane_title"},   std::string_view{"pane_pid"},
      std::string_view{"pane_tty"},     std::string_view{"pane_current_path"},
      std::string_view{"pane_width"},   std::string_view{"pane_height"},
      std::string_view{"pane_dead"},    std::string_view{"pane_in_mode"},
      std::string_view{"pane_at_top"},  std::string_view{"pane_at_bottom"},
      std::string_view{"pane_at_left"}, std::string_view{"pane_at_right"},
      std::string_view{"pane_pipe"},    std::string_view{"pane_left"},
      std::string_view{"pane_top"},     std::string_view{"pane_dead_status"}};

  Pane(std::shared_ptr<const Snapshot> snapshot, std::size_t row) noexcept
      : Row{std::move(snapshot), row} {}

  using Row::connection_identity;
  using Row::server;

  [[nodiscard]] PaneId id() const noexcept { return PaneId{value(0)}; }
  /// What is running in the pane now, which is not what started it.
  [[nodiscard]] std::string_view command() const noexcept { return value(1); }
  [[nodiscard]] bool active() const noexcept { return detail::to_flag(value(2)); }
  [[nodiscard]] WindowId window_id() const noexcept { return WindowId{value(3)}; }
  [[nodiscard]] SessionId session_id() const noexcept { return SessionId{value(4)}; }
  [[nodiscard]] long long index() const noexcept { return detail::to_number(value(5)); }
  [[nodiscard]] std::string_view title() const noexcept { return value(6); }
  [[nodiscard]] long long pid() const noexcept { return detail::to_number(value(7)); }
  [[nodiscard]] std::string_view tty() const noexcept { return value(8); }
  [[nodiscard]] std::string_view path() const noexcept { return value(9); }
  [[nodiscard]] long long width() const noexcept {
    return detail::to_number(value(10));
  }
  [[nodiscard]] long long height() const noexcept {
    return detail::to_number(value(11));
  }
  /// A pane whose program exited while `remain-on-exit` kept it on screen.
  [[nodiscard]] bool dead() const noexcept { return detail::to_flag(value(12)); }
  /// Copy mode and its relatives, in which sent keys move the cursor rather
  /// than reaching the program.
  [[nodiscard]] bool in_mode() const noexcept { return detail::to_flag(value(13)); }
  [[nodiscard]] bool at_top() const noexcept { return detail::to_flag(value(14)); }
  [[nodiscard]] bool at_bottom() const noexcept { return detail::to_flag(value(15)); }
  [[nodiscard]] bool at_left() const noexcept { return detail::to_flag(value(16)); }
  [[nodiscard]] bool at_right() const noexcept { return detail::to_flag(value(17)); }
  /// Whether this pane's output is currently being copied to a command.
  [[nodiscard]] bool piping() const noexcept { return detail::to_flag(value(18)); }
  /// Position within the window, in cells from its top-left corner — the
  /// geometry `select_layout`'s saved arrangement places panes at.
  [[nodiscard]] long long left() const noexcept { return detail::to_number(value(19)); }
  /// Its counterpart along the other axis.
  [[nodiscard]] long long top() const noexcept { return detail::to_number(value(20)); }
  /// What the pane's process exited with, once it has.
  ///
  /// Optional rather than a number because zero is a real exit status and
  /// "still running" is not a status at all — tmux renders the field empty
  /// until the process is gone. Only a pane held on screen by `remain-on-exit`
  /// can report one: without it tmux destroys the pane, and there is nothing
  /// left to ask.
  [[nodiscard]] std::optional<int> exit_status() const noexcept {
    const std::string_view raw = value(21);
    if (raw.empty()) {
      return std::nullopt;
    }
    int status = 0;
    const char* const end = raw.data() + raw.size();
    const auto [stopped, code] = std::from_chars(raw.data(), end, status);
    if (code != std::errc{} || stopped != end) {
      return std::nullopt;
    }
    return status;
  }
  /// The owning psmux route carried by Windows live snapshots. Empty on POSIX
  /// and in recordings made from the backward-compatible `kFields` schema.
  [[nodiscard]] std::string_view session_name() const noexcept {
    return value(kSessionNameField);
  }

  /// Two values are the same pane when they name the same tmux object on the
  /// same connection — not when they were listed at the same moment. A
  /// pane refreshed after a rename equals the one it was refreshed from.
  [[nodiscard]] bool operator==(const Pane& other) const noexcept {
    return same_connection(other) &&
           detail::same_entity_id(ids_scoped_by_session(), id().value(),
                                  session_id().value(), other.id().value(),
                                  other.session_id().value());
  }

  [[nodiscard]] expected<Window, CommandFailure> window() const;
  [[nodiscard]] expected<Session, CommandFailure> session() const;

  /// Literal text, never interpreted as key names or formats, and never
  /// followed by a newline the caller did not ask for.
  [[nodiscard]] expected<void, CommandFailure> send_text(std::string_view text) const;
  [[nodiscard]] expected<void, CommandFailure> send_key(std::string_view key) const;

  /// The text and then Enter, as one tmux invocation.
  ///
  /// Running a command in a pane is two commands to tmux, and sending them
  /// separately costs two round trips and leaves a window where the line is
  /// typed and not submitted. This sends both in one batch, which tmux runs
  /// fail-fast, so a refused line is not followed by an Enter.
  ///
  /// Empty text sends Enter alone, which is what submitting a blank line
  /// means. `send_text` refuses it instead: there, nothing would be sent.
  [[nodiscard]] expected<void, CommandFailure> send_line(std::string_view text) const;

  /// Split this exact pane rather than whichever pane in its window happens to
  /// be active.
  [[nodiscard]] expected<Pane, CommandFailure> split(SplitOptions options = {}) const;

  /// The visible contents, as tmux printed them. `capture_lines` frames it into
  /// lines, and takes a named string: the lines are views into it, so framing
  /// this return value directly is a compile error rather than a dangling read.
  ///
  /// A pane's scrollback can be far larger than the default bound, and a
  /// capture that does not fit is reported rather than cut, so a caller reading
  /// history passes the size it is prepared to hold.
  [[nodiscard]] expected<std::string, CommandFailure> capture() const;
  [[nodiscard]] expected<std::string, CommandFailure>
  capture(CaptureOptions options) const;

  /// Wait until this pane produces `wanted`, rather than until it merely
  /// appears on screen. Prefers the control stream's <code>\%output</code> and falls
  /// back to re-reading the screen when no connection can be opened; `WaitOptions` says
  /// which, and `WaitResult::path` says which answered. A caller that typed the text it
  /// is waiting for names it in `WaitOptions::sent`, or the shell's echo of its own
  /// command is credited to the pane as output.
  [[nodiscard]] expected<WaitResult, CommandFailure>
  wait_for_text(std::string_view wanted, const WaitOptions& options = {}) const;

  [[nodiscard]] expected<void, CommandFailure> set_width(long long width) const;
  [[nodiscard]] expected<void, CommandFailure> set_height(long long height) const;
  [[nodiscard]] expected<void, CommandFailure> swap_with(const Pane& other) const;

  /// Toggle whether this pane's window is zoomed onto it — the whole window
  /// given over to one pane, full size. Zoom is window state, which
  /// `Window::zoomed()` reads; naming a pane here is how tmux picks which one
  /// to give the window to.
  ///
  /// Only the zoom-in direction reads this pane: a window already zoomed
  /// unzooms on any target, this pane included, and stays on whichever pane
  /// it was zoomed onto (measured against raw tmux).
  [[nodiscard]] expected<void, CommandFailure> toggle_zoom() const;

  /// Take this pane out into a window of its own, which is returned. If it is
  /// already the window's only pane, return that window without moving it.
  /// An empty name leaves tmux to name the window after what is running.
  [[nodiscard]] expected<Window, CommandFailure>
  break_out(std::string_view name = {}) const;

  /// Move this pane into another window, splitting it. The other half of
  /// `break_out`: that takes the tree apart, this puts it back.
  ///
  /// The pane keeps its id, so a value held across the move still names it.
  /// The window it came from disappears if it held nothing else, which is
  /// why the target is named rather than inferred from where this pane is.
  [[nodiscard]] expected<void, CommandFailure> join(const Window& target) const;

  /// Put this pane into copy mode, where its contents can be scrolled and
  /// selected rather than typed into.
  ///
  /// Needs no attached client: the mode is pane state, which `in_mode`
  /// reports. Entering twice is harmless.
  [[nodiscard]] expected<void, CommandFailure> enter_copy_mode() const;

  /// Leave whatever mode the pane is in.
  ///
  /// A pane in no mode is refused, with tmux's "not in a mode". That is kept
  /// rather than smoothed into success: checking first would cost a round
  /// trip and still race, and a caller who cares can read `in_mode` or
  /// ignore the failure.
  [[nodiscard]] expected<void, CommandFailure> leave_mode() const;

  /// Copy everything this pane prints to a shell command, until told to
  /// stop. The command runs on the tmux server's machine with the pane's
  /// output on its standard input.
  ///
  /// Starting a second pipe replaces the first: tmux keeps one per pane, so
  /// there is nothing to close and nothing to leak.
  [[nodiscard]] expected<void, CommandFailure> pipe_to(std::string_view command) const;

  /// Stop copying. Harmless on a pane that was not piping.
  [[nodiscard]] expected<void, CommandFailure> stop_piping() const;

  /// Name this pane. The title is what `#{pane_title}` reports and what a
  /// status line can show; it survives the process being replaced.
  [[nodiscard]] expected<void, CommandFailure> set_title(std::string_view title) const;

  /// Start the pane's command again.
  ///
  /// tmux refuses a pane whose process is still running unless told to kill
  /// it, and that refusal is kept rather than smoothed over: replacing a
  /// live process is a decision, so `replace_running` has to be asked for.
  [[nodiscard]] expected<void, CommandFailure>
  respawn(bool replace_running = false) const;
  [[nodiscard]] expected<void, CommandFailure> respawn(RespawnOptions options) const;

  /// Forget the scrollback, which is the only way to bound a pane's memory
  /// without restarting what is running in it.
  [[nodiscard]] expected<void, CommandFailure> clear_history() const;

  /// Ask tmux to expand a format against this pane. `#{pane_current_command}`
  /// and `#{pane_current_path}` are the two most callers reach for, and
  /// neither is a field this class carries: both change under a value that
  /// stays still.
  ///
  /// Guarded like the session and window forms, because tmux answers a pane
  /// that has gone with a blank and a zero exit status.
  [[nodiscard]] expected<std::string, CommandFailure>
  expand(std::string_view format) const;

  /// Show a message to the clients watching this pane's session, expanded
  /// against this pane.
  [[nodiscard]] expected<void, CommandFailure>
  show_message(std::string_view text) const;

  /// Deliver a buffer's text to this pane, as if it had been typed. The text
  /// arrives on the command line and is not run: a caller wanting it executed
  /// sends Enter afterwards, which is the same distinction `send_text` draws.
  ///
  /// `consume` is tmux's `-d`, deleting the buffer once it has been pasted,
  /// which is what a caller treating it as a one-shot transfer wants.
  [[nodiscard]] expected<void, CommandFailure> paste(const Buffer& buffer,
                                                     bool consume = false) const;

  [[nodiscard]] expected<void, CommandFailure> select() const;
  [[nodiscard]] expected<void, CommandFailure> kill() const;
  [[nodiscard]] expected<Pane, CommandFailure> refresh() const;

  /// Pane options, the narrowest scope tmux has, and the end of an inheritance
  /// chain that runs pane, window, session, global.
  [[nodiscard]] expected<std::vector<OptionEntry>, CommandFailure> options() const;
  [[nodiscard]] expected<OptionEntry, CommandFailure>
  option(std::string_view name) const;
  [[nodiscard]] expected<void, CommandFailure> set_option(std::string_view name,
                                                          std::string_view value) const;
  [[nodiscard]] expected<void, CommandFailure>
  unset_option(std::string_view name) const;
};

/// One command this tmux understands.
///
/// The list is how a caller asks what the server can do rather than deducing
/// it from a version string. A build with commands compiled out, or a
/// version between releases, answers for itself.
class Command : private detail::Row {
public:
  static constexpr std::string_view kNoun{"command"};
  static constexpr std::array kFields{std::string_view{"command_list_name"},
                                      std::string_view{"command_list_alias"},
                                      std::string_view{"command_list_usage"}};

  Command(std::shared_ptr<const Snapshot> snapshot, std::size_t row) noexcept
      : Row{std::move(snapshot), row} {}

  using Row::connection_identity;
  using Row::server;

  [[nodiscard]] std::string_view name() const noexcept { return value(0); }
  /// tmux's short form, such as `lscm` for `list-commands`. Empty when the
  /// command has none.
  [[nodiscard]] std::string_view alias() const noexcept { return value(1); }
  /// The flags and arguments, as tmux prints them in its own help.
  [[nodiscard]] std::string_view usage() const noexcept { return value(2); }

  [[nodiscard]] bool operator==(const Command& other) const noexcept {
    return same_connection(other) && name() == other.name();
  }
};

/// A named piece of text the server holds, outliving the pane it came from.
///
/// tmux's cut buffers are the clipboard between panes: a pane's selection
/// lands in one, and pasting reads one back. They belong to the server, not
/// to any pane, which is why they are listed from it.
class Buffer : private detail::Row {
public:
  static constexpr std::string_view kNoun{"buffer"};
  static constexpr std::array kFields{
      std::string_view{"buffer_name"}, std::string_view{"buffer_size"},
      std::string_view{"buffer_sample"}, std::string_view{"buffer_created"}};

  Buffer(std::shared_ptr<const Snapshot> snapshot, std::size_t row) noexcept
      : Row{std::move(snapshot), row} {}

  using Row::connection_identity;
  using Row::server;

  /// Named by the caller, or by tmux as `buffer0` and upward when it is not.
  [[nodiscard]] std::string_view name() const noexcept { return value(0); }
  [[nodiscard]] long long size() const noexcept { return detail::to_number(value(1)); }
  /// The opening of the contents, as tmux prints it in a listing. Truncated,
  /// and with control characters rendered — `contents()` reads the bytes.
  [[nodiscard]] std::string_view sample() const noexcept { return value(2); }
  [[nodiscard]] std::chrono::sys_seconds created() const noexcept {
    return detail::to_time(value(3));
  }

  [[nodiscard]] bool operator==(const Buffer& other) const noexcept {
    return same_connection(other) && name() == other.name();
  }

  /// The whole contents. tmux prints them with no trailing newline, so what
  /// comes back is exactly what was put in.
  [[nodiscard]] expected<std::string, CommandFailure> contents() const;
  [[nodiscard]] expected<void, CommandFailure> remove() const;

private:
  friend class Server;
};

/// One attached client, as one listing saw it.
///
/// The shortest-lived of these: a client goes away with its terminal, so a
/// handle outlives what it names more often than the others do. It is named
/// by its tty rather than by an id tmux issues.
class Client : private detail::Row {
public:
  static constexpr std::string_view kNoun{"client"};
  static constexpr std::array kFields{
      std::string_view{"client_name"},     std::string_view{"client_session"},
      std::string_view{"client_readonly"}, std::string_view{"client_tty"},
      std::string_view{"client_width"},    std::string_view{"client_height"},
      std::string_view{"client_created"},  std::string_view{"client_activity"},
      std::string_view{"client_termname"}, std::string_view{"client_control_mode"},
      std::string_view{"client_pid"},      std::string_view{"pane_id"},
      std::string_view{"client_flags"},    std::string_view{"window_id"}};

  Client(std::shared_ptr<const Snapshot> snapshot, std::size_t row) noexcept
      : Row{std::move(snapshot), row} {}

  using Row::connection_identity;
  using Row::server;

  /// A client is named by its terminal path, which is the only stable handle
  /// tmux gives; there is no client id format.
  [[nodiscard]] std::string_view name() const noexcept { return value(0); }
  [[nodiscard]] std::string_view session_name() const noexcept { return value(1); }
  [[nodiscard]] bool read_only() const noexcept { return detail::to_flag(value(2)); }
  [[nodiscard]] std::string_view tty() const noexcept { return value(3); }
  [[nodiscard]] long long width() const noexcept { return detail::to_number(value(4)); }
  [[nodiscard]] long long height() const noexcept {
    return detail::to_number(value(5));
  }
  [[nodiscard]] std::chrono::sys_seconds created() const noexcept {
    return detail::to_time(value(6));
  }
  [[nodiscard]] std::chrono::sys_seconds last_activity() const noexcept {
    return detail::to_time(value(7));
  }
  [[nodiscard]] std::string_view terminal() const noexcept { return value(8); }
  /// A control-mode client is a program driving tmux, not a terminal.
  [[nodiscard]] bool control_mode() const noexcept { return detail::to_flag(value(9)); }
  [[nodiscard]] long long pid() const noexcept { return detail::to_number(value(10)); }
  /// The session window's active pane, not independent client-local focus.
  [[nodiscard]] PaneId active_pane_id() const noexcept { return PaneId{value(11)}; }
  [[nodiscard]] std::string_view flags() const noexcept { return value(12); }
  [[nodiscard]] WindowId window_id() const noexcept { return WindowId{value(13)}; }

  /// Two values are the same client when they name the same terminal on the
  /// same connection.
  [[nodiscard]] bool operator==(const Client& other) const noexcept {
    return same_connection(other) && name() == other.name();
  }

  [[nodiscard]] expected<Session, CommandFailure> session() const;

  /// Point this client at another session, leaving it attached.
  [[nodiscard]] expected<void, CommandFailure> switch_to(const Session& session) const;
  [[nodiscard]] expected<void, CommandFailure> detach() const;
  /// Redraw, and tell tmux the size this client is now, which matters for a
  /// control-mode client whose size tmux cannot otherwise observe.
  [[nodiscard]] expected<void, CommandFailure> refresh() const;
};

// Typed field handles. A handle exists for every field a filter can compare —
// the strings and the flags — and names the tmux token beside the accessor, so
// an expression can be evaluated here and translated to a tmux `-f` filter
// later without a second table to keep in step.

/// Written as tmux would name it, with the detail that identifies it: an id
/// and the thing a reader recognises it by. Declared against a forward-declared
/// stream so no consumer pays for `<ostream>` to include an entity.
