include/libtmux/error.hpp.content:
#pragma once

// Crossing between this library's error types.
//
// There are two runtime failure types, because the two transports answer
// different questions: `CommandFailure` says whether tmux acted, and
// `ProtocolError` says what the control wire did. A caller that handles both
// surfaces wants one type, and wrote the same adapter to get it.
//
// The validation enums are a separate matter. Each names why a pure argument
// builder refused, and none of them ever reached tmux — which is why they are
// their own small types rather than failures with a delivery status. Folding
// one into a `CommandFailure` is always `validation` and `not_started`, and
// this is where that is written once.
//
// Its own header, not `command.hpp`: only a caller that crosses surfaces pays
// for including every error type at once.

#include "libtmux/abi.hpp"
#include "libtmux/cardinality.hpp"
#include "libtmux/command.hpp"
#include "libtmux/control.hpp"
#include "libtmux/delivery.hpp"
#include "libtmux/keys.hpp"
#include "libtmux/legacy_lookup.hpp"
#include "libtmux/socket.hpp"
#include "libtmux/target.hpp"
#include "libtmux/version.hpp"

#include <string>
#include <utility>

LIBTMUX_NAMESPACE_BEGIN

/// A control-wire failure as a command failure, keeping what it says about
/// delivery — the one thing a caller cannot reconstruct. A protocol error that
/// never started is a validation refusal; past that point the wire is what
/// broke, which is `pipe`.
[[nodiscard]] inline CommandFailure as_command_failure(ProtocolError error) {
  return CommandFailure{.kind = error.delivery == DeliveryStatus::not_started
                                    ? FailureKind::validation
                                    : FailureKind::pipe,
                        .delivery = error.delivery,
                        .exit_code = -1,
                        .diagnostic = std::move(error.message)};
}

/// The other direction, for a caller handing a command failure to a surface
/// that speaks the wire's type. The kind is dropped because the wire has no
/// word for it; the diagnostic carries what it said.
[[nodiscard]] inline ProtocolError as_protocol_error(CommandFailure failure) {
  return ProtocolError{.message = std::move(failure.diagnostic),
                       .delivery = failure.delivery};
}

/// Which error types name a validation reason rather than a runtime failure.
/// Opted in one by one rather than matched on being an enum: `FailureKind` and
/// `DeliveryStatus` are enums too, and neither is a reason a call was refused.
template <typename Reason> inline constexpr bool is_validation_reason = false;
template <> inline constexpr bool is_validation_reason<TargetError> = true;
template <> inline constexpr bool is_validation_reason<SocketError> = true;
template <> inline constexpr bool is_validation_reason<CardinalityError> = true;
template <> inline constexpr bool is_validation_reason<LookupParseError> = true;
template <> inline constexpr bool is_validation_reason<VersionError> = true;
template <> inline constexpr bool is_validation_reason<KeyError> = true;

/// Why a pure argument builder refused, as a command failure. Nothing was
/// dispatched, so the delivery is `not_started` and there is no exit status.
template <typename Reason>
  requires is_validation_reason<Reason>
[[nodiscard]] CommandFailure as_command_failure(Reason reason) {
  return CommandFailure{.kind = FailureKind::validation,
                        .delivery = DeliveryStatus::not_started,
                        .exit_code = 0,
                        .diagnostic = std::string{to_string(reason)}};
}

LIBTMUX_NAMESPACE_END

include/libtmux/expected.hpp.content:
#pragma once

// The one C++23 library facility this package's public surface needs.
//
// Recoverable failure is reported by value, not by exception, which means
// `std::expected`. That type arrived in C++23, so a toolchain shipping a C++20
// standard library cannot provide it. Rather than fork the API, the C++20 build
// substitutes the reference implementation the standard type was modelled on.
//
// Callers write `libtmux::expected` and never name either underlying type, so
// the same source compiles under both.

#if defined(LIBTMUX_USE_TL_EXPECTED)
#include <tl/expected.hpp>
#else
#include <expected>
// libstdc++ defines `std::expected` only when the compiler advertises the
// concepts support its header is written against, which clang does not when it
// drives libstdc++ — the pairing a distribution gives you by default. Without
// this the first thing a builder sees is a template error inside this header,
// which names neither the toolchain nor the way out.
#if !defined(__cpp_lib_expected)
#error                                                                                 \
    "libtmux needs std::expected, and this standard library does not provide it. Build with libc++ (-stdlib=libc++), with GCC, or configure -DLIBTMUX_CXX_STANDARD=20 to use tl::expected instead."
#endif
#endif

#include <type_traits>
#include <utility>

namespace libtmux {

#if defined(LIBTMUX_USE_TL_EXPECTED)

/// A value or the reason there is not one.
///
/// `std::expected` where the standard library has it, and a drop-in otherwise,
/// so a caller writes the same code either way. Nothing in this library throws
/// to report a tmux failure.
template <typename Value, typename Error> using expected = tl::expected<Value, Error>;

#else

/// A value or the reason there is not one.
///
/// `std::expected` where the standard library has it, and a drop-in otherwise,
/// so a caller writes the same code either way. Nothing in this library throws
/// to report a tmux failure.
template <typename Value, typename Error> using expected = std::expected<Value, Error>;

#endif

// The unexpected type itself, for the rare declaration that names it.
#if defined(LIBTMUX_USE_TL_EXPECTED)
/// The error side of `expected`, named for the rare declaration that has to
/// spell it. Returning one is how a function reports a failure.
template <typename Error> using unexpected_t = tl::unexpected<Error>;
#else
/// The error side of `expected`, named for the rare declaration that has to
/// spell it. Returning one is how a function reports a failure.
template <typename Error> using unexpected_t = std::unexpected<Error>;
#endif

/// What `value()` throws when there is none. Named here so a caller who wants an
/// exception at a boundary can catch it in either standard's build.
#if defined(LIBTMUX_USE_TL_EXPECTED)
template <typename Error> using bad_expected_access = tl::bad_expected_access<Error>;
#else
template <typename Error> using bad_expected_access = std::bad_expected_access<Error>;
#endif

/// A factory rather than an alias: an alias template cannot deduce its argument,
/// so `unexpected(error)` would stop compiling at every call site.
template <typename Error> [[nodiscard]] constexpr auto unexpected(Error&& error) {
  using Decayed = std::decay_t<Error>;
#if defined(LIBTMUX_USE_TL_EXPECTED)
  return tl::unexpected<Decayed>(std::forward<Error>(error));
#else
  return std::unexpected<Decayed>(std::forward<Error>(error));
#endif
}

} // namespace libtmux

include/libtmux/filter_expr.hpp.content:
#pragma once

// Value-semantic filter expressions over explicit snapshots.
//
// An expression owns every operand it compares against, so it can outlive the
// call that built it and can be stored, copied, and later translated. It is
// deliberately not an expression template: the node set is a closed variant, so
// the same value that filters a range in memory can be inspected and, later,
// compiled to a tmux `-f` format string.

#include "libtmux/abi.hpp"
#include "libtmux/lowered_node.hpp"
#include <algorithm>
#include <cstddef>
#include <functional>
#include <memory>
#include <ranges>
#include <string>
#include <string_view>
#include <type_traits>
#include <utility>
#include <variant>
#include <vector>

LIBTMUX_NAMESPACE_BEGIN

/// How a text field is compared. `iequals` folds case; the rest do not.
enum class StringOp { equals, iequals, contains, starts_with, ends_with };
/// tmux renders a count, a size and an index as text. Comparing them as text
/// puts "9" after "10", so a numeric field is its own kind with its own
/// operations rather than a string field a caller must remember to convert.
/// How a numeric field is compared, on the value rather than on its text.
enum class NumberOp { equals, not_equals, less, less_equal, greater, greater_equal };
/// Whether a group's operands must all hold or any one of them.
enum class Combine { conjunction, disjunction };

/// A field is a named accessor: the name is what a future tmux-format lowering
/// needs, the accessor is what in-memory evaluation needs.
///
/// The two halves are only as consistent as whoever paired them, and nothing in
/// the type system pairs them. A field naming `pane_title` while reading
/// `pane_current_command` evaluates one way in memory and lowers to another,
/// and the built-in handles avoid that only by taking their name from the
/// entity's own `kFields` array rather than spelling it again.
///
/// Which is enough here and not enough everywhere. A caller may build a field
/// however they like and get whatever they built — their process, their
/// predicate. What must not follow is a forged pairing crossing a process
/// boundary, so a document arriving from anywhere else is resolved by name
/// against what this library actually queries, and a name it does not know is
/// refused rather than evaluated to nothing. That check lives with the wire
/// format, in the JSON integration, because it is the boundary that needs it.
template <typename Entity> struct StringField {
  std::string_view name;
  std::string_view (*read)(const Entity&);
};

/// A flag on an entity, named for the expression and read through a function
/// pointer rather than a member pointer so the same descriptor works for a
/// field computed from several tmux tokens.
template <typename Entity> struct BoolField {
  std::string_view name;
  bool (*read)(const Entity&);
};

/// A numeric field on an entity, read as a number rather than as the text tmux
/// sends, so `9` orders before `10`.
template <typename Entity> struct NumberField {
  std::string_view name;
  long long (*read)(const Entity&);
};

/// A filter over one entity type, as a value.
///
/// Owns every operand it compares against, so it outlives the call that built
/// it and can be stored and copied. The node set is a closed variant rather
/// than an expression template, which is what lets the same value both filter
/// a range already in memory and be translated to a tmux `-f` format later.
template <typename Entity> class FilterExpr {
public:
  /// A text field compared against an operand this node owns.
  struct StringTest {
    StringField<Entity> field;
    StringOp op;
    std::string operand;
  };

  /// A flag compared against an expected value.
  struct BoolTest {
    BoolField<Entity> field;
    bool expected;
  };

  /// A numeric field compared against a number.
  struct NumberTest {
    NumberField<Entity> field;
    NumberOp op;
    long long operand;
  };

  /// Several expressions combined, all of them or any of them.
  struct Group {
    Combine combine;
    std::vector<FilterExpr> operands;
  };

  /// One expression inverted. Held indirectly because a node cannot contain
  /// itself by value.
  struct Negation {
    std::unique_ptr<FilterExpr> operand;
  };

  /// A relation crosses to another entity type, so its child expression cannot
  /// live in this variant. The node keeps the relation name and quantifier for
  /// inspection and owns the evaluation by value.
  struct RelationTest {
    std::string relation;
    int quantifier;
    std::function<bool(const Entity&)> evaluate;
    /// The child compares another entity, so it cannot live in this variant.
    /// Its lowered form can, which is what keeps a relation translatable.
    LoweredExpression child;
  };

  using Node =
      std::variant<StringTest, BoolTest, NumberTest, Group, Negation, RelationTest>;

  explicit FilterExpr(Node node) : node_{std::move(node)} {}

  FilterExpr(const FilterExpr& other) : node_{clone(other.node_)} {}
  FilterExpr& operator=(const FilterExpr& other) {
    if (this != &other) {
      node_ = clone(other.node_);
    }
    return *this;
  }
  FilterExpr(FilterExpr&&) noexcept = default;
  FilterExpr& operator=(FilterExpr&&) noexcept = default;
  ~FilterExpr() = default;

  [[nodiscard]] bool operator()(const Entity& entity) const {
    return std::visit([&entity](const auto& node) { return evaluate(node, entity); },
                      node_);
  }

  [[nodiscard]] const Node& node() const noexcept { return node_; }

private:
  static Node clone(const Node& node) {
    return std::visit(
        [](const auto& alternative) -> Node {
          using Alternative = std::decay_t<decltype(alternative)>;
          if constexpr (std::is_same_v<Alternative, Negation>) {
            return Negation{std::make_unique<FilterExpr>(*alternative.operand)};
          } else {
            return alternative;
          }
        },
        node);
  }

  static bool evaluate(const StringTest& test, const Entity& entity) {
    const std::string_view value = test.field.read(entity);
    const std::string_view operand = test.operand;
    switch (test.op) {
    case StringOp::equals:
      return value == operand;
    case StringOp::iequals:
      return value.size() == operand.size() &&
             std::ranges::equal(value, operand, [](char left, char right) {
               return fold(left) == fold(right);
             });
    case StringOp::contains:
      return value.find(operand) != std::string_view::npos;
    case StringOp::starts_with:
      return value.starts_with(operand);
    case StringOp::ends_with:
      return value.ends_with(operand);
    }
    return false;
  }

  static bool evaluate(const BoolTest& test, const Entity& entity) {
    return test.field.read(entity) == test.expected;
  }

  static bool evaluate(const NumberTest& test, const Entity& entity) {
    const long long value = test.field.read(entity);
    switch (test.op) {
    case NumberOp::equals:
      return value == test.operand;
    case NumberOp::not_equals:
      return value != test.operand;
    case NumberOp::less:
      return value < test.operand;
    case NumberOp::less_equal:
      return value <= test.operand;
    case NumberOp::greater:
      return value > test.operand;
    case NumberOp::greater_equal:
      return value >= test.operand;
    }
    return false;
  }

  static bool evaluate(const Group& group, const Entity& entity) {
    // An empty conjunction is true and an empty disjunction is false, so a
    // group folded from no operands never silently matches everything.
    const auto matches = [&entity](const FilterExpr& operand) {
      return operand(entity);
    };
    return group.combine == Combine::conjunction
               ? std::ranges::all_of(group.operands, matches)
               : std::ranges::any_of(group.operands, matches);
  }

  static bool evaluate(const Negation& negation, const Entity& entity) {
    return !(*negation.operand)(entity);
  }

  static bool evaluate(const RelationTest& test, const Entity& entity) {
    return test.evaluate(entity);
  }

  static constexpr char fold(char value) noexcept {
    return value >= 'A' && value <= 'Z' ? static_cast<char>(value - 'A' + 'a') : value;
  }

  Node node_;
};

/// A typed field handle. Only the operations a field's type actually supports
/// are declared, so `pane::active.starts_with(...)` is a compile error rather
/// than a runtime surprise.
///
/// A handle also reads a row, so the same name serves as a ranges projection —
/// and a flag handle as a predicate — rather than a lambda that spells the
/// accessor a second time. `sort(panes, {}, pane::index)` then orders by the
/// number tmux rendered, where projecting the text puts `%10` before `%9`.
template <typename Entity> struct StringFieldHandle {
  StringField<Entity> field;

  [[nodiscard]] std::string_view operator()(const Entity& row) const {
    return field.read(row);
  }

  [[nodiscard]] FilterExpr<Entity> operator==(std::string_view operand) const {
    return make(StringOp::equals, operand);
  }
  [[nodiscard]] FilterExpr<Entity> iequals(std::string_view operand) const {
    return make(StringOp::iequals, operand);
  }
  [[nodiscard]] FilterExpr<Entity> contains(std::string_view operand) const {
    return make(StringOp::contains, operand);
  }
  [[nodiscard]] FilterExpr<Entity> starts_with(std::string_view operand) const {
    return make(StringOp::starts_with, operand);
  }
  [[nodiscard]] FilterExpr<Entity> ends_with(std::string_view operand) const {
    return make(StringOp::ends_with, operand);
  }

private:
  [[nodiscard]] FilterExpr<Entity> make(StringOp op, std::string_view operand) const {
    return FilterExpr<Entity>{
        typename FilterExpr<Entity>::StringTest{field, op, std::string{operand}}};
  }
};

/// The value a numeric field name resolves to in an expression, whose
/// comparison operators build the node rather than comparing anything.
template <typename Entity> struct NumberFieldHandle {
  NumberField<Entity> field;

  [[nodiscard]] long long operator()(const Entity& row) const {
    return field.read(row);
  }

  [[nodiscard]] FilterExpr<Entity> operator==(long long operand) const {
    return make(NumberOp::equals, operand);
  }
  [[nodiscard]] FilterExpr<Entity> operator!=(long long operand) const {
    return make(NumberOp::not_equals, operand);
  }
  [[nodiscard]] FilterExpr<Entity> operator<(long long operand) const {
    return make(NumberOp::less, operand);
  }
  [[nodiscard]] FilterExpr<Entity> operator<=(long long operand) const {
    return make(NumberOp::less_equal, operand);
  }
  [[nodiscard]] FilterExpr<Entity> operator>(long long operand) const {
    return make(NumberOp::greater, operand);
  }
  [[nodiscard]] FilterExpr<Entity> operator>=(long long operand) const {
    return make(NumberOp::greater_equal, operand);
  }

private:
  [[nodiscard]] FilterExpr<Entity> make(NumberOp op, long long operand) const {
    return FilterExpr<Entity>{
        typename FilterExpr<Entity>::NumberTest{field, op, operand}};
  }
};

/// The value a flag's name resolves to in an expression. Converts to a filter
/// on its own, so naming the field is the same as testing it for true.
template <typename Entity> struct BoolFieldHandle {
  BoolField<Entity> field;

  [[nodiscard]] bool operator()(const Entity& row) const { return field.read(row); }

  [[nodiscard]] operator FilterExpr<Entity>() const { // NOLINT(*-explicit-*)
    return FilterExpr<Entity>{typename FilterExpr<Entity>::BoolTest{field, true}};
  }
  [[nodiscard]] FilterExpr<Entity> operator==(bool expected) const {
    return FilterExpr<Entity>{typename FilterExpr<Entity>::BoolTest{field, expected}};
  }
};

template <typename Entity>
[[nodiscard]] FilterExpr<Entity> operator&&(FilterExpr<Entity> left,
                                            FilterExpr<Entity> right) {
  std::vector<FilterExpr<Entity>> operands;
  operands.reserve(2);
  operands.push_back(std::move(left));
  operands.push_back(std::move(right));
  return FilterExpr<Entity>{
      typename FilterExpr<Entity>::Group{Combine::conjunction, std::move(operands)}};
}

template <typename Entity>
[[nodiscard]] FilterExpr<Entity> operator||(FilterExpr<Entity> left,
                                            FilterExpr<Entity> right) {
  std::vector<FilterExpr<Entity>> operands;
  operands.reserve(2);
  operands.push_back(std::move(left));
  operands.push_back(std::move(right));
  return FilterExpr<Entity>{
      typename FilterExpr<Entity>::Group{Combine::disjunction, std::move(operands)}};
}

template <typename Entity>
[[nodiscard]] FilterExpr<Entity> operator!(FilterExpr<Entity> operand) {
  return FilterExpr<Entity>{typename FilterExpr<Entity>::Negation{
      std::make_unique<FilterExpr<Entity>>(std::move(operand))}};
}

template <typename Entity>
[[nodiscard]] FilterExpr<Entity> operator&&(FilterExpr<Entity> left,
                                            BoolFieldHandle<Entity> right) {
  return std::move(left) && FilterExpr<Entity>{right};
}

template <typename Entity>
[[nodiscard]] FilterExpr<Entity> operator&&(BoolFieldHandle<Entity> left,
                                            FilterExpr<Entity> right) {
  return FilterExpr<Entity>{left} && std::move(right);
}

template <typename Entity>
[[nodiscard]] FilterExpr<Entity> operator||(FilterExpr<Entity> left,
                                            BoolFieldHandle<Entity> right) {
  return std::move(left) || FilterExpr<Entity>{right};
}

template <typename Entity>
[[nodiscard]] FilterExpr<Entity> operator||(BoolFieldHandle<Entity> left,
                                            FilterExpr<Entity> right) {
  return FilterExpr<Entity>{left} || std::move(right);
}

template <typename Entity>
[[nodiscard]] FilterExpr<Entity> operator!(BoolFieldHandle<Entity> operand) {
  return !FilterExpr<Entity>{operand};
}

/// The query vocabulary has a namespace of its own, so a caller composing views
/// can say where an adaptor came from without importing the whole library:
///
///   using namespace libtmux::tmuxq;
///   auto interesting = panes | matching(pane::active);
///
/// It is a home, not a second surface — `libtmux::matching` below names these
/// same functions, so there is one definition to reason about.
namespace tmuxq {

/// `matching(expr)` is a range adaptor closure so it composes with std views.
template <typename Entity> [[nodiscard]] auto matching(FilterExpr<Entity> expr) {
  return std::views::filter(
      [expr = std::move(expr)](const Entity& entity) { return expr(entity); });
}

/// A bare flag field is a complete question, so it adapts a range directly.
template <typename Entity> [[nodiscard]] auto matching(BoolFieldHandle<Entity> field) {
  return matching(FilterExpr<Entity>{field});
}

} // namespace tmuxq

using tmuxq::matching;

LIBTMUX_NAMESPACE_END

include/libtmux/format.hpp.content:
#pragma once

// Compose tmux format strings.
//
// tmux treats `#` as the start of a substitution: `#{...}` expands a variable,
// `#(...)` runs a command, and `##` is a literal `#`. Any literal text placed
// in a format must therefore escape its `#` characters, or a status line
// containing `#1` silently becomes an expansion attempt.

#include "libtmux/abi.hpp"
#include <string>
#include <string_view>
#include <vector>

LIBTMUX_NAMESPACE_BEGIN

/// Escape literal text for inclusion in a format string.
[[nodiscard]] inline std::string escape_literal(std::string_view text) {
  std::string escaped;
  escaped.reserve(text.size());
  for (const char character : text) {
    if (character == '#') {
      escaped.push_back('#');
    }
    escaped.push_back(character);
  }
  return escaped;
}

/// Wrap a variable name as a substitution. The name is not escaped: a name is
/// chosen by the caller from tmux's format vocabulary, not built from data.
[[nodiscard]] inline std::string variable(std::string_view name) {
  return "#{" + std::string{name} + "}";
}

/// Build a format from alternating literal and variable pieces so a caller
/// never hand-concatenates and forgets to escape one of them.
class FormatBuilder {
public:
  FormatBuilder& literal(std::string_view text) {
    format_ += escape_literal(text);
    return *this;
  }

  FormatBuilder& field(std::string_view name) {
    format_ += variable(name);
    return *this;
  }

  [[nodiscard]] const std::string& str() const noexcept { return format_; }

private:
  std::string format_;
};

LIBTMUX_NAMESPACE_END

include/libtmux/keys.hpp.content:
#pragma once

// Build `send-keys` arguments.
//
// tmux does not report an unknown key name: `send-keys NoSuchKey` succeeds
// silently, so a typo is invisible at the call site and shows up later as
// input that never arrived. Key names are therefore validated here, where the
// caller can still be told.
//
// Literal text takes `-l`, under which tmux interprets nothing — not key
// names, not formats. Choosing between the two is the caller's decision and is
// never inferred from the text.

#include "libtmux/abi.hpp"
#include "libtmux/expected.hpp"
#include <array>
#include <string>
#include <string_view>
#include <vector>

LIBTMUX_NAMESPACE_BEGIN

/// Why a key name could not be resolved to something tmux accepts.
enum class KeyError { empty, unknown_name };

[[nodiscard]] constexpr std::string_view to_string(KeyError error) noexcept {
  switch (error) {
  case KeyError::empty:
    return "there are no keys to send";
  case KeyError::unknown_name:
    return "tmux does not know that key name";
  }
  return "unknown key error";
}

/// Named keys tmux accepts, taken from the table in its own key-string.c at
/// the oldest supported release. Function keys are generated rather than
/// listed, and a single character is handled separately.
inline constexpr std::array kNamedKeys{
    std::string_view{"BSpace"},   std::string_view{"BTab"},
    std::string_view{"DC"},       std::string_view{"Delete"},
    std::string_view{"Down"},     std::string_view{"End"},
    std::string_view{"Enter"},    std::string_view{"Escape"},
    std::string_view{"Home"},     std::string_view{"IC"},
    std::string_view{"Insert"},   std::string_view{"KP*"},
    std::string_view{"KP+"},      std::string_view{"KP-"},
    std::string_view{"KP."},      std::string_view{"KP/"},
    std::string_view{"KP0"},      std::string_view{"KP1"},
    std::string_view{"KP2"},      std::string_view{"KP3"},
    std::string_view{"KP4"},      std::string_view{"KP5"},
    std::string_view{"KP6"},      std::string_view{"KP7"},
    std::string_view{"KP8"},      std::string_view{"KP9"},
    std::string_view{"KPEnter"},  std::string_view{"Left"},
    std::string_view{"NPage"},    std::string_view{"PPage"},
    std::string_view{"PageDown"}, std::string_view{"PageUp"},
    std::string_view{"PgDn"},     std::string_view{"PgUp"},
    std::string_view{"Right"},    std::string_view{"Space"},
    std::string_view{"Tab"},      std::string_view{"Up"},
};

[[nodiscard]] inline bool is_function_key(std::string_view name) noexcept {
  if (name.size() < 2 || name.front() != 'F') {
    return false;
  }
  const std::string_view digits = name.substr(1);
  // tmux names at most F12, so anything longer than two digits is already out
  // of range and must not be accumulated: doing so overflows before the range
  // check can reject it.
  if (digits.empty() || digits.size() > 2) {
    return false;
  }
  unsigned value = 0;
  for (const char digit : digits) {
    if (digit < '0' || digit > '9') {
      return false;
    }
    value = value * 10 + static_cast<unsigned>(digit - '0');
  }
  return value >= 1 && value <= 12;
}

/// Accept a key with any number of C-, M-, or S- modifiers.
[[nodiscard]] inline bool is_key_name(std::string_view key) noexcept {
  while (key.size() > 2 && key[1] == '-' &&
         (key[0] == 'C' || key[0] == 'M' || key[0] == 'S')) {
    key.remove_prefix(2);
  }
  if (key.empty()) {
    return false;
  }
  if (key.size() == 1) {
    // tmux takes any printable character as itself, and rejects a control
    // byte: `send-keys` with one delivers nothing.
    return static_cast<unsigned char>(key.front()) >= 0x20U;
  }
  if (is_function_key(key)) {
    return true;
  }
  for (const std::string_view named : kNamedKeys) {
    if (key == named) {
      return true;
    }
  }
  return false;
}

/// Send text exactly as written: the flag, the end of flags, and the text.
///
/// `--` is part of the fragment rather than something a caller appends, because
/// text beginning with a dash is read as another `send-keys` option without it
/// and that is not a mistake worth making twice. It was made twice: this
/// returned the flag and the text alone, `Pane::send_text` inserted the
/// separator afterwards, and `Chain::send_text` did not — so the same text
/// through the two spellings reached tmux as two different commands.
[[nodiscard]] inline expected<std::vector<std::string>, KeyError>
literal_arguments(std::string_view text) {
  if (text.empty()) {
    return unexpected(KeyError::empty);
  }
  return std::vector<std::string>{"-l", "--", std::string{text}};
}

LIBTMUX_NAMESPACE_END

