include/libtmux/legacy_lookup.hpp.content:
#pragma once

// Edge parser for the Python `field__lookup=value` spelling.
//
// This exists so a caller migrating from Python libtmux can hand a recorded
// filter string straight across. It is deliberately an edge: it produces the
// same FilterExpr the typed fields produce, so nothing downstream knows a
// string was ever involved, and the typed spelling stays the only way to write
// a new filter.

#include "libtmux/abi.hpp"
#include "libtmux/expected.hpp"
#include <span>
#include <string_view>

#include "libtmux/filter_expr.hpp"

LIBTMUX_NAMESPACE_BEGIN

/// Why a legacy lookup string could not be read.
enum class LookupParseError {
  missing_value,
  unknown_field,
  unknown_lookup,
};

/// `eq` is the implicit lookup, matching Python's bare `field=value`. An empty
/// name reaches here only from a key that carried no separator at all; a key
/// ending in one is refused before this is asked.
[[nodiscard]] inline expected<StringOp, LookupParseError>
lookup_of(std::string_view name) {
  if (name.empty() || name == "eq" || name == "exact") {
    return StringOp::equals;
  }
  if (name == "iexact") {
    return StringOp::iequals;
  }
  if (name == "contains") {
    return StringOp::contains;
  }
  if (name == "startswith") {
    return StringOp::starts_with;
  }
  if (name == "endswith") {
    return StringOp::ends_with;
  }
  return unexpected(LookupParseError::unknown_lookup);
}

/// Parse one `field[__lookup]=value` term against a caller-supplied field table.
///
/// The value is taken verbatim after the first `=`, so a value containing `=`
/// or `__` survives unchanged; only the key is split.
template <typename Entity>
[[nodiscard]] expected<FilterExpr<Entity>, LookupParseError>
parse_lookup(std::string_view term, std::span<const StringFieldHandle<Entity>> fields) {
  const std::size_t assign = term.find('=');
  if (assign == std::string_view::npos) {
    return unexpected(LookupParseError::missing_value);
  }
  const std::string_view key = term.substr(0, assign);
  const std::string_view value = term.substr(assign + 1);

  std::string_view name = key;
  std::string_view lookup;
  if (const std::size_t split = key.rfind("__"); split != std::string_view::npos) {
    name = key.substr(0, split);
    lookup = key.substr(split + 2);
    // A bare field means equality; a field that asked for a lookup and named
    // none did not. Letting `field__=value` through would read as equality,
    // which is a spelling mistake answered with a filter.
    if (lookup.empty()) {
      return unexpected(LookupParseError::unknown_lookup);
    }
  }

  const auto op = lookup_of(lookup);
  if (!op.has_value()) {
    return unexpected(op.error());
  }
  for (const StringFieldHandle<Entity>& field : fields) {
    if (field.field.name == name) {
      switch (*op) {
      case StringOp::equals:
        return field == value;
      case StringOp::iequals:
        return field.iequals(value);
      case StringOp::contains:
        return field.contains(value);
      case StringOp::starts_with:
        return field.starts_with(value);
      case StringOp::ends_with:
        return field.ends_with(value);
      }
    }
  }
  return unexpected(LookupParseError::unknown_field);
}

LIBTMUX_NAMESPACE_END

include/libtmux/lowered_node.hpp.content:
#pragma once

// One node of a lowered expression.
//
// Lowering flattens an expression into a sequence a caller can serialize or
// compile without knowing the entity type it came from. That erasure is what
// lets a relation keep its child: the child compares a different entity, so it
// cannot live in the parent's variant, but its lowered form can.

#include <string>
#include <string_view>
#include <utility>
#include <vector>

#include "libtmux/abi.hpp"

LIBTMUX_NAMESPACE_BEGIN

/// One node of a filter after it has been reduced to what tmux's `-f` format
/// language can express.
struct LoweredNode {
  enum class Kind {
    string_test,
    bool_test,
    number_test,
    begin_group,
    end_group,
    begin_negation,
    end_negation,
    begin_relation,
    end_relation,
  };

  Kind kind{Kind::string_test};
  /// Field name for a test, relation name for a relation, empty otherwise.
  std::string name;
  std::string op;
  std::string operand;
  /// The value a number_test compares against, kept as a number so a future
  /// tmux `-f` compiler does not have to parse it back out of the operand.
  long long number{};
  bool conjunction{};
  bool expected{};
  int quantifier{};
};

/// A whole lowered filter, flat: children are referenced by index rather than
/// owned, so the vector can be walked without recursion.
using LoweredExpression = std::vector<LoweredNode>;

/// Collects a lowered expression. This is the sink the relation builders use to
/// capture their child, and it is a plain value so the result is copyable.
/// Builds the flat node list a lowered expression is, keeping the indices
/// stable so a parent can reference a child it has not finished emitting.
class NodeCollector {
public:
  void string_test(std::string_view field, std::string_view op,
                   std::string_view operand) {
    LoweredNode node;
    node.kind = LoweredNode::Kind::string_test;
    node.name = std::string{field};
    node.op = std::string{op};
    node.operand = std::string{operand};
    nodes_.push_back(std::move(node));
  }
  void bool_test(std::string_view field, bool expected) {
    LoweredNode node;
    node.kind = LoweredNode::Kind::bool_test;
    node.name = std::string{field};
    node.expected = expected;
    nodes_.push_back(std::move(node));
  }
  void number_test(std::string_view field, std::string_view op, long long operand) {
    LoweredNode node;
    node.kind = LoweredNode::Kind::number_test;
    node.name = std::string{field};
    node.op = std::string{op};
    node.number = operand;
    nodes_.push_back(std::move(node));
  }
  void begin_group(bool conjunction) {
    LoweredNode node;
    node.kind = LoweredNode::Kind::begin_group;
    node.conjunction = conjunction;
    nodes_.push_back(std::move(node));
  }
  void end_group() { push(LoweredNode::Kind::end_group); }
  void begin_negation() { push(LoweredNode::Kind::begin_negation); }
  void end_negation() { push(LoweredNode::Kind::end_negation); }
  void begin_relation(std::string_view name, int quantifier) {
    LoweredNode node;
    node.kind = LoweredNode::Kind::begin_relation;
    node.name = std::string{name};
    node.quantifier = quantifier;
    nodes_.push_back(std::move(node));
  }
  void end_relation() { push(LoweredNode::Kind::end_relation); }

  [[nodiscard]] const LoweredExpression& nodes() const noexcept { return nodes_; }
  [[nodiscard]] LoweredExpression take() noexcept { return std::move(nodes_); }

private:
  void push(LoweredNode::Kind kind) {
    LoweredNode node;
    node.kind = kind;
    nodes_.push_back(std::move(node));
  }

  LoweredExpression nodes_;
};

LIBTMUX_NAMESPACE_END

include/libtmux/lowering.hpp.content:
#pragma once

// Walk a FilterExpr and hand its shape to a caller-supplied sink.
//
// The core stays dependency-free by never naming a serialization library: the
// sink is whatever the caller passes, so a JSON integration lives entirely
// outside this header. The same walk is what a future tmux `-f` compiler will
// use, which is why the node keeps its field name rather than only its
// accessor.

#include "libtmux/abi.hpp"
#include <string_view>
#include <variant>

#include "libtmux/filter_expr.hpp"
#include "libtmux/lowered_node.hpp"

LIBTMUX_NAMESPACE_BEGIN

[[nodiscard]] constexpr std::string_view name_of(StringOp op) noexcept {
  switch (op) {
  case StringOp::equals:
    return "eq";
  case StringOp::iequals:
    return "iexact";
  case StringOp::contains:
    return "contains";
  case StringOp::starts_with:
    return "startswith";
  case StringOp::ends_with:
    return "endswith";
  }
  return "eq";
}

[[nodiscard]] constexpr std::string_view name_of(NumberOp op) noexcept {
  switch (op) {
  case NumberOp::equals:
    return "eq";
  case NumberOp::not_equals:
    return "ne";
  case NumberOp::less:
    return "lt";
  case NumberOp::less_equal:
    return "lte";
  case NumberOp::greater:
    return "gt";
  case NumberOp::greater_equal:
    return "gte";
  }
  return "eq";
}

/// Replay an already-lowered child into a sink.
template <typename Sink> void replay(const LoweredExpression& nodes, Sink& sink) {
  for (const LoweredNode& node : nodes) {
    switch (node.kind) {
    case LoweredNode::Kind::string_test:
      sink.string_test(node.name, node.op, node.operand);
      break;
    case LoweredNode::Kind::bool_test:
      sink.bool_test(node.name, node.expected);
      break;
    case LoweredNode::Kind::number_test:
      sink.number_test(node.name, node.op, node.number);
      break;
    case LoweredNode::Kind::begin_group:
      sink.begin_group(node.conjunction);
      break;
    case LoweredNode::Kind::end_group:
      sink.end_group();
      break;
    case LoweredNode::Kind::begin_negation:
      sink.begin_negation();
      break;
    case LoweredNode::Kind::end_negation:
      sink.end_negation();
      break;
    case LoweredNode::Kind::begin_relation:
      sink.begin_relation(node.name, node.quantifier);
      break;
    case LoweredNode::Kind::end_relation:
      sink.end_relation();
      break;
    }
  }
}

/// A sink receives one call per node in prefix order. Groups and negations are
/// bracketed by begin/end so a sink never has to count operands itself.
template <typename Entity, typename Sink>
void lower(const FilterExpr<Entity>& expr, Sink& sink) {
  using Expr = FilterExpr<Entity>;
  std::visit(
      [&sink](const auto& node) {
        using Node = std::decay_t<decltype(node)>;
        if constexpr (std::is_same_v<Node, typename Expr::StringTest>) {
          sink.string_test(node.field.name, name_of(node.op), node.operand);
        } else if constexpr (std::is_same_v<Node, typename Expr::BoolTest>) {
          sink.bool_test(node.field.name, node.expected);
        } else if constexpr (std::is_same_v<Node, typename Expr::NumberTest>) {
          sink.number_test(node.field.name, name_of(node.op), node.operand);
        } else if constexpr (std::is_same_v<Node, typename Expr::Group>) {
          sink.begin_group(node.combine == Combine::conjunction);
          for (const Expr& operand : node.operands) {
            lower(operand, sink);
          }
          sink.end_group();
        } else if constexpr (std::is_same_v<Node, typename Expr::Negation>) {
          sink.begin_negation();
          lower(*node.operand, sink);
          sink.end_negation();
        } else {
          // The child was lowered when the relation was built, so it replays
          // here between markers and a sink sees one complete expression.
          sink.begin_relation(node.relation, node.quantifier);
          replay(node.child, sink);
          sink.end_relation();
        }
      },
      expr.node());
}

LIBTMUX_NAMESPACE_END

include/libtmux/notification.hpp.content:
#pragma once

// Events tmux emits outside guarded control reply blocks.
//
// Most are protocol notifications. A wait-capable command may also print
// delayed output or errors there, without a request identifier. Raw bytes
// preserve that ambiguity; `parse` adds borrowed views only for known
// notification shapes.

#include "libtmux/abi.hpp"

#include <chrono>
#include <cstddef>
#include <cstdint>
#include <memory>
#include <optional>
#include <span>
#include <string_view>
#include <vector>

LIBTMUX_NAMESPACE_BEGIN

/// One control event tmux sent unprompted, still as bytes.
///
/// Kept undecoded because deciding what it is costs a parse a caller may not
/// need — `ParsedNotification` is that parse.
struct Notification {
  /// Compatibility name for one outside-block control event. Unknown content
  /// is not proof that tmux emitted a notification rather than delayed output.
  std::vector<std::byte> body;
};

/// What a notification is, once its name and arguments have been read.
///
/// `unknown` is not a failure. The body may be a notification added by a newer
/// tmux or unguarded delayed command output. A kind and fields keep additions
/// from breaking an exhaustive `std::visit` in caller code.
enum class NotificationKind : std::uint8_t {
  unknown,
  output,
  extended_output,
  paused,
  resumed,
  sessions_changed,
  session_changed,
  session_renamed,
  session_window_changed,
  client_detached,
  client_session_changed,
  window_add,
  window_close,
  window_renamed,
  window_pane_changed,
  unlinked_window_add,
  unlinked_window_close,
  unlinked_window_renamed,
  pane_mode_changed,
  paste_buffer_changed,
  paste_buffer_deleted,
  subscription_changed,
  config_error,
  exit,
  layout_change,
  message,
};

[[nodiscard]] std::string_view to_string(NotificationKind kind) noexcept;

/// A notification's arguments, as views into the notification it was read from.
///
/// tmux types its arguments by prefix — `$0` a session, `@1` a window, `%2` a
/// pane — so each lands in the field it belongs to and the others stay empty.
/// `payload` is the pane bytes of an output notification, already unescaped;
/// it is empty for every other kind.
///
/// `subscription_changed` is the one kind whose first argument is never an
/// id: it is the subscription's own name (chosen by whoever called
/// `refresh-client -B`), so `text` holds that name and the changed value
/// together — `"<name> : <value>"` — once `session`/`window`/`pane` have
/// taken the ids around them.
///
/// Everything here borrows. The notification must outlive it, which is why
/// there is no overload taking a temporary.
struct ParsedNotification {
  NotificationKind kind{NotificationKind::unknown};
  std::string_view name{};
  std::string_view session{};
  std::string_view window{};
  std::string_view pane{};
  std::string_view text{};
  std::span<const std::byte> payload{};
  /// Milliseconds this output was behind when tmux wrote it. Only
  /// `extended_output` carries one.
  std::optional<std::uint64_t> age{};
};

[[nodiscard]] ParsedNotification parse(const Notification& notification);
ParsedNotification parse(Notification&&) = delete;

/// Whether `pane_id` (<code>\%N</code>) is still part of a window's arrangement,
/// reading a `layout_change` notification's own `text` — `window_layout` followed by
/// `window_visible_layout` and the window's flags (control-notify.c) — for
/// its first, whitespace-delimited token.
///
/// tmux gives no notification dedicated to a pane leaving its window; a
/// <code>\%layout-change</code> naming the pane gone is the only signal there is. This
/// answers only from the JSON layout (3.8+, and only for a connection that
/// requested it — see `Window::layout()`), which carries each pane's stable
/// id. The classic layout string encodes each pane's position by index
/// instead, which the removal of any other pane in the window renumbers, so
/// this returns `std::nullopt` there rather than guessing: killing the
/// observed pane is the one case a caller most wants an honest answer for,
/// and a stale index is exactly where a guess would be wrong.
[[nodiscard]] std::optional<bool>
layout_contains_pane(std::string_view layout_change_text, std::string_view pane_id);

namespace detail {
struct NotificationWatchState;
}

/// One independent view of outside-block events emitted after opening.
///
/// Taking from one watch never drains another watch or the Connection's legacy
/// event queue. The retained log is shared and bounded; this watch's dropped
/// count reports only events this watch actually missed.
///
/// A watch retains the stream state. It can drain already-buffered events after
/// its Connection is moved or destroyed; waits then wake as a closed stream.
class NotificationWatch final {
public:
  NotificationWatch() noexcept;
  ~NotificationWatch() noexcept;
  NotificationWatch(NotificationWatch&&) noexcept;
  NotificationWatch& operator=(NotificationWatch&&) noexcept;
  NotificationWatch(const NotificationWatch&) = delete;
  NotificationWatch& operator=(const NotificationWatch&) = delete;

  /// Everything this watch has not taken yet, returned without waiting.
  [[nodiscard]] std::vector<Notification> take_notifications();
  /// Wait for this watch to have an event, for the stream to close, or for the
  /// deadline. An empty result means one of the latter two happened.
  [[nodiscard]] std::vector<Notification>
  wait_for_notifications(std::chrono::steady_clock::time_point deadline);
  /// Readable when this watch has something to take or its stream has closed.
  /// Do not read it; taking all available events clears this watch's byte while
  /// the stream is open, and closure remains readable. `-1` means the pipe
  /// could not be created or the watch is empty/moved from.
  [[nodiscard]] int notification_fd() const noexcept;
  /// Events evicted before this watch took them, excluding events consumed by
  /// other cursors and events emitted before this watch opened.
  [[nodiscard]] std::size_t dropped_notifications() const noexcept;

private:
  friend class Connection;
  explicit NotificationWatch(
      std::unique_ptr<detail::NotificationWatchState> state) noexcept;
  std::unique_ptr<detail::NotificationWatchState> state_;
};

LIBTMUX_NAMESPACE_END

include/libtmux/options.hpp.content:
#pragma once

// Parse `show-options`-shaped output.
//
// tmux prints one option per line as `name value`, and an array option as
// `name[index] value`. The value may be quoted when it contains spaces, and an
// option with an empty value prints its name alone. Keeping all three shapes in
// one parser means callers never hand-split option output again.

#include "libtmux/abi.hpp"
#include <cstddef>
#include <optional>
#include <string>
#include <string_view>
#include <vector>

LIBTMUX_NAMESPACE_BEGIN

/// One name in the environment tmux gives processes it starts.
///
/// The value is optional because tmux distinguishes two things a listing shows
/// side by side: a name bound to a value, printed `NAME=value`, and a name
/// marked so that a child does *not* inherit it, printed `-NAME`. The second is
/// an instruction rather than an empty value, and flattening it to `""` would
/// tell a caller the child sees an empty string when it sees nothing at all.
struct EnvironmentEntry {
  std::string name;
  std::optional<std::string> value;
};

/// One option as tmux reports it: its name, its value, and the array index it
/// sits at when it is an array option.
struct OptionEntry {
  std::string name;
  /// Present only for array options, which tmux indexes sparsely: absent
  /// indexes are genuinely unset rather than empty.
  std::optional<std::size_t> index;
  std::string value;
  /// True when the value comes from a wider scope rather than being set here.
  /// `show-options -A` marks these with a trailing asterisk on the name.
  ///
  /// tmux accepts a user option whose name itself ends in an asterisk, and
  /// prints `@star* value` for one set here — which is the same shape as
  /// `status-position* bottom` for an inherited option. In a listing the two
  /// cannot be told apart, and the marker reading wins. Asking for one option
  /// by name is exact, because the name asked for settles it.
  bool inherited{};
};

/// Undo the quoting tmux applies when it prints a value.
///
/// tmux picks one of four forms, and a reader that knows only one corrupts the
/// rest: ``''`` for an empty value; double quotes when the value contains any of
/// `` #';${}``; single quotes when it contains a double quote; and otherwise no
/// quotes at all. Inside any of them the body is escaped the way `vis` does it
/// — `\t`, `\n`, `\\`, `\ooo` for a byte with no printable form — and a
/// leading tilde is escaped whether or not anything else is.
///
/// This is the inverse of tmux's own `args_escape`, so a value read here and
/// written back is the value that was there.
[[nodiscard]] inline std::string unquote(std::string_view value) {
  if (value == "''") {
    return {};
  }
  if (value.size() >= 2 && ((value.front() == '"' && value.back() == '"') ||
                            (value.front() == '\'' && value.back() == '\''))) {
    value = value.substr(1, value.size() - 2);
  }

  std::string result;
  result.reserve(value.size());
  for (std::size_t position = 0; position < value.size(); ++position) {
    if (value[position] != '\\' || position + 1U == value.size()) {
      result.push_back(value[position]);
      continue;
    }
    const char escaped = value[position + 1U];
    ++position;
    switch (escaped) {
    case 'n':
      result.push_back('\n');
      break;
    case 't':
      result.push_back('\t');
      break;
    case 'r':
      result.push_back('\r');
      break;
    case 'a':
      result.push_back('\a');
      break;
    case 'b':
      result.push_back('\b');
      break;
    case 'f':
      result.push_back('\f');
      break;
    case 'v':
      result.push_back('\v');
      break;
    case '0':
    case '1':
    case '2':
    case '3':
    case '4':
    case '5':
    case '6':
    case '7': {
      // Up to three octal digits. tmux writes all three when the byte is
      // followed by something that would otherwise extend the number.
      unsigned byte = 0;
      std::size_t digits = 0;
      while (digits < 3U && position < value.size() && value[position] >= '0' &&
             value[position] <= '7') {
        byte = (byte * 8U) + static_cast<unsigned>(value[position] - '0');
        ++position;
        ++digits;
      }
      --position;
      result.push_back(static_cast<char>(byte & 0xFFU));
      break;
    }
    default:
      // A quote, a backslash, a tilde, a dollar: itself.
      result.push_back(escaped);
      break;
    }
  }
  return result;
}

/// Parse one line. Returns nullopt for a blank line so callers can feed raw
/// output straight in.
[[nodiscard]] inline std::optional<OptionEntry> parse_option(std::string_view line) {
  if (line.empty()) {
    return std::nullopt;
  }
  const std::size_t space = line.find(' ');
  std::string_view key = line.substr(0, space);
  const std::string_view value =
      space == std::string_view::npos ? std::string_view{} : line.substr(space + 1);

  OptionEntry entry;
  // The inheritance marker is part of the listing, not of the option name.
  // Stripping it here keeps a name comparison working whether or not the
  // caller asked for inherited options.
  if (key.ends_with('*')) {
    entry.inherited = true;
    key.remove_suffix(1);
  }
  if (key.ends_with(']')) {
    if (const std::size_t open = key.rfind('['); open != std::string_view::npos) {
      const std::string_view digits = key.substr(open + 1, key.size() - open - 2);
      std::size_t index = 0;
      bool numeric = !digits.empty();
      for (const char digit : digits) {
        if (digit < '0' || digit > '9') {
          numeric = false;
          break;
        }
        index = index * 10 + static_cast<std::size_t>(digit - '0');
      }
      if (numeric) {
        entry.index = index;
        key = key.substr(0, open);
      }
    }
  }
  entry.name = std::string{key};
  entry.value = unquote(value);
  return entry;
}

[[nodiscard]] inline std::vector<OptionEntry> parse_options(std::string_view output) {
  std::vector<OptionEntry> entries;
  std::size_t position = 0;
  while (position <= output.size()) {
    const std::size_t end = output.find('\n', position);
    const std::string_view line =
        output.substr(position, end == std::string_view::npos ? std::string_view::npos
                                                              : end - position);
    if (std::optional<OptionEntry> entry = parse_option(line)) {
      entries.push_back(*std::move(entry));
    }
    if (end == std::string_view::npos) {
      break;
    }
    position = end + 1;
  }
  return entries;
}

LIBTMUX_NAMESPACE_END

include/libtmux/relations.hpp.content:
#pragma once

// Relation quantifiers over to-many and to-one links.
//
// The quantifier is named rather than inferred so a reader never has to guess
// what an empty relation means: `all_of` is satisfied by an empty relation,
// `any_of` is not, and `none_of` is. That is the vacuous-truth convention the
// standard algorithms already use, stated explicitly because getting it wrong
// silently changes which entities a filter returns.

#include "libtmux/abi.hpp"
#include <functional>
#include <ranges>
#include <string>
#include <type_traits>
#include <utility>

#include "libtmux/filter_expr.hpp"
#include "libtmux/lowering.hpp"

LIBTMUX_NAMESPACE_BEGIN

/// How a filter applies across a relation.
///
/// `all_of` and `none_of` hold for an empty relation, which is set theory
/// rather than an oversight; `any_of` is usually what a caller means.
enum class Quantifier { any_of, all_of, none_of, is };

/// Join two listings on the id one of them carries.
///
/// A relation predicate has to reach the related rows without running tmux, so
/// the caller lists both kinds once and links them here. The result borrows the
/// rows it was given, exactly as a filtered view does, so it must not outlive
/// the listing it reads.
template <typename Parent, typename Child>
[[nodiscard]] auto children_of(const std::vector<Child>& rows,
                               StringFieldHandle<Child> foreign_key,
                               StringFieldHandle<Parent> key) {
  return [&rows, foreign_key, key](const Parent& parent) {
    const std::string_view id = key.field.read(parent);
    return rows | std::views::filter([foreign_key, id](const Child& child) {
             return foreign_key.field.read(child) == id;
           });
  };
}

/// The rows are borrowed, so a listing that dies at the semicolon is refused
/// here rather than dangling inside the predicate later.
template <typename Parent, typename Child>
auto children_of(const std::vector<Child>&&, StringFieldHandle<Child>,
                 StringFieldHandle<Parent>) = delete;

/// The same join read the other way: the one row a child points at, or none.
template <typename Child, typename Parent>
[[nodiscard]] auto parent_of(const std::vector<Parent>& rows,
                             StringFieldHandle<Child> foreign_key,
                             StringFieldHandle<Parent> key) {
  return [&rows, foreign_key, key](const Child& child) -> const Parent* {
    const std::string_view id = foreign_key.field.read(child);
    for (const Parent& row : rows) {
      if (key.field.read(row) == id) {
        return &row;
      }
    }
    return nullptr;
  };
}

/// The related entity is whatever the accessor yields, so a bare flag field can
/// stand in for a predicate here exactly as it does in `matching`.
template <typename Entity, typename Read>
using RelatedMany = std::ranges::range_value_t<
    std::remove_cvref_t<std::invoke_result_t<Read, const Entity&>>>;

template <typename Entity, typename Read>
/// The entity on the far side of a to-one link, with the accessor's
/// indirection and qualifiers stripped away.
using RelatedOne = std::remove_cvref_t<
    std::remove_pointer_t<std::invoke_result_t<Read, const Entity&>>>;

/// To-many and to-one links take different accessors, so they get different
/// builders rather than one that has to compile both shapes.
template <typename Entity>
[[nodiscard]] FilterExpr<Entity> quantified(std::string name, Quantifier quantifier,
                                            auto read, auto predicate) {
  const FilterExpr<RelatedMany<Entity, decltype(read)>> test{predicate};
  auto evaluate = [quantifier, read, test](const Entity& entity) {
    // `decltype(auto)`, not `const auto&`: an accessor that returns a view by
    // value must stay non-const to be iterated at all, since a filtered view
    // caches its first position. An accessor returning a container reference
    // still binds without copying.
    decltype(auto) related = read(entity);
    const auto matches = [&test](const auto& row) { return test(row); };
    if (quantifier == Quantifier::any_of) {
      return std::ranges::any_of(related, matches);
    }
    if (quantifier == Quantifier::all_of) {
      return std::ranges::all_of(related, matches);
    }
    return std::ranges::none_of(related, matches);
  };
  NodeCollector collector;
  lower(test, collector);
  return FilterExpr<Entity>{typename FilterExpr<Entity>::RelationTest{
      std::move(name), static_cast<int>(quantifier), std::move(evaluate),
      collector.take()}};
}

template <typename Entity>
[[nodiscard]] FilterExpr<Entity> any_of(std::string name, auto read, auto predicate) {
  return quantified<Entity>(std::move(name), Quantifier::any_of, read, predicate);
}

template <typename Entity>
[[nodiscard]] FilterExpr<Entity> all_of(std::string name, auto read, auto predicate) {
  return quantified<Entity>(std::move(name), Quantifier::all_of, read, predicate);
}

template <typename Entity>
[[nodiscard]] FilterExpr<Entity> none_of(std::string name, auto read, auto predicate) {
  return quantified<Entity>(std::move(name), Quantifier::none_of, read, predicate);
}

/// An absent to-one link never satisfies `is`: a window with no active pane is
/// not a window whose active pane runs an editor.
template <typename Entity>
[[nodiscard]] FilterExpr<Entity> is(std::string name, auto read, auto predicate) {
  const FilterExpr<RelatedOne<Entity, decltype(read)>> test{predicate};
  auto evaluate = [read, test](const Entity& entity) {
    const auto* related = read(entity);
    return related != nullptr && test(*related);
  };
  NodeCollector collector;
  lower(test, collector);
  return FilterExpr<Entity>{typename FilterExpr<Entity>::RelationTest{
      std::move(name), static_cast<int>(Quantifier::is), std::move(evaluate),
      collector.take()}};
}

template <typename Child, typename Parent>
auto parent_of(const std::vector<Parent>&&, StringFieldHandle<Child>,
               StringFieldHandle<Parent>) = delete;

LIBTMUX_NAMESPACE_END

include/libtmux/server.hpp.content:
#pragma once

// The connection root.
//
// A Server names which tmux server to talk to and how to reach it. It is a
// handle: copying one costs a reference count, and every entity taken from it
// keeps the same connection alive, so a listing outlives the Server value that
// produced it.
//
// No transport type appears in this header. `run` is declared here and defined
// against a private backend, so an async or control-mode executor can replace
// that backend without changing a caller or breaking ABI.

#include "libtmux/abi.hpp"
#include "libtmux/command.hpp"
#include "libtmux/expected.hpp"
#include <chrono>
#include <concepts>
#include <cstddef>
#include <filesystem>
#include <memory>
#include <optional>
#include <span>
#include <string>
#include <string_view>
#include <type_traits>
#include <utility>
#include <vector>

#include "libtmux/async.hpp"
#include "libtmux/batch.hpp"
#include "libtmux/capabilities.hpp"
#include "libtmux/chain.hpp"
#include "libtmux/control.hpp"
#include "libtmux/entities.hpp"
#include "libtmux/layout.hpp"
#include "libtmux/options.hpp"
#include "libtmux/socket.hpp"
#include "libtmux/version.hpp"

LIBTMUX_NAMESPACE_BEGIN

class Server;

namespace detail {
/// Declared so the private constructor has exactly one way in. Defined in a
/// header this package does not install.
[[nodiscard]] Server server_over(std::shared_ptr<const Backend> backend);
} // namespace detail

/// What a caller-supplied transport tells the library about itself.
///
/// `implementation` answers what a caller may rely on, and only that. Leaving it
/// `unknown` makes `capabilities().supports(...)` answer no for every feature —
/// the library will not promise what it cannot recognise — but it does not stop
/// a typed call: `refuses` asks a separate question from `supports` rather than
/// its negation, so that a transport reaching a real tmux is not blocked for
/// being unfamiliar. Name `tmux` when the executor really does reach a POSIX
/// tmux server, so a caller asking what it may rely on gets a useful answer.
struct ExecutorOptions {
  ServerImplementation implementation{ServerImplementation::unknown};
  /// What `Server::socket_path()` reports. Informational; the library never
  /// resolves it, because the executor has already decided where it is talking.
  std::string socket_path{};
  /// The tmux this transport speaks to. Absent asks the executor by running
  /// `-V`, which a transport that only speaks tmux subcommands cannot answer —
  /// such an executor names the version here instead.
  std::optional<Version> version{};
};

/// One tmux server, addressed by the socket it listens on.
///
/// The entry point: sessions, windows and panes are read from here and carry
/// the server with them. Constructing a handle sends no command. Only a
/// startable handle may create an absent daemon; ordinary handles never do.
class Server {
public:
  /// `-S path`: the socket file, used verbatim.
  ///
  /// These report `CommandFailure`, the same type every other call reports,
  /// rather than the `SocketError` the argument builders use: a factory that
  /// failed differently is a factory nothing can be chained onto. The reason a
  /// selector was rejected is in the diagnostic, and `socket_path_arguments`
  /// still returns the enum for a caller that wants to branch on it.
  ///
  /// An observer, if given, is told about every command this server runs. It is
  /// fixed at construction because the connection is immutable afterwards, and
  /// that is what makes a Server safe to copy between threads. The policy is
  /// fixed for the same reason, and says what a call gets when it names no
  /// timeout or limit of its own.
  [[nodiscard]] static expected<Server, CommandFailure>
  at_socket_path(std::string_view path, CommandObserver observer = {},
                 ExecutionPolicy policy = {});
  /// Uses native path bytes on POSIX and UTF-8 on Windows. The exact path
  /// constraint keeps string and string-literal calls unambiguous.
  template <typename Path>
    requires std::same_as<std::remove_cvref_t<Path>, std::filesystem::path>
  [[nodiscard]] static expected<Server, CommandFailure>
  at_socket_path(Path&& path, CommandObserver observer = {},
                 ExecutionPolicy policy = {}) {
    const auto text = path.u8string();
    return at_socket_path(
        std::string_view{reinterpret_cast<const char*>(text.data()), text.size()},
        std::move(observer), policy);
  }
  /// `-L name`: resolved under tmux's socket directory, as the tmux flag does.
  [[nodiscard]] static expected<Server, CommandFailure>
  at_socket_name(std::string_view name, CommandObserver observer = {},
                 ExecutionPolicy policy = {});

  /// A socket handle that may create an absent server on its first
  /// `new_session` call or an explicit `run({"start-server"})`. `configuration`
  /// is passed to tmux as `-f`; absent
  /// preserves tmux's user configuration. Every other call remains no-start
  /// while the socket is absent. The selector and configuration are frozen in
  /// the handle, and concurrent first-session calls are serialized.
  [[nodiscard]] static expected<Server, CommandFailure>
  startable_at_socket_path(std::string_view path,
                           std::optional<std::filesystem::path> configuration,
                           CommandObserver observer = {}, ExecutionPolicy policy = {});
  template <typename Path>
    requires std::same_as<std::remove_cvref_t<Path>, std::filesystem::path>
  [[nodiscard]] static expected<Server, CommandFailure>
  startable_at_socket_path(Path&& path,
                           std::optional<std::filesystem::path> configuration,
                           CommandObserver observer = {}, ExecutionPolicy policy = {}) {
    const auto text = path.u8string();
    return startable_at_socket_path(
        std::string_view{reinterpret_cast<const char*>(text.data()), text.size()},
        std::move(configuration), std::move(observer), policy);
  }
  [[nodiscard]] static expected<Server, CommandFailure>
  startable_at_socket_name(std::string_view name,
                           std::optional<std::filesystem::path> configuration,
                           CommandObserver observer = {}, ExecutionPolicy policy = {});
  [[nodiscard]] static expected<Server, CommandFailure>
  startable_at_default(std::optional<std::filesystem::path> configuration,
                       CommandObserver observer = {}, ExecutionPolicy policy = {});

  /// The server this process is running inside.
  ///
  /// tmux exports `TMUX` to everything it starts, as
  /// `<socket path>,<server pid>,<session id>`. Only the socket path is read:
  /// the session id is stale the moment a pane moves, and a `#()` job carries
  /// no session at all — so a caller who wants the session asks tmux, rather
  /// than trusting what it inherited.
  [[nodiscard]] static expected<Server, CommandFailure>
  from_env(CommandObserver observer = {}, ExecutionPolicy policy = {});

  /// The server tmux would talk to with no `-L` or `-S` at all, which is the
  /// one a person means when they say "my tmux".
  [[nodiscard]] static expected<Server, CommandFailure>
  at_default(CommandObserver observer = {}, ExecutionPolicy policy = {});

  /// A Server over a transport the caller supplies.
  ///
  /// `BackendKind::custom` named this possibility from the first release and
  /// nothing could reach it: the interface a backend had to satisfy lived in a
  /// header this package does not install, so the only transport a consumer
  /// could get was the one that launches a subprocess per command. An executor
  /// answers one command; the library keeps session routing, batching, attach
  /// preparation and the rest on its own side rather than making them a
  /// promise.
  [[nodiscard]] static expected<Server, CommandFailure>
  over(std::shared_ptr<const CommandExecutor> executor, ExecutorOptions options = {},
       CommandObserver observer = {}, ExecutionPolicy policy = {});

  /// The local backend contract; no command runs. `tmux_version()` separately
  /// queries the executable or the connected control server.
  [[nodiscard]] ServerCapabilities capabilities() const noexcept;

  /// The resolved path pinned by this handle, including a startable path whose
  /// server has not been created yet. Empty only when the backend has no socket
  /// path representation.
  [[nodiscard]] std::string_view socket_path() const noexcept;

  /// Run one command and return its standard output.
  ///
  /// The timeout still rides on the call: how long a caller will wait is a
  /// property of what they asked for, and listing sessions does not share a
  /// deadline with attaching a client. Unset takes the server's
  /// `ExecutionPolicy`, which is thirty seconds rather than forever — a floor,
  /// not a guess at what this particular command needs.
  /// `output_limit` bounds how much of tmux's answer this call will hold. Past
  /// it the command reports `truncated` rather than returning a prefix that
  /// reads like a complete answer. Unset uses the package default, which is
  /// ample for every listing and can be too small for a long scrollback.
  [[nodiscard]] expected<std::string, CommandFailure>
  run(const CommandRequest& command,
      std::optional<std::chrono::milliseconds> timeout = {},
      std::optional<std::size_t> output_limit = {}) const;

  /// Admit one command to an explicit bounded runtime without waiting for it.
  /// A refusal before admission is returned here; an admitted command carries
  /// every later transport or tmux failure in its operation.
  [[nodiscard]] expected<CommandOperation, CommandFailure>
  try_submit(CommandRuntime& runtime, CommandRequest command,
             std::optional<std::chrono::milliseconds> timeout = {},
             std::optional<std::size_t> output_limit = {}) const;

  /// Run several commands in one invocation. tmux runs a batch fail-fast, so a
  /// failed batch is partially applied rather than rolled back, and one exit
  /// status covers the group, so tmux does not identify which member failed.
  [[nodiscard]] expected<std::string, CommandFailure>
  run_batch(const CommandBatch& batch) const;

  /// Run a chain. A chain that failed validation never reaches tmux, and says
  /// which step was wrong rather than surfacing a tmux message about it.
  [[nodiscard]] expected<std::string, CommandFailure>
  run_chain(const Chain& chain) const;

  /// Open a control-mode connection to one session.
  ///
  /// This is the streaming half of the transport: a control connection stays
  /// open, exposes guarded reply blocks in wire order, and delivers events
  /// outside those blocks. The synchronous surface above is unaffected —
  /// a caller who never opens one never pays for it. A guarded block is not a
  /// final result for commands whose work tmux completes asynchronously.
  ///
  /// Fails with `ProtocolError`, not `CommandFailure`, because that is what
  /// the `Connection` it returns speaks: an error type here that the value's
  /// own surface does not use would make the doorway disagree with the room.
  [[nodiscard]] expected<Connection, ProtocolError>
  control(std::string_view session) const;
  /// The Server supplies the socket and `session` supplies the session name;
  /// every other connection option is kept, including pane output policy.
  /// `session` matches its exact tmux session name even when it holds a "."
  /// or ":", which would otherwise be split as a window or pane target.
  [[nodiscard]] expected<Connection, ProtocolError>
  control_with_options(std::string_view session, ConnectionOptions options) const;

  /// A Server whose commands travel over held-open control clients attached to
  /// `session`, rather than one launched process each.
  ///
  /// Only where that gives the same answer. tmux can end a command's guarded
  /// block before the command has finished, so a command goes over the wire
  /// only if the typed surface issues it and tmux cannot defer it as sent —
  /// `split-window` without `-I` or `-W`, `display-message` without `-I`, the
  /// listings, and the other commands in the list in `server.cpp`, each checked
  /// against tmux's `CMD_RETURN_WAIT`. Anything else launches, as it would from
  /// this Server: a deferring command, one that acts on the client itself, an
  /// alias or an abbreviation this cannot see through. A failure reads as the
  /// same `CommandFailure` a launch would give.
  ///
  /// `connections` spreads commands over that many clients. One is enough for
  /// most callers — a connection already carries concurrent requests — and
  /// each extra client is attached to `session` and shows in `clients()`.
  ///
  /// A command with no target resolves against the control client's session
  /// rather than the most recently used one. The typed surface always names a
  /// target; a caller passing raw commands through `run` should too.
  [[nodiscard]] expected<Server, ProtocolError>
  over_control(std::string_view session, std::size_t connections = 1) const;

  /// Ask the selected subprocess executable with `tmux -V` without touching a
  /// server. The call uses this Server's execution policy.
  [[nodiscard]] expected<Version, CommandFailure> tmux_version() const;

  /// Validate the complete batch's syntax before any I/O, then query its daemon
  /// once for version-dependent names or v2 JSON layouts. No layout is applied.
  /// Only an unbound native subprocess handle may use the client version for an
  /// absent socket; failures from previously bound endpoints remain failures.
  [[nodiscard]] expected<void, LayoutFailure>
  validate_layouts(std::span<const LayoutRequest> layouts) const;

  /// Whether a server is answering on this socket. False covers every reason —
  /// no server, no socket, a tmux that would not run — because a caller who
  /// only wants to know whether to start one does not need to tell them apart.
  ///
  /// Bounded by default: the one call whose whole job is answering "can I reach
  /// this" must not be the call that hangs. A stalled socket or a stopped
  /// server answers no, in time, rather than never.
  [[nodiscard]] bool is_alive(std::chrono::milliseconds timeout = std::chrono::seconds{
                                  5}) const;
  /// The same question, keeping why the answer was no.
  [[nodiscard]] expected<void, CommandFailure>
  check_alive(std::chrono::milliseconds timeout = std::chrono::seconds{5}) const;

  /// End the server and everything in it.
  [[nodiscard]] expected<void, CommandFailure> kill() const;

  /// One snapshot each. Iterating or filtering the result never reaches tmux
  /// again; taking a current view means calling these again.
  [[nodiscard]] expected<std::vector<Session>, CommandFailure> sessions() const;
  /// tmux scopes window and pane listings to the current session unless asked
  /// for every one, so `-a` is part of the request rather than a caller's
  /// responsibility to remember.
  [[nodiscard]] expected<std::vector<Window>, CommandFailure> windows() const;
  [[nodiscard]] expected<std::vector<Pane>, CommandFailure> panes() const;
  [[nodiscard]] expected<std::vector<Client>, CommandFailure> clients() const;

  /// Block until someone signals this channel, or the deadline passes.
  ///
  /// tmux latches a signal: one sent while nobody is waiting satisfies the
  /// next wait rather than being lost. That makes signal-before-wait safe,
  /// and it also means a stale signal can release a later waiter, so a
  /// channel is worth naming for one exchange rather than reusing.
  ///
  /// A server that dies under a waiter makes tmux exit zero, which is
  /// indistinguishable from being signalled — a caller would carry on as
  /// though the other side had spoken. This reports that as a failure
  /// instead, which is the reason to prefer it over running the command.
  ///
  /// Omitting `timeout` waits with no deadline: if the channel is never
  /// signalled, this call never returns. Waiting is the whole point of the
  /// request, so that is deliberate rather than a gap — pass a timeout to
  /// bound it.
  [[nodiscard]] expected<void, CommandFailure>
  wait_for(std::string_view channel,
           std::optional<std::chrono::milliseconds> timeout = {}) const;

  /// Release whoever is waiting on the channel, or latch it for whoever
  /// waits next.
  [[nodiscard]] expected<void, CommandFailure> signal(std::string_view channel) const;

  /// Every command this tmux understands, with its alias and usage.
  ///
  /// Asking beats inferring: the supported-version range is a floor, not a
  /// description, and a distribution can ship a build with commands left
  /// out. A caller deciding whether a capability exists can look.
  [[nodiscard]] expected<std::vector<Command>, CommandFailure> commands() const;

  /// The server's cut buffers, newest first as tmux orders them. A server
  /// holding none answers with an empty list rather than a failure, like
  /// every other listing here.
  [[nodiscard]] expected<std::vector<Buffer>, CommandFailure> buffers() const;

  /// Read a file into a named buffer, and write one back out.
  ///
  /// The file is read and written by the tmux server, so the path is the
  /// server's to resolve — which matters when it is not on this machine.
  /// The bytes are not interpreted: a buffer round-tripped through a file
  /// comes back identical.
  [[nodiscard]] expected<void, CommandFailure>
  load_buffer(std::string_view name, const std::filesystem::path& from) const;
  [[nodiscard]] expected<void, CommandFailure>
  save_buffer(std::string_view name, const std::filesystem::path& to) const;

  /// Bind a key in a key table, and take a binding away again.
  ///
  /// The command is argv, not a string, so nothing here has to be quoted for
  /// tmux to take it apart again correctly.
  ///
  /// A table name containing whitespace is refused. tmux accepts one and then
  /// prints it unquoted in `list-keys`, where `-T my table X command` cannot
  /// be told apart from the table `my` bound to the key `table` — so a name
  /// that survives being listed is required, the same way a target refuses a
  /// name that cannot survive being parsed.
  ///
  /// Key names are tmux's to check: unlike `send-keys`, `bind-key` reports an
  /// unknown one — including an empty one — so there is nothing for this to
  /// add, and nothing here repeats it.
  ///
  /// `repeatable` is tmux's `-r`, letting the key repeat without the prefix
  /// being pressed again.
  [[nodiscard]] expected<void, CommandFailure>
  bind_key(std::string_view table, std::string_view key,
           const std::vector<std::string>& command, bool repeatable = false) const;

  /// Unbinding a key that was not bound succeeds; unbinding in a table that
  /// does not exist is refused. A table exists only while something is bound
  /// in it, so taking away the last binding takes the table with it.
  [[nodiscard]] expected<void, CommandFailure> unbind_key(std::string_view table,
                                                          std::string_view key) const;

  /// Run a shell command on the machine the server is on.
  ///
  /// Reports whether it ran, not what it printed. tmux hands back the output
  /// on most versions and discards it on 3.3a and 3.4, and an answer that is
  /// empty on two versions in the middle of the range is worse than no answer
  /// at all. A caller that needs the output redirects it to a file.
  ///
  /// What is uniform is the exit status: a command that fails is a failure
  /// here, carrying its code in `exit_code`.
  ///
  /// `background` is tmux's `-b`, which returns as soon as the command is
  /// started. Nothing can then be said about how it ended, so a backgrounded
  /// command that fails still reports success.
  [[nodiscard]] expected<void, CommandFailure> run_shell(std::string_view command,
                                                         bool background = false) const;

  /// Run the commands in a file, the way tmux runs a configuration file.
  ///
  /// The server reads the file, so the path is the server's to resolve. A
  /// file it cannot read is reported rather than passed over.
  /// A control-backed Server rejects execution because the file can add an
  /// unknowable number of reply blocks; `check_file` remains available there.
  [[nodiscard]] expected<void, CommandFailure>
  source_file(const std::filesystem::path& file) const;

  /// Parse the same file and report what tmux would refuse in it, running
  /// none of it. This is how a program checks a configuration it is about to
  /// apply without applying half of it first.
  [[nodiscard]] expected<void, CommandFailure>
  check_file(const std::filesystem::path& file) const;

  /// Ask tmux to expand a format, against no target but the server itself.
  ///
  /// Unguarded, unlike the entity forms: there is no target here that could
  /// have gone away. A server kept alive with no sessions still answers its
  /// own fields, and answers the session-scoped ones with nothing — which is
  /// the truth about that server, not a failure to report.
  [[nodiscard]] expected<std::string, CommandFailure>
  expand(std::string_view format) const;

  /// Put a message on the status line of every attached client, and send it
  /// to each control client as `%message`.
  ///
  /// tmux expands the text as a format, so a `#{...}` in it is substituted
  /// rather than shown. Text built from data belongs in `escape_literal`
  /// first.
  [[nodiscard]] expected<void, CommandFailure>
  show_message(std::string_view text) const;

  /// Put text in a named buffer, replacing what was there. An empty name
  /// lets tmux choose one, which is what a caller copying without caring
  /// about the name wants.
  [[nodiscard]] expected<void, CommandFailure> set_buffer(std::string_view name,
                                                          std::string_view data) const;

  /// One object by target, for a caller holding an id or a `session:window`
  /// path that came from somewhere else. The target is resolved the way tmux
  /// resolves it, so a session target names that session's active pane and the
  /// window that pane is in. A target tmux cannot resolve is reported missing.
  [[nodiscard]] expected<Session, CommandFailure>
  session(std::string_view target) const;
  [[nodiscard]] expected<Window, CommandFailure> window(std::string_view target) const;
  [[nodiscard]] expected<Pane, CommandFailure> pane(std::string_view target) const;

  /// Wait until the pane `target` names produces `wanted`. For a caller holding
  /// a target rather than a `Pane` — `Pane::wait_for_text` is the same wait
  /// without the lookup. One deadline covers both: a target that will not
  /// resolve cannot spend the whole budget and leave nothing for waiting, and
  /// `WaitPath::pane_lookup` says that is what happened.
  [[nodiscard]] expected<WaitResult, CommandFailure>
  wait_for_text(std::string_view target, std::string_view wanted,
                const WaitOptions& options = {}) const;

  /// Created detached, and returned, because tmux prints what it made. Windows
  /// psmux rejects typed creation: concurrent creators cannot prove ownership.
  [[nodiscard]] expected<Session, CommandFailure>
  new_session(std::string_view name) const;
  [[nodiscard]] expected<Session, CommandFailure>
  new_session(NewSessionOptions options) const;

  [[nodiscard]] expected<std::vector<OptionEntry>, CommandFailure>
  options(std::string_view target = {}) const;
  /// The server's own options, which are neither session nor window options
  /// and are the only ones a server without a session still has.
  [[nodiscard]] expected<std::vector<OptionEntry>, CommandFailure>
  server_options() const;
  [[nodiscard]] expected<void, CommandFailure>
  set_server_option(std::string_view name, std::string_view value) const;
  [[nodiscard]] expected<std::vector<OptionEntry>, CommandFailure>
  global_options() const;
  /// Sets the value every session inherits, rather than one session's own.
  [[nodiscard]] expected<void, CommandFailure>
  set_global_option(std::string_view name, std::string_view value) const;
  [[nodiscard]] expected<std::vector<OptionEntry>, CommandFailure>
  hooks(std::string_view target = {}) const;

  /// The environment every new process on this server starts with.
  ///
  /// Server-global here; a session has its own. tmux keeps hidden entries
  /// apart from these, and this asks for neither `-h` nor the shell form, so
  /// what comes back is the plain listing a caller means.
  [[nodiscard]] expected<std::vector<EnvironmentEntry>, CommandFailure>
  environment() const;

  /// Bind a name. An empty value binds it to empty, which is not the same as
  /// not binding it at all.
  [[nodiscard]] expected<void, CommandFailure>
  set_environment(std::string_view name, std::string_view value) const;

  /// Forget the name, so a new process inherits whatever the tmux server
  /// itself has. This is tmux's `-u`.
  [[nodiscard]] expected<void, CommandFailure>
  unset_environment(std::string_view name) const;

  /// Keep the name and take it out of what a new process inherits — tmux's
  /// `-r`, which a listing then prints as `-NAME`. Different from forgetting
  /// it: this one is remembered, as an instruction to remove.
  [[nodiscard]] expected<void, CommandFailure>
  remove_environment(std::string_view name) const;
  /// A hook set globally is not reported by the unscoped listing, so reading it
  /// back needs the scope it was set with.
  [[nodiscard]] expected<std::vector<OptionEntry>, CommandFailure> global_hooks() const;
  [[nodiscard]] expected<void, CommandFailure>
  set_global_hook(std::string_view name, std::string_view command) const;

private:
  explicit Server(std::shared_ptr<const detail::Backend> backend)
      : backend_{std::move(backend)} {}

  friend Server detail::server_over(std::shared_ptr<const detail::Backend> backend);

  /// Whether this server is known to get `feature` wrong, which is what the
  /// typed surface refuses on. Distinct from `capabilities().supports`, which a
  /// caller asks about what it may rely on.
  [[nodiscard]] bool refuses(ServerFeature feature) const noexcept;

  [[nodiscard]] expected<std::vector<OptionEntry>, CommandFailure>
  show(std::vector<std::string> request, std::string_view target) const;

  std::shared_ptr<const detail::Backend> backend_;
};

LIBTMUX_NAMESPACE_END

