#pragma once

// tmux format requests and the snapshots their output becomes.
//
// A snapshot is everything one tmux listing returned: the bytes, the rows
// parsed out of them, and the connection that produced them. Entities are a
// shared pointer to one of these plus a row index, which is why an entity can
// be copied, stored and returned with no owner to keep alive, and why
// iterating a filtered range never spawns tmux — the process ran once, when
// the snapshot was taken.
//
// A snapshot is a moment. Nothing in it changes when tmux does; asking for
// current state means taking another one.

#include "libtmux/abi.hpp"
#include "libtmux/command.hpp"
#include "libtmux/expected.hpp"
#include <chrono>
#include <cstddef>
#include <memory>
#include <optional>
#include <span>
#include <string>
#include <string_view>
#include <vector>

LIBTMUX_NAMESPACE_BEGIN

namespace detail {
/// Which tmux server to talk to, and how to run a command against it. Opaque
/// here on purpose: no transport type appears in an installed header.
class Backend;
class SnapshotFactory;
} // namespace detail

/// tmux joins requested formats with a separator that cannot appear in a format
/// name. U+241E matches the Python implementation's default so both can read the
/// same recorded output.
///
/// It is multi-byte, so every tmux this library starts is passed `-u`: a tmux
/// that believes the terminal is not UTF-8 substitutes an underscore and no row
/// splits at all.
inline constexpr std::string_view kFormatSeparator = "␞";

/// A separator absent from every format *name* is not absent from every format
/// *value*, which is the whole difficulty. `tmux rename-window 'a␞b'` is
/// accepted, and one such name used to make every window and pane listing on
/// that server fail to split — data the caller never chose breaking reads of
/// everything else.
///
/// So tmux escapes the separator before it can be mistaken for one. U+241B pairs
/// with it and is escaped in turn, which is what makes the transform reversible:
/// `␛S` is a separator that was in the value and `␛E` is an escape marker that
/// was, and neither has a second reading.
inline constexpr std::string_view kFormatEscape = "␛";

/// Build the format argument for one entity's fields, terminating every field so
/// a trailing empty value is still a value rather than a missing column.
///
/// The two substitutions nest rather than run in sequence, because tmux applies
/// the inner one to the raw value and the outer one to its result. In that order
/// a value already holding the escape marker is neutralised before the separator
/// pass can produce one; reversed, the two become indistinguishable.
///
/// `#{s/…/…/:…}` predates every tmux this library supports, and neither
/// character is a regular-expression metacharacter.
///
/// Unconditional, rather than applied only to the fields that could carry a
/// separator. Expanding the substitutions costs about 0.32us per row — a 61-row
/// listing pays 19us, against a process launch of some milliseconds — and a
/// per-field exemption list is a thing to get wrong later, once, silently.
[[nodiscard]] inline std::string
format_request(std::span<const std::string_view> fields) {
  std::string request;
  for (const std::string_view field : fields) {
    // tmux 3.2a dereferences a missing session for session_created. The
    // conditional is lazy, so an absent target still yields an empty field.
    if (field == "session_created") {
      request += "#{?session_id,";
    }
    request += "#{s/";
    request += kFormatSeparator;
    request += '/';
    request += kFormatEscape;
    request += "S/:#{s/";
    request += kFormatEscape;
    request += '/';
    request += kFormatEscape;
    request += "E/:";
    request += field;
    request += "}}";
    if (field == "session_created") {
      request += ",}";
    }
    request += kFormatSeparator;
  }
  return request;
}

/// Undo that escaping, in place.
///
/// Escaping only ever lengthens, so the decoded bytes fit where the encoded ones
/// were: the write cursor never overtakes the read cursor, nothing moves, and
/// nothing is allocated. Answers the decoded length.
///
/// An escape marker followed by anything else is left as written. Output this
/// library asked for contains no such sequence, and failing on one would mean a
/// recording could not carry a literal `␛`.
[[nodiscard]] inline std::size_t decode_value(char* begin, std::size_t size) noexcept {
  const std::string_view escape = kFormatEscape;
  std::size_t read = 0;
  std::size_t write = 0;
  while (read < size) {
    const bool marked = size - read > escape.size() &&
                        std::string_view{begin + read, escape.size()} == escape;
    const char tag = marked ? begin[read + escape.size()] : '\0';
    const std::string_view decoded = tag == 'S'   ? kFormatSeparator
                                     : tag == 'E' ? kFormatEscape
                                                  : std::string_view{};
    if (decoded.empty()) {
      begin[write++] = begin[read++];
      continue;
    }
    for (const char byte : decoded) {
      begin[write++] = byte;
    }
    read += escape.size() + 1U;
  }
  return write;
}

/// Split one tmux output line into its field values.
///
/// The trailing separator emitted by `format_request` produces one empty tail
/// element, which is dropped; a short or long row is reported rather than padded
/// so a format-name typo cannot masquerade as an empty field.
[[nodiscard]] inline bool split_row(std::string_view line, std::size_t fields,
                                    std::vector<std::string_view>& values) {
  values.clear();
  std::size_t position = 0;
  while (position <= line.size()) {
    const std::size_t next = line.find(kFormatSeparator, position);
    if (next == std::string_view::npos) {
      break;
    }
    values.push_back(line.substr(position, next - position));
    position = next + kFormatSeparator.size();
  }
  return values.size() == fields && position == line.size();
}

/// Where a tmux subcommand wants its format string. Most take `-F`;
/// `display-message` takes the format as its message argument instead, and
/// passing `-F` to it addresses a different thing entirely.
enum class FormatArgument { flag, message };

/// Owning row storage, shared by every entity taken from it.
class Snapshot {
public:
  /// Run `request` with this entity's fields appended and parse what came back.
  /// Rows are parsed once, here: entities hold views into them, so a second
  /// parse would invalidate every entity already handed out.
  [[nodiscard]] static expected<std::shared_ptr<const Snapshot>, CommandFailure>
  take(std::shared_ptr<const detail::Backend> backend,
       std::span<const std::string_view> fields, CommandRequest request,
       FormatArgument placement = FormatArgument::flag);

  [[nodiscard]] static expected<std::shared_ptr<const Snapshot>, CommandFailure>
  take_in_session(std::shared_ptr<const detail::Backend> backend,
                  std::span<const std::string_view> fields, CommandRequest request,
                  FormatArgument placement, std::string_view session_id,
                  std::string_view session_name);

  [[nodiscard]] static expected<std::shared_ptr<const Snapshot>, CommandFailure>
  take_in_session(std::shared_ptr<const detail::Backend> backend,
                  std::span<const std::string_view> fields, CommandRequest request,
                  FormatArgument placement, std::string_view session_id,
                  std::string_view session_name,
                  std::optional<std::chrono::milliseconds> timeout,
                  std::optional<std::size_t> output_limit);

  /// Output that did not come from a live server: a recording, a fixture, a
  /// test. Entities read and filter exactly as they would from a listing, and
  /// anything that would run a command reports that there is no connection.
  /// Returns null if a row does not match the fields it claims to have.
  [[nodiscard]] static std::shared_ptr<const Snapshot>
  from_recording(std::span<const std::string_view> fields, std::string output);

  Snapshot(const Snapshot&) = delete;
  Snapshot& operator=(const Snapshot&) = delete;
  Snapshot(Snapshot&&) = delete;
  Snapshot& operator=(Snapshot&&) = delete;
  ~Snapshot();

  [[nodiscard]] std::size_t index_of(std::string_view field) const noexcept;

  [[nodiscard]] const std::vector<std::vector<std::string_view>>&
  rows() const noexcept {
    return rows_;
  }

  /// The connection this came from, so an entity can act on what it describes.
  [[nodiscard]] const std::shared_ptr<const detail::Backend>& backend() const noexcept {
    return backend_;
  }

private:
  friend class detail::SnapshotFactory;

  Snapshot(std::shared_ptr<const detail::Backend> backend,
           std::vector<std::string> fields, std::string output);

  [[nodiscard]] bool parse();

  std::shared_ptr<const detail::Backend> backend_;
  /// Owned, not viewed. The entity field arrays outlive everything, but
  /// `from_recording` is public and takes whatever a caller passes: a snapshot
  /// that outlived the names it was built from would report field indices
  /// against freed memory. Every tmux format name is short enough to sit in the
  /// string itself, so owning them allocates nothing.
  std::vector<std::string> fields_;
  std::string output_;
  std::vector<std::vector<std::string_view>> rows_;
};

LIBTMUX_NAMESPACE_END

include/libtmux/socket.hpp.content:
#pragma once

// Build the connection arguments that select a tmux-compatible server.
//
// tmux selects a server either by socket name (`-L`) or by socket path
// (`-S`). A name is resolved under the socket directory, so it must be a
// single path component; a path is used verbatim. Either way the result must
// fit a UNIX domain socket address. Windows psmux supports names but has no
// `-S` transport, so socket paths are rejected there.

#include "libtmux/abi.hpp"
#include "libtmux/expected.hpp"
#include <array>
#include <cstddef>
#include <string>
#include <string_view>
#include <vector>

#if !defined(_WIN32)
#include <sys/un.h>
#endif

LIBTMUX_NAMESPACE_BEGIN

// The address this platform can hold, less its terminator.
//
// Taken from the header rather than written down: it is 107 on Linux and 103
// on macOS, and the hardcoded Linux number let a 104-byte path pass validation
// on a platform that would then refuse it at connect time, with a message
// naming neither the limit nor the path — which is the failure this check
// exists to replace.
#if defined(_WIN32)
inline constexpr std::size_t kSocketPathLimit = 0U;
#else
inline constexpr std::size_t kSocketPathLimit = sizeof(sockaddr_un::sun_path) - 1U;
#endif

/// Why a socket name or path was rejected before any server was contacted.
///
/// Length is the one that surprises: a unix socket path is bounded by the
/// platform, not by tmux.
enum class SocketError {
  empty,
  name_has_separator,
  path_too_long,
  path_unsupported,
};

[[nodiscard]] constexpr std::string_view to_string(SocketError error) noexcept {
  switch (error) {
  case SocketError::empty:
    return "the socket selector is empty";
  case SocketError::name_has_separator:
    return "a socket name cannot contain a path separator";
  case SocketError::path_unsupported:
    return "psmux does not support socket paths on Windows; use a socket name";
  case SocketError::path_too_long:
    return "the socket path does not fit a unix domain address";
  }
  return "unknown socket error";
}

/// `-L name`: a single component resolved under the socket directory.
[[nodiscard]] inline expected<std::vector<std::string>, SocketError>
socket_name_arguments(std::string_view name) {
  if (name.empty()) {
    return unexpected(SocketError::empty);
  }
  if (name.find('/') != std::string_view::npos
#if defined(_WIN32)
      || name.find('\\') != std::string_view::npos
#endif
  ) {
    return unexpected(SocketError::name_has_separator);
  }
  return std::vector<std::string>{"-L", std::string{name}};
}

/// `-S path`: used verbatim, so the address limit applies to it directly.
[[nodiscard]] inline expected<std::vector<std::string>, SocketError>
socket_path_arguments(std::string_view path) {
  if (path.empty()) {
    return unexpected(SocketError::empty);
  }
#if defined(_WIN32)
  return unexpected(SocketError::path_unsupported);
#else
  if (path.size() > kSocketPathLimit) {
    return unexpected(SocketError::path_too_long);
  }
  return std::vector<std::string>{"-S", std::string{path}};
#endif
}

LIBTMUX_NAMESPACE_END

include/libtmux/target.hpp.content:
#pragma once

// Build tmux target specifiers.
//
// tmux addresses objects either by id (`$0`, `@0`, `%0`) or by the
// `session:window.pane` path. Ids are unambiguous; the path is not, because
// `:` and `.` are its separators and a session or window name containing one
// silently re-parses as a different target. Prefer an id whenever one exists,
// and refuse to build a path from a name that cannot survive it.

#include "libtmux/abi.hpp"
#include "libtmux/expected.hpp"
#include <string>
#include <string_view>

LIBTMUX_NAMESPACE_BEGIN

/// Why a target could not be built from a name.
enum class TargetError {
  empty_name,
  /// A name holding a separator would re-parse as a different target.
  separator_in_name,
};

[[nodiscard]] constexpr std::string_view to_string(TargetError error) noexcept {
  switch (error) {
  case TargetError::empty_name:
    return "the name is empty";
  case TargetError::separator_in_name:
    return "the name contains a target separator and would address something else";
  }
  return "unknown target error";
}

/// Whether a value is written as an id, which is what decides that it needs no
/// separator validation below — not whether tmux would resolve it. `%x` is an
/// id by this test and no pane by tmux's, and both are right: it carries no
/// separator, so composing it can only produce the caller's own mistake back.
[[nodiscard]] constexpr bool is_pane_id(std::string_view value) noexcept {
  return value.size() > 1 && value.front() == '%';
}
[[nodiscard]] constexpr bool is_window_id(std::string_view value) noexcept {
  return value.size() > 1 && value.front() == '@';
}
[[nodiscard]] constexpr bool is_session_id(std::string_view value) noexcept {
  return value.size() > 1 && value.front() == '$';
}

/// Validate one path component. Ids skip validation because they contain no
/// separator by construction.
[[nodiscard]] inline expected<std::string, TargetError>
path_component(std::string_view name) {
  if (name.empty()) {
    return unexpected(TargetError::empty_name);
  }
  if (name.find_first_of(":.") != std::string_view::npos) {
    return unexpected(TargetError::separator_in_name);
  }
  return std::string{name};
}

/// A session target is its id, or its validated name.
[[nodiscard]] inline expected<std::string, TargetError>
session_target(std::string_view session) {
  if (is_session_id(session)) {
    return std::string{session};
  }
  return path_component(session);
}

/// A window target is its id, which needs no session, or `session:window`.
[[nodiscard]] inline expected<std::string, TargetError>
window_target(std::string_view session, std::string_view window) {
  if (is_window_id(window)) {
    return std::string{window};
  }
  const auto left = session_target(session);
  if (!left.has_value()) {
    return left;
  }
  const auto right = path_component(window);
  if (!right.has_value()) {
    return right;
  }
  return *left + ":" + *right;
}

/// A pane target is its id, or `session:window.pane`.
[[nodiscard]] inline expected<std::string, TargetError>
pane_target(std::string_view session, std::string_view window, std::string_view pane) {
  if (is_pane_id(pane)) {
    return std::string{pane};
  }
  const auto left = window_target(session, window);
  if (!left.has_value()) {
    return left;
  }
  const auto right = path_component(pane);
  if (!right.has_value()) {
    return right;
  }
  return *left + "." + *right;
}

LIBTMUX_NAMESPACE_END

include/libtmux/testing/capabilities.hpp.content:
#pragma once

// GoogleTest skips for behaviour that belongs to tmux rather than to this
// library, so a release that cannot provide a capability is reported as
// skipped rather than failing or going untested.
//
// `LIBTMUX_REQUIRES_TMUX` is for a capability present from some release
// onwards. `LIBTMUX_SKIP_TMUX_DEFECT` is for a defect fixed in a later
// release, where a minimum would wrongly excuse everything above it — tmux 3.4
// escapes a round-tripped option that 3.3a and 3.5 both get right.
//
// The only header here that names a test framework. Suites using another one
// take `tmux_version.hpp` and write their own skip.

#include "libtmux/testing/tmux_version.hpp"

#include <gtest/gtest.h>

/// Skip unless tmux is at least `major.minor`, naming what is missing below it.
#define LIBTMUX_REQUIRES_TMUX(major_version, minor_version, capability)                \
  do {                                                                                 \
    const ::libtmux::Version required{.major = (major_version),                        \
                                      .minor = (minor_version)};                       \
    if (::libtmux::test::running_tmux() < required) {                                  \
      GTEST_SKIP() << (capability) << " arrived in tmux " << (major_version) << '.'    \
                   << (minor_version) << "; running "                                  \
                   << ::libtmux::test::describe_running_tmux();                        \
    }                                                                                  \
  } while (false)

/// Skip while tmux is inside a closed range of releases with a known defect.
/// Both ends are inclusive, and `last` is the newest release still affected —
/// so a fix in 3.6 is written as a window ending at 3.5.
#define LIBTMUX_SKIP_TMUX_DEFECT(first_major, first_minor, last_major, last_minor,     \
                                 description)                                          \
  do {                                                                                 \
    const ::libtmux::Version first_affected{.major = (first_major),                    \
                                            .minor = (first_minor)};                   \
    const ::libtmux::Version after_affected{.major = (last_major),                     \
                                            .minor = (last_minor) + 1U};               \
    const ::libtmux::Version running = ::libtmux::test::running_tmux();                \
    if (running >= first_affected && running < after_affected) {                       \
      GTEST_SKIP() << (description) << " (tmux " << (first_major) << '.'               \
                   << (first_minor) << " through " << (last_major) << '.'              \
                   << (last_minor) << "; running "                                     \
                   << ::libtmux::test::describe_running_tmux() << ')';                 \
    }                                                                                  \
  } while (false)

include/libtmux/testing/environment_guar.content:
#pragma once

// Set a variable for the length of a scope, and put back exactly what was
// there.
//
// A socket name is not a location: tmux resolves it under `$TMUX_TMPDIR`, so a
// test that starts a server under one directory and then asks the library for
// the same name has to say which directory it means. Exporting it is what a
// caller of `tmux -L` does, and this is that, scoped.
//
// Process-global, so it is a fixture-setup tool and not something to hold
// while another thread is spawning: `setenv` racing `getenv` is undefined
// however careful the caller is.

#include <cstdlib>
#include <optional>
#include <string>
#include <string_view>

namespace libtmux::test {

/// Environment variables set for the lifetime of this value and restored on
/// destruction, including the ones that were previously unset.
class EnvironmentGuard final {
public:
  EnvironmentGuard(std::string name, std::string_view value) : name_{std::move(name)} {
    if (const char* const existing = std::getenv(name_.c_str()); existing != nullptr) {
      previous_ = existing;
    }
    ::setenv(name_.c_str(), std::string{value}.c_str(), 1);
  }

  ~EnvironmentGuard() {
    if (previous_.has_value()) {
      ::setenv(name_.c_str(), previous_->c_str(), 1);
    } else {
      ::unsetenv(name_.c_str());
    }
  }

  EnvironmentGuard(const EnvironmentGuard&) = delete;
  EnvironmentGuard& operator=(const EnvironmentGuard&) = delete;
  EnvironmentGuard(EnvironmentGuard&&) = delete;
  EnvironmentGuard& operator=(EnvironmentGuard&&) = delete;

private:
  std::string name_;
  std::optional<std::string> previous_;
};

} // namespace libtmux::test

include/libtmux/testing/scoped_server.hp.content:
#pragma once

// A private tmux server, torn down with the scope that started it.
//
// Exported as `libtmux::testing`, a target separate from the library. The
// server gets a `mkdtemp` tree of its own, `TMUX_TMPDIR` inside it, and a
// child environment with `TMUX` and `TMUX_PANE` erased, so a suite run from
// inside tmux cannot reach the surrounding server. Teardown kills the server
// and removes the tree even when a test aborts.

#include "libtmux/expected.hpp"

#include <chrono>
#include <expected>
#include <filesystem>
#include <memory>
#include <optional>
#include <string>
#include <string_view>
#include <vector>

namespace libtmux::test {

/// Whether the test server is addressed by `tmux -L name` or `tmux -S path`.
enum class SocketMode { Name, Path };

/// What teardown could not clean up, so a suite can fail loudly rather than
/// leave a server behind quietly.
struct TeardownReport {
  std::vector<std::string> messages;
};

/// Names the private tree, the socket and the `tmux -L` name, so concurrent
/// suites cannot collide and a leftover directory identifies its owner.
///
/// `label` reaches the socket path, which must fit in `sockaddr_un::sun_path`
/// — 108 bytes on Linux, 104 on macOS. Keep it under about twenty characters:
/// macOS spends roughly sixty of those on `$TMPDIR` alone, once
/// `/var/folders/...` has canonicalised to `/private/var/...`, and tmux spends
/// more again on the directory it puts the socket in. A label that overruns is
/// reported by tmux as "File name too long", naming the path.
///
/// `start` refuses one containing anything outside `[A-Za-z0-9._-]`.
struct SocketNamespace {
  std::string label{"libtmux-cxx-test"};

  [[nodiscard]] static SocketNamespace internal() { return {}; }

  /// Prefixed, so a consumer's servers are distinguishable from this library's.
  [[nodiscard]] static SocketNamespace consumer(std::string_view suite) {
    return SocketNamespace{"libtmux-cxx-" + std::string{suite}};
  }
};

/// How the test server is started and how long teardown may take.
///
/// Every member carries an initializer on purpose; see the note on the last
/// one.
struct ScopedTmuxServerOptions {
  std::filesystem::path tmux_binary{"tmux"};
  SocketMode mode{SocketMode::Path};
  std::chrono::milliseconds startup_timeout{5000};
  std::chrono::milliseconds teardown_timeout{2000};
  std::string session_name{"libtmux_test"};
  SocketNamespace socket_namespace{};
  /// Every member has an initializer: without one here, a designated
  /// initializer that stops short of it warns under
  /// `-Wmissing-field-initializers`.
  std::shared_ptr<TeardownReport> teardown_report{};
};

/// Build and edit a `NAME=VALUE` block for a child process.
/// `current_environment` copies this process's; `set_environment` replaces any
/// existing entry rather than appending; `erase_environment` removes every
/// entry for the name.
[[nodiscard]] std::vector<std::string> current_environment();
void set_environment(std::vector<std::string>& environment, std::string_view name,
                     std::string_view value);
void erase_environment(std::vector<std::string>& environment, std::string_view name);

/// Whether two paths name the same socket.
///
/// Not `std::filesystem::equivalent`: [fs.op.equivalent] makes it an *error*
/// when both paths are "other" files, and a unix domain socket is one. That is
/// not a corner a tmux suite can avoid — every socket comparison hits it — and
/// the two standard libraries disagree about it. libstdc++ implements the rule
/// and reports `ENOTSUP`; libc++ answers anyway, so the same test passes on one
/// and fails on the other. This asks the kernel for the inode instead.
///
/// The error is for a path that could not be inspected at all; a readable pair
/// that names two different sockets is a `false`, not a failure.
[[nodiscard]] libtmux::expected<bool, std::string>
same_socket_inode(const std::filesystem::path& left,
                  const std::filesystem::path& right);

/// A tmux server that exists for the lifetime of this value.
///
/// Owns a private socket and directory and kills the server on destruction, so
/// suites running at once cannot see each other's sessions. Teardown reports
/// rather than throws — a destructor that throws during a failing test hides
/// the failure.
class ScopedTmuxServer final {
public:
  static libtmux::expected<ScopedTmuxServer, std::string>
  start(ScopedTmuxServerOptions options = {});
  ~ScopedTmuxServer() noexcept;
  ScopedTmuxServer(ScopedTmuxServer&&) noexcept;
  ScopedTmuxServer& operator=(ScopedTmuxServer&&) noexcept;
  ScopedTmuxServer(const ScopedTmuxServer&) = delete;
  ScopedTmuxServer& operator=(const ScopedTmuxServer&) = delete;

  [[nodiscard]] SocketMode socket_mode() const noexcept;
  [[nodiscard]] std::optional<std::string_view> socket_name() const noexcept;
  [[nodiscard]] const std::filesystem::path& socket_path() const noexcept;
  [[nodiscard]] const std::filesystem::path& tmux_tmpdir() const noexcept;
  [[nodiscard]] std::string_view session_name() const noexcept;
  [[nodiscard]] std::string_view socket_namespace() const noexcept;
  [[nodiscard]] int server_pid() const noexcept;
  [[nodiscard]] std::vector<std::string> command_prefix() const;
  [[nodiscard]] bool is_alive() const;

  /// `NAME=VALUE` entries for a child that should reach this server and not the
  /// surrounding one: `TMUX_TMPDIR` inside the private tree, `TMUX` and
  /// `TMUX_PANE` absent.
  [[nodiscard]] std::vector<std::string> child_environment() const;

private:
  struct State;
  explicit ScopedTmuxServer(std::unique_ptr<State> state) noexcept;
  std::unique_ptr<State> state_;
};

} // namespace libtmux::test

include/libtmux/testing/tmux_version.hpp.content:
#pragma once

// The tmux the tests run against.
//
// Resolved at runtime from the same binary `ScopedTmuxServer` spawns, not
// stamped in by the build: an installed library cannot carry the consumer's
// tmux version, and a configure-time answer can name a different binary than
// the one that runs.
//
// No test framework is involved. `capabilities.hpp` layers GoogleTest skip
// macros on top; a suite on Catch2 or doctest uses this directly.

#include "libtmux/version.hpp"

#include <filesystem>
#include <string>

namespace libtmux::test {

/// Resolved once per distinct binary and cached. A tmux that cannot be run or
/// whose version cannot be parsed reports as the newest possible version, so
/// version-gated tests run and fail rather than silently skipping.
[[nodiscard]] Version running_tmux(const std::filesystem::path& tmux_binary = "tmux");

/// What `tmux -V` printed, verbatim, or "unknown".
[[nodiscard]] std::string
describe_running_tmux(const std::filesystem::path& tmux_binary = "tmux");

} // namespace libtmux::test

include/libtmux/version.hpp.content:
#pragma once

// Parse and order tmux version strings.
//
// Suffixes follow bare releases; `next-` precedes its release and `master`
// follows all. Psmux 3.3.7 occupies `revision=7`, equal to tmux 3.3g.

#include "libtmux/abi.hpp"
#include "libtmux/expected.hpp"
#include <compare>
#include <cstdint>
#include <limits>
#include <string>
#include <string_view>

LIBTMUX_NAMESPACE_BEGIN

/// Why a tmux version string could not be read.
enum class VersionError { missing_prefix, malformed };

[[nodiscard]] constexpr std::string_view to_string(VersionError error) noexcept {
  switch (error) {
  case VersionError::missing_prefix:
    return "the output does not begin with the tmux prefix";
  case VersionError::malformed:
    return "the version is not a number this can order";
  }
  return "unknown version error";
}

/// A tmux version, ordered so a feature gate can compare against a literal.
///
/// tmux marks a development build with a suffix, which orders after the
/// release it follows rather than before it.
struct Version {
  std::uint32_t major{};
  std::uint32_t minor{};
  /// 0 for a bare release, 1 for `a`, 2 for `b`, and so on. Psmux's numeric
  /// third component occupies this existing slot as the corresponding number.
  std::uint32_t revision{};
  /// A `next-` build precedes the release it leads to; `master` follows every
  /// numbered release.
  bool prerelease{false};
  bool unbounded{false};

  [[nodiscard]] constexpr std::strong_ordering
  operator<=>(const Version& other) const noexcept {
    if (unbounded != other.unbounded) {
      return unbounded ? std::strong_ordering::greater : std::strong_ordering::less;
    }
    if (const auto order = major <=> other.major; order != 0) {
      return order;
    }
    if (const auto order = minor <=> other.minor; order != 0) {
      return order;
    }
    if (const auto order = revision <=> other.revision; order != 0) {
      return order;
    }
    if (prerelease != other.prerelease) {
      return prerelease ? std::strong_ordering::less : std::strong_ordering::greater;
    }
    return std::strong_ordering::equal;
  }
  [[nodiscard]] constexpr bool operator==(const Version&) const noexcept = default;
};

/// Parse the first line of `tmux -V`, with or without its trailing newline.
[[nodiscard]] inline expected<Version, VersionError>
parse_version(std::string_view output) {
  if (const auto line_end = output.find_first_of("\r\n");
      line_end != std::string_view::npos) {
    output = output.substr(0, line_end);
  }
  constexpr std::string_view prefix = "tmux ";
  if (!output.starts_with(prefix)) {
    return unexpected(VersionError::missing_prefix);
  }
  output.remove_prefix(prefix.size());

  Version version;
  if (output == "master" || output.ends_with("-master")) {
    version.unbounded = true;
    return version;
  }
  if (output.starts_with("next-")) {
    version.prerelease = true;
    output.remove_prefix(5);
  }

  const std::size_t dot = output.find('.');
  if (dot == std::string_view::npos || dot == 0) {
    return unexpected(VersionError::malformed);
  }
  const auto digits = [](std::string_view text, std::uint32_t& out) -> bool {
    if (text.empty()) {
      return false;
    }
    out = 0;
    for (const char digit : text) {
      if (digit < '0' || digit > '9') {
        return false;
      }
      const auto value = static_cast<std::uint32_t>(digit - '0');
      if (out > (std::numeric_limits<std::uint32_t>::max() - value) / 10U) {
        return false;
      }
      out = out * 10U + value;
    }
    return true;
  };
  if (!digits(output.substr(0, dot), version.major)) {
    return unexpected(VersionError::malformed);
  }
  std::string_view rest = output.substr(dot + 1);
  std::size_t end = 0;
  while (end < rest.size() && rest[end] >= '0' && rest[end] <= '9') {
    ++end;
  }
  if (!digits(rest.substr(0, end), version.minor)) {
    return unexpected(VersionError::malformed);
  }
  const std::string_view suffix = rest.substr(end);
  if (suffix.empty()) {
    return version;
  }
  // A release candidate ranks as the release it names: `-rc`, or `-rc2` for
  // a later candidate of the same release.
  if (suffix.starts_with("-rc")) {
    std::uint32_t candidate = 0;
    if (suffix.size() == 3 || digits(suffix.substr(3), candidate)) {
      return version;
    }
    return unexpected(VersionError::malformed);
  }
  if (suffix.starts_with('.')) {
    if (!digits(suffix.substr(1), version.revision)) {
      return unexpected(VersionError::malformed);
    }
    return version;
  }
  if (suffix.size() != 1 || suffix[0] < 'a' || suffix[0] > 'z') {
    return unexpected(VersionError::malformed);
  }
  version.revision = static_cast<std::uint32_t>(suffix[0] - 'a') + 1;
  return version;
}

/// The oldest release this library supports, matching the Python package.
inline constexpr Version kMinimumSupported{.major = 3, .minor = 2, .revision = 1};

[[nodiscard]] constexpr bool is_supported(const Version& version) noexcept {
  return version >= kMinimumSupported;
}

/// This package's own version, not tmux's.
[[nodiscard]] std::string_view library_version() noexcept;

LIBTMUX_NAMESPACE_END

/// The same version, available to the preprocessor.
///
/// `library_version()` answers what was linked; these answer what was compiled
/// against, which is the question a consumer has to ask before using something
/// that may not exist yet:
///
///   `#if LIBTMUX_VERSION_MAJOR > 0 || LIBTMUX_VERSION_MINOR >= 2`
///
/// Written here rather than generated into the build directory, so that
/// `include/libtmux/` stays self-contained for anyone reading or vendoring it
/// without CMake. A test compares `LIBTMUX_VERSION_STRING` against
/// `library_version()`, which the build takes from the `VERSION` file, so the
/// two cannot drift apart unnoticed.
#define LIBTMUX_VERSION_MAJOR 0
#define LIBTMUX_VERSION_MINOR 1
#define LIBTMUX_VERSION_PATCH 0
#define LIBTMUX_VERSION_STRING "0.1.0-alpha.11"

